-- Business Agent PostgreSQL schema
-- Baseline: schema-v2 renamed v4_ai -> agent, vector extension in public.
-- Plus sanitized Group A migrations from 服务治理/06-ai (IAM / demand-create / Zeus-Trove seeds omitted).
-- Search path: agent, public

-- PostgreSQL schema for Business Agent (derived from upstream schema-v2).
-- Entity tables follow SuperEntity<Long>: id, create_time, last_modify_time, deleted.

CREATE SCHEMA IF NOT EXISTS agent;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;

SET search_path TO agent, public;

CREATE OR REPLACE FUNCTION dataagent_try_parse_jsonb(value TEXT)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
BEGIN
  RETURN value::jsonb;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;

CREATE SEQUENCE IF NOT EXISTS agent_execution_resource_id_seq AS BIGINT;
CREATE SEQUENCE IF NOT EXISTS agent_mcp_server_id_seq AS BIGINT;
CREATE SEQUENCE IF NOT EXISTS agent_mcp_tool_id_seq AS BIGINT;

CREATE TABLE IF NOT EXISTS data_agent (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  agent_type VARCHAR(100) NOT NULL DEFAULT 'commonagent',
  name VARCHAR(255) NOT NULL,
  description TEXT,
  avatar TEXT,
  status VARCHAR(50) DEFAULT 'draft',
  api_key VARCHAR(255),
  api_key_enabled BOOLEAN DEFAULT false,
  prompt TEXT,
  category VARCHAR(100),
  admin_id BIGINT,
  tags TEXT,
  runtime_timeout_seconds INTEGER DEFAULT 120,
  react_max_iterations INTEGER,
  max_model_calls INTEGER,
  max_tool_calls INTEGER,
  max_prompt_tokens BIGINT,
  chat_model_config_id BIGINT,
  temporal_policy JSONB NOT NULL DEFAULT '{"zoneId":"Asia/Shanghai","locale":"zh-CN","weekStartsOn":"MONDAY","ambiguityStrategy":"ASK"}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_visibility_policy (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL,
  conversation_scope VARCHAR(32) NOT NULL DEFAULT 'GRANT_ONLY',
  catalog_scope VARCHAR(32) NOT NULL DEFAULT 'TENANT',
  apply_mode VARCHAR(32) NOT NULL DEFAULT 'APPROVAL_REQUIRED',
  approval_mode VARCHAR(32) NOT NULL DEFAULT 'LOCAL',
  workflow_flow_code VARCHAR(128) DEFAULT 'AGENT_VISIBILITY_APPLY',
  risk_level VARCHAR(32) DEFAULT 'NORMAL',
  default_grant_days INTEGER,
  approver_config_json TEXT,
  status VARCHAR(32) NOT NULL DEFAULT 'ENABLED',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_visibility_grant (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL,
  agent_name VARCHAR(255),
  subject_type VARCHAR(32) NOT NULL,
  subject_id VARCHAR(128) NOT NULL,
  subject_name VARCHAR(255),
  source_type VARCHAR(32) NOT NULL DEFAULT 'MANUAL',
  application_id BIGINT,
  expire_time TIMESTAMP(6),
  status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_visibility_application (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL,
  agent_name VARCHAR(255),
  applicant_user_id VARCHAR(64) NOT NULL,
  applicant_nick_name VARCHAR(128),
  reason TEXT,
  grant_days INTEGER,
  status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  approval_mode VARCHAR(32) NOT NULL DEFAULT 'LOCAL',
  approver_user_id VARCHAR(64),
  approver_nick_name VARCHAR(128),
  approval_comment TEXT,
  workflow_flow_code VARCHAR(128),
  workflow_instance_id BIGINT,
  workflow_status VARCHAR(64),
  business_code VARCHAR(255),
  submit_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  finish_time TIMESTAMP(6),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS datasource (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  type VARCHAR(50) NOT NULL,
  host VARCHAR(255) NOT NULL,
  port INTEGER NOT NULL,
  database_name VARCHAR(255) NOT NULL,
  username VARCHAR(255) NOT NULL,
  password TEXT NOT NULL,
  connection_url VARCHAR(1000),
  status VARCHAR(50) DEFAULT 'inactive',
  test_status VARCHAR(50) DEFAULT 'unknown',
  description TEXT,
  creator_id BIGINT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS datasource_table (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  table_comment TEXT,
  business_name VARCHAR(255),
  enabled BOOLEAN DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS datasource_column (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  column_name VARCHAR(255) NOT NULL,
  column_type VARCHAR(255),
  column_comment TEXT,
  business_name VARCHAR(255),
  sample_values TEXT,
  enabled BOOLEAN DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS datasource_permission_rule (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  column_name VARCHAR(255) NOT NULL,
  data_ref_type VARCHAR(64) NOT NULL,
  java_type VARCHAR(32) DEFAULT 'String',
  scope_type INTEGER,
  enabled BOOLEAN DEFAULT true,
  missing_policy VARCHAR(32) DEFAULT 'ALLOW_ON_MISSING',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS business_knowledge (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_id BIGINT NOT NULL,
  superseded_by_id BIGINT,
  business_term VARCHAR(255) NOT NULL,
  description TEXT,
  synonyms TEXT,
  is_recall BOOLEAN DEFAULT true,
  embedding_status VARCHAR(20),
  error_msg VARCHAR(255),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  CONSTRAINT ck_business_knowledge_superseded_self
    CHECK (superseded_by_id IS NULL OR superseded_by_id <> id)
);

CREATE TABLE IF NOT EXISTS skill_knowledge (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_id BIGINT NOT NULL,
  superseded_by_id BIGINT,
  title VARCHAR(255) NOT NULL,
  type VARCHAR(50) NOT NULL,
  question TEXT,
  content TEXT,
  is_recall BOOLEAN DEFAULT true,
  embedding_status VARCHAR(20),
  error_msg VARCHAR(255),
  source_filename VARCHAR(500),
  file_path VARCHAR(500),
  file_size BIGINT,
  file_type VARCHAR(255),
  splitter_type VARCHAR(50) DEFAULT 'recursive',
  is_resource_cleaned BOOLEAN DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  CONSTRAINT ck_skill_knowledge_superseded_self
    CHECK (superseded_by_id IS NULL OR superseded_by_id <> id),
  CONSTRAINT ck_skill_knowledge_type CHECK (type IN ('DOCUMENT', 'QA', 'FAQ'))
);

CREATE TABLE IF NOT EXISTS semantic_model (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_id BIGINT NOT NULL,
  superseded_by_id BIGINT,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  column_name VARCHAR(255) NOT NULL DEFAULT '',
  business_name VARCHAR(255) NOT NULL DEFAULT '',
  synonyms TEXT,
  business_description TEXT,
  column_comment VARCHAR(255),
  data_type VARCHAR(255) NOT NULL DEFAULT '',
  status BOOLEAN NOT NULL DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  CONSTRAINT ck_semantic_model_superseded_self
    CHECK (superseded_by_id IS NULL OR superseded_by_id <> id)
);

CREATE TABLE IF NOT EXISTS logical_relation (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  source_table_name VARCHAR(100) NOT NULL,
  source_column_name VARCHAR(100) NOT NULL,
  target_table_name VARCHAR(100) NOT NULL,
  target_column_name VARCHAR(100) NOT NULL,
  relation_type VARCHAR(20),
  description VARCHAR(500),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS skill_datasource (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_id BIGINT NOT NULL,
  datasource_id BIGINT NOT NULL REFERENCES datasource(id) ON DELETE CASCADE,
  is_active BOOLEAN DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS agent_preset_question (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  question TEXT NOT NULL,
  sort_order INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_skill (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  skill_code VARCHAR(128) NOT NULL,
  skill_name VARCHAR(128) NOT NULL,
  description TEXT,
  category VARCHAR(128),
  scope VARCHAR(32) NOT NULL DEFAULT 'TENANT',
  skill_kind VARCHAR(32) NOT NULL,
  execution_mode VARCHAR(32) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  latest_draft_version_id BIGINT,
  published_version_id BIGINT,
  display_order INTEGER NOT NULL DEFAULT 0,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_data_agent_skill_scope CHECK (scope = 'TENANT'),
  CONSTRAINT ck_data_agent_skill_kind CHECK (skill_kind IN ('QA', 'QUERY', 'ACTION', 'ORCHESTRATION')),
  CONSTRAINT ck_data_agent_skill_execution_mode CHECK (execution_mode IN ('KNOWLEDGE', 'DETERMINISTIC', 'REACT', 'FLOW')),
  CONSTRAINT ck_data_agent_skill_kind_execution_mode CHECK (
    (skill_kind = 'QA' AND execution_mode = 'KNOWLEDGE')
    OR (skill_kind = 'QUERY' AND execution_mode IN ('DETERMINISTIC', 'REACT'))
    OR (skill_kind IN ('ACTION', 'ORCHESTRATION') AND execution_mode = 'FLOW')
  )
);

CREATE TABLE IF NOT EXISTS data_agent_skill_version (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  skill_id BIGINT NOT NULL REFERENCES data_agent_skill(id) ON DELETE RESTRICT,
  skill_name VARCHAR(128) NOT NULL,
  description TEXT,
  category VARCHAR(128),
  display_order INTEGER NOT NULL DEFAULT 0,
  skill_kind VARCHAR(32) NOT NULL,
  execution_mode VARCHAR(32) NOT NULL,
  version_no INTEGER NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  skill_markdown TEXT,
  route_rules JSONB NOT NULL DEFAULT
    '{"exact":[],"phrases":[],"aliases":[],"positiveExamples":[],"negativeExamples":[],"hardExcludes":[]}'::jsonb,
  knowledge_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  react_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  flow_definition JSONB,
  variables_schema JSONB NOT NULL DEFAULT '{}'::jsonb,
  flow_runtime_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  flow_policy_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  resource_requirement JSONB NOT NULL DEFAULT '{}'::jsonb,
  input_schema JSONB NOT NULL DEFAULT '{}'::jsonb,
  output_schema JSONB NOT NULL DEFAULT '{}'::jsonb,
  datasource_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  semantic_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  runtime_config JSONB NOT NULL DEFAULT '{}'::jsonb,
  checksum VARCHAR(64),
  published_at TIMESTAMP,
  published_by VARCHAR(64),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_data_agent_skill_version_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'RETIRED')),
  CONSTRAINT ck_data_agent_skill_version_kind
    CHECK (skill_kind IN ('QA', 'QUERY', 'ACTION', 'ORCHESTRATION')),
  CONSTRAINT ck_data_agent_skill_version_execution_mode
    CHECK (execution_mode IN ('KNOWLEDGE', 'DETERMINISTIC', 'REACT', 'FLOW')),
  CONSTRAINT ck_data_agent_skill_version_kind_execution_mode CHECK (
    (skill_kind = 'QA' AND execution_mode = 'KNOWLEDGE')
    OR (skill_kind = 'QUERY' AND execution_mode IN ('DETERMINISTIC', 'REACT'))
    OR (skill_kind IN ('ACTION', 'ORCHESTRATION') AND execution_mode = 'FLOW')
  ),
  CONSTRAINT uk_data_agent_skill_version_id_skill UNIQUE (id, skill_id)
);

ALTER TABLE data_agent_skill
  ADD CONSTRAINT fk_data_agent_skill_latest_draft
  FOREIGN KEY (latest_draft_version_id, id) REFERENCES data_agent_skill_version(id, skill_id) ON DELETE RESTRICT;
ALTER TABLE data_agent_skill
  ADD CONSTRAINT fk_data_agent_skill_published
  FOREIGN KEY (published_version_id, id) REFERENCES data_agent_skill_version(id, skill_id) ON DELETE RESTRICT;

ALTER TABLE skill_datasource
  ADD CONSTRAINT fk_skill_datasource_skill
  FOREIGN KEY (skill_id) REFERENCES data_agent_skill(id) ON DELETE RESTRICT;
ALTER TABLE semantic_model
  ADD CONSTRAINT fk_semantic_model_skill
  FOREIGN KEY (skill_id) REFERENCES data_agent_skill(id) ON DELETE RESTRICT;
ALTER TABLE business_knowledge
  ADD CONSTRAINT fk_business_knowledge_skill
  FOREIGN KEY (skill_id) REFERENCES data_agent_skill(id) ON DELETE RESTRICT;
ALTER TABLE skill_knowledge
  ADD CONSTRAINT fk_skill_knowledge_skill
  FOREIGN KEY (skill_id) REFERENCES data_agent_skill(id) ON DELETE RESTRICT;
ALTER TABLE semantic_model
  ADD CONSTRAINT fk_semantic_model_superseded_by
  FOREIGN KEY (superseded_by_id) REFERENCES semantic_model(id) ON DELETE RESTRICT;
ALTER TABLE business_knowledge
  ADD CONSTRAINT fk_business_knowledge_superseded_by
  FOREIGN KEY (superseded_by_id) REFERENCES business_knowledge(id) ON DELETE RESTRICT;
ALTER TABLE skill_knowledge
  ADD CONSTRAINT fk_skill_knowledge_superseded_by
  FOREIGN KEY (superseded_by_id) REFERENCES skill_knowledge(id) ON DELETE RESTRICT;

CREATE TABLE IF NOT EXISTS data_agent_skill_binding (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  skill_id BIGINT NOT NULL,
  pinned_skill_version_id BIGINT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 0,
  enabled BOOLEAN NOT NULL DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  CONSTRAINT fk_data_agent_skill_binding_version
    FOREIGN KEY (pinned_skill_version_id, skill_id)
    REFERENCES data_agent_skill_version(id, skill_id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS agent_execution_resource (
  id BIGINT NOT NULL DEFAULT nextval('agent_execution_resource_id_seq'::regclass) PRIMARY KEY,
  resource_key VARCHAR(256) NOT NULL UNIQUE,
  resource_name VARCHAR(128),
  resource_type VARCHAR(32) NOT NULL,
  server_code VARCHAR(128),
  service_name VARCHAR(128),
  base_url VARCHAR(512),
  tool_name VARCHAR(128),
  endpoint_url VARCHAR(512),
  http_method VARCHAR(16) DEFAULT 'POST',
  header_template TEXT,
  auth_type VARCHAR(32),
  credential_ref VARCHAR(128),
  param_mapping TEXT,
  request_template TEXT,
  response_mapping TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  display_order INTEGER NOT NULL DEFAULT 0,
  ext_config TEXT,
  deleted BOOLEAN NOT NULL DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS agent_execution_resource_version (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  resource_id BIGINT NOT NULL REFERENCES agent_execution_resource(id) ON DELETE RESTRICT,
  resource_key VARCHAR(256) NOT NULL,
  version_no INTEGER NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  access_mode VARCHAR(16) NOT NULL,
  exposure_mode VARCHAR(32) NOT NULL,
  permission_code VARCHAR(256),
  confirm_required BOOLEAN NOT NULL DEFAULT false,
  idempotency_required BOOLEAN NOT NULL DEFAULT false,
  timeout_ms INTEGER NOT NULL DEFAULT 30000,
  input_schema JSONB NOT NULL DEFAULT '{}'::jsonb,
  output_schema JSONB NOT NULL DEFAULT '{}'::jsonb,
  runtime_param_mappings JSONB NOT NULL DEFAULT '{}'::jsonb,
  response_mappings JSONB NOT NULL DEFAULT '{}'::jsonb,
  sensitive_fields JSONB NOT NULL DEFAULT '[]'::jsonb,
  snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  published_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_agent_execution_resource_version_access CHECK (access_mode IN ('READ', 'WRITE')),
  CONSTRAINT ck_agent_execution_resource_version_exposure CHECK (exposure_mode IN ('MODEL', 'FLOW_ONLY')),
  CONSTRAINT ck_agent_execution_resource_version_write_exposure CHECK (NOT (access_mode = 'WRITE' AND exposure_mode = 'MODEL'))
);

CREATE TABLE IF NOT EXISTS data_agent_skill_tool_ref (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  skill_version_id BIGINT NOT NULL REFERENCES data_agent_skill_version(id) ON DELETE CASCADE,
  resource_version_id BIGINT NOT NULL REFERENCES agent_execution_resource_version(id) ON DELETE RESTRICT,
  resource_key VARCHAR(256) NOT NULL,
  usage VARCHAR(256),
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  display_order INTEGER NOT NULL DEFAULT 0,
  ext_config TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_flow_instance (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE RESTRICT,
  skill_id BIGINT NOT NULL,
  skill_version_id BIGINT NOT NULL,
  skill_code VARCHAR(128) NOT NULL,
  session_id BIGINT,
  thread_id VARCHAR(128) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  status VARCHAR(32) NOT NULL,
  current_node_id VARCHAR(128),
  context_data JSONB NOT NULL DEFAULT '{}'::jsonb,
  waiting_payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  idempotency_key VARCHAR(256),
  lock_version INTEGER NOT NULL DEFAULT 0,
  input_hash VARCHAR(64),
  context_revision BIGINT NOT NULL DEFAULT 0,
  resume_version INTEGER NOT NULL DEFAULT 0,
  last_runtime_request_id VARCHAR(128),
  error_code VARCHAR(128),
  error_message TEXT,
  expires_at TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT fk_data_agent_flow_instance_skill_version
    FOREIGN KEY (skill_version_id, skill_id)
    REFERENCES data_agent_skill_version(id, skill_id) ON DELETE RESTRICT,
  CONSTRAINT ck_data_agent_flow_instance_status CHECK (
    status IN ('RUNNING', 'PROCESSING', 'WAITING', 'EXECUTING', 'UNKNOWN', 'SUCCEEDED', 'FAILED', 'SUSPENDED', 'CANCELLED')
  )
);

ALTER TABLE data_agent_flow_instance ADD COLUMN IF NOT EXISTS input_hash VARCHAR(64);
ALTER TABLE data_agent_flow_instance ADD COLUMN IF NOT EXISTS context_revision BIGINT NOT NULL DEFAULT 0;
ALTER TABLE data_agent_flow_instance ADD COLUMN IF NOT EXISTS resume_version INTEGER NOT NULL DEFAULT 0;
COMMENT ON COLUMN data_agent_flow_instance.input_hash IS '最近一次已成功处理的用户输入 SHA-256（hex）；等待恢复时相同 hash 不重复抽取';
COMMENT ON COLUMN data_agent_flow_instance.context_revision IS '上下文修订号，与 context_data /runtime/contextRevision 同步';
COMMENT ON COLUMN data_agent_flow_instance.resume_version IS '恢复版本号，进入 WAITING 递增；过期版本的恢复请求被拒绝';

CREATE TABLE IF NOT EXISTS data_agent_flow_event (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  flow_instance_id BIGINT NOT NULL REFERENCES data_agent_flow_instance(id) ON DELETE CASCADE,
  runtime_request_id VARCHAR(128),
  event_key VARCHAR(128),
  node_id VARCHAR(128),
  node_type VARCHAR(32),
  event_type VARCHAR(32) NOT NULL,
  status VARCHAR(32) NOT NULL,
  duration_ms BIGINT,
  input_data JSONB NOT NULL DEFAULT '{}'::jsonb,
  output_data JSONB NOT NULL DEFAULT '{}'::jsonb,
  error_code VARCHAR(128),
  error_message TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_data_agent_flow_event_event_key CHECK (
    event_key IS NULL OR BTRIM(event_key) <> ''
  )
);

CREATE TABLE IF NOT EXISTS agent_mcp_server (
  id BIGINT NOT NULL DEFAULT nextval('agent_mcp_server_id_seq'::regclass) PRIMARY KEY,
  server_code VARCHAR(128) NOT NULL UNIQUE,
  service_name VARCHAR(128),
  endpoint_path VARCHAR(256) NOT NULL DEFAULT '/mcp',
  transport_type VARCHAR(64) NOT NULL DEFAULT 'streamable-http',
  base_url VARCHAR(512),
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  metadata TEXT,
  deleted BOOLEAN NOT NULL DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS agent_mcp_tool (
  id BIGINT NOT NULL DEFAULT nextval('agent_mcp_tool_id_seq'::regclass) PRIMARY KEY,
  server_code VARCHAR(128) NOT NULL,
  tool_name VARCHAR(128) NOT NULL,
  tool_title VARCHAR(128),
  description TEXT,
  input_schema TEXT,
  output_schema TEXT,
  permission_policy TEXT,
  risk_level VARCHAR(32),
  readonly BOOLEAN,
  confirm_required BOOLEAN,
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  metadata TEXT,
  deleted BOOLEAN NOT NULL DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_agent_mcp_tool UNIQUE (server_code, tool_name)
);

ALTER SEQUENCE agent_execution_resource_id_seq OWNED BY agent_execution_resource.id;
ALTER SEQUENCE agent_mcp_server_id_seq OWNED BY agent_mcp_server.id;
ALTER SEQUENCE agent_mcp_tool_id_seq OWNED BY agent_mcp_tool.id;

COMMENT ON TABLE agent_execution_resource IS '平台执行资源工具目录';
COMMENT ON TABLE data_agent_skill IS 'Skill catalog';
COMMENT ON TABLE data_agent_skill_version IS 'Immutable published Skill versions';
COMMENT ON COLUMN data_agent_skill.skill_kind IS 'Skill类型：QA、QUERY、ACTION、ORCHESTRATION';
COMMENT ON COLUMN data_agent_skill.execution_mode IS 'Skill执行模式：KNOWLEDGE、DETERMINISTIC、REACT、FLOW';
COMMENT ON COLUMN data_agent_skill_version.skill_kind IS '版本快照Skill类型：QA、QUERY、ACTION、ORCHESTRATION';
COMMENT ON COLUMN data_agent_skill_version.execution_mode IS '版本快照执行模式：KNOWLEDGE、DETERMINISTIC、REACT、FLOW';
COMMENT ON COLUMN data_agent_skill_version.datasource_config IS '发布版本的数据源、表和字段白名单快照';
COMMENT ON COLUMN data_agent_skill_version.semantic_config IS '发布版本的语义模型引用快照';
COMMENT ON COLUMN data_agent_skill_version.knowledge_config IS '发布版本的业务知识引用和召回配置快照';
COMMENT ON COLUMN data_agent_skill_version.runtime_config IS '发布版本的运行策略快照';
COMMENT ON COLUMN semantic_model.superseded_by_id IS '指向替代该资源的新语义模型；NULL 表示当前编辑态资源';
COMMENT ON COLUMN business_knowledge.superseded_by_id IS '指向替代该资源的新业务知识；NULL 表示当前编辑态资源';
COMMENT ON TABLE agent_execution_resource_version IS 'Immutable tool versions';
COMMENT ON TABLE data_agent_skill_tool_ref IS 'Skill version to pinned tool version references';
COMMENT ON TABLE data_agent_flow_instance IS 'Persistent deterministic FLOW state';
COMMENT ON TABLE data_agent_flow_event IS 'FLOW node event audit log';
COMMENT ON COLUMN agent_execution_resource.resource_type IS '资源类型：MCP_TOOL、INTERNAL_API、HTTP、WEBHOOK';
COMMENT ON COLUMN agent_execution_resource.credential_ref IS '凭据别名或密钥引用，不保存明文 key/token';
COMMENT ON TABLE agent_mcp_server IS 'MCP 服务目录';
COMMENT ON TABLE agent_mcp_tool IS 'MCP 工具同步目录';

CREATE TABLE IF NOT EXISTS model_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider VARCHAR(255) NOT NULL,
  base_url VARCHAR(255) NOT NULL,
  api_key TEXT NOT NULL,
  model_name VARCHAR(255) NOT NULL,
  endpoint_dialect VARCHAR(40) NOT NULL DEFAULT 'OPENAI_COMPATIBLE',
  capability_profile VARCHAR(40) NOT NULL DEFAULT 'AUTO',
  reasoning_protocol VARCHAR(40) NOT NULL DEFAULT 'AUTO',
  reasoning_mode VARCHAR(20) NOT NULL DEFAULT 'AUTO',
  reasoning_level VARCHAR(20),
  reasoning_budget_tokens BIGINT,
  token_limit_mode VARCHAR(40),
  temperature_policy VARCHAR(20),
  structured_output_mode VARCHAR(40) NOT NULL DEFAULT 'AUTO',
  preserved_reasoning_policy VARCHAR(20) NOT NULL DEFAULT 'DROP',
  temperature NUMERIC(10,2) DEFAULT 0.00,
  is_active BOOLEAN DEFAULT false,
  max_tokens BIGINT DEFAULT 2000,
  context_window_tokens BIGINT DEFAULT 32768,
  model_type VARCHAR(40) NOT NULL DEFAULT 'CHAT',
  completions_path VARCHAR(255),
  embeddings_path VARCHAR(255),
  transcriptions_path VARCHAR(255),
  support_vision BOOLEAN DEFAULT false,
  proxy_enabled BOOLEAN DEFAULT false,
  proxy_host VARCHAR(255),
  proxy_port INTEGER,
  proxy_username VARCHAR(255),
  proxy_password TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  CONSTRAINT model_config_endpoint_dialect_ck CHECK (
    endpoint_dialect IN (
      'OPENAI_COMPATIBLE', 'DASHSCOPE_NATIVE', 'STEPFUN_NATIVE', 'DEEPSEEK_NATIVE',
      'ZHIPU_NATIVE', 'MOONSHOT_NATIVE', 'CUSTOM')),
  CONSTRAINT model_config_capability_profile_ck CHECK (
    capability_profile IN (
      'AUTO', 'NO_REASONING', 'QWEN_HYBRID', 'QWEN_THINKING_ONLY',
      'STEPFUN_REASONING', 'DEEPSEEK_THINKING', 'GLM_THINKING',
      'KIMI_K3_REASONING', 'KIMI_K26_THINKING', 'KIMI_K27_CODE')),
  CONSTRAINT model_config_reasoning_protocol_ck CHECK (
    reasoning_protocol IN (
      'AUTO', 'REASONING_EFFORT', 'THINKING_OBJECT', 'THINKING_OBJECT_WITH_EFFORT',
      'ENABLE_THINKING', 'ENABLE_THINKING_ONLY', 'NONE')),
  CONSTRAINT model_config_reasoning_mode_ck CHECK (
    reasoning_mode IN ('AUTO', 'ENABLED', 'DISABLED')),
  CONSTRAINT model_config_reasoning_level_ck CHECK (
    reasoning_level IS NULL OR reasoning_level IN (
      'NONE', 'MINIMAL', 'LOW', 'MEDIUM', 'HIGH', 'XHIGH', 'MAX')),
  CONSTRAINT model_config_reasoning_budget_tokens_ck CHECK (
    reasoning_budget_tokens IS NULL
    OR reasoning_budget_tokens BETWEEN 1 AND 2147483647),
  CONSTRAINT model_config_token_limit_mode_ck CHECK (
    token_limit_mode IS NULL OR token_limit_mode IN (
      'MAX_TOKENS', 'MAX_COMPLETION_TOKENS')),
  CONSTRAINT model_config_temperature_policy_ck CHECK (
    temperature_policy IS NULL OR temperature_policy IN ('SEND', 'OMIT')),
  CONSTRAINT model_config_structured_output_mode_ck CHECK (
    structured_output_mode IN (
      'AUTO', 'STRICT_JSON_SCHEMA', 'JSON_OBJECT', 'PROMPT_JSON')),
  CONSTRAINT model_config_preserved_reasoning_policy_ck CHECK (
    preserved_reasoning_policy = 'DROP')
);

CREATE TABLE IF NOT EXISTS data_agent_model_structured_capability (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  model_config_id BIGINT NOT NULL REFERENCES model_config(id) ON DELETE CASCADE,
  task_profile VARCHAR(40) NOT NULL,
  protocol VARCHAR(40) NOT NULL,
  model_fingerprint VARCHAR(64) NOT NULL,
  compiler_version VARCHAR(64) NOT NULL,
  probe_version VARCHAR(64) NOT NULL,
  state VARCHAR(24) NOT NULL DEFAULT 'NOT_PROBED',
  claim_lease VARCHAR(64),
  lease_until TIMESTAMP,
  checked_at TIMESTAMP,
  expires_at TIMESTAMP,
  next_attempt_at TIMESTAMP,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  latency_ms BIGINT,
  platform_tokens BIGINT,
  failure_code VARCHAR(128),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_data_agent_model_structured_capability_profile
    CHECK (task_profile IN ('FLOW_PATCH_V1')),
  CONSTRAINT ck_data_agent_model_structured_capability_protocol
    CHECK (protocol IN ('FUNCTION_CALL', 'STRICT_JSON_SCHEMA', 'JSON_OBJECT')),
  CONSTRAINT ck_data_agent_model_structured_capability_state
    CHECK (state IN ('NOT_PROBED', 'SUPPORTED', 'UNSUPPORTED', 'UNAVAILABLE', 'STALE')),
  CONSTRAINT ck_data_agent_model_structured_capability_attempt_count CHECK (attempt_count >= 0),
  CONSTRAINT ck_data_agent_model_structured_capability_latency CHECK (latency_ms IS NULL OR latency_ms >= 0),
  CONSTRAINT ck_data_agent_model_structured_capability_tokens CHECK (platform_tokens IS NULL OR platform_tokens >= 0),
  CONSTRAINT uk_data_agent_model_structured_capability_version
    UNIQUE (model_config_id, task_profile, protocol, model_fingerprint, compiler_version, probe_version)
);

CREATE INDEX IF NOT EXISTS data_agent_model_structured_capability_idx_due
  ON data_agent_model_structured_capability(state, next_attempt_at, lease_until)
  WHERE deleted = false;

CREATE TABLE IF NOT EXISTS agent_model_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  model_config_id BIGINT NOT NULL REFERENCES model_config(id) ON DELETE CASCADE,
  is_default BOOLEAN DEFAULT false,
  user_selectable BOOLEAN DEFAULT true,
  enabled BOOLEAN DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_route_profile (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_name VARCHAR(128) NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'BUILDING', 'READY', 'ACTIVE', 'RETIRED', 'FAILED')),
  route_model_config_id BIGINT REFERENCES model_config(id),
  route_model_probe_state VARCHAR(16) NOT NULL DEFAULT 'NOT_PROBED'
    CHECK (route_model_probe_state IN ('NOT_PROBED', 'SUPPORTED', 'UNSUPPORTED', 'UNAVAILABLE', 'STALE')),
  route_model_protocol VARCHAR(16) NOT NULL DEFAULT 'NONE'
    CHECK (route_model_protocol IN ('FUNCTION_CALL', 'STRICT_SCHEMA', 'JSON_OBJECT', 'PROMPT_JSON', 'NONE')),
  route_model_fingerprint VARCHAR(128),
  route_model_probe_version VARCHAR(32),
  route_model_checked_at TIMESTAMP,
  route_model_latency_ms BIGINT CHECK (route_model_latency_ms IS NULL OR route_model_latency_ms >= 0),
  route_model_failure_code VARCHAR(64),
  route_model_runtime_ready BOOLEAN NOT NULL DEFAULT false,
  embedding_model_config_id BIGINT REFERENCES model_config(id),
  embedding_probe_state VARCHAR(16) NOT NULL DEFAULT 'NOT_PROBED'
    CHECK (embedding_probe_state IN ('NOT_PROBED', 'SUPPORTED', 'UNSUPPORTED', 'UNAVAILABLE', 'STALE')),
  embedding_checked_at TIMESTAMP,
  embedding_latency_ms BIGINT CHECK (embedding_latency_ms IS NULL OR embedding_latency_ms >= 0),
  embedding_probe_version VARCHAR(32),
  embedding_failure_code VARCHAR(64),
  lexical_auto_select_enabled BOOLEAN NOT NULL DEFAULT true,
  semantic_recall_enabled BOOLEAN NOT NULL DEFAULT true,
  semantic_auto_select_enabled BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT data_agent_route_profile_semantic_auto_requires_recall_ck
    CHECK (NOT semantic_auto_select_enabled OR semantic_recall_enabled),
  model_disambiguation_enabled BOOLEAN NOT NULL DEFAULT false,
  lexical_min_score INTEGER NOT NULL DEFAULT 70 CHECK (lexical_min_score >= 0),
  lexical_min_gap INTEGER NOT NULL DEFAULT 15 CHECK (lexical_min_gap >= 0),
  vector_recall_threshold NUMERIC(8,6) NOT NULL CHECK (vector_recall_threshold BETWEEN 0 AND 1),
  vector_auto_select_threshold NUMERIC(8,6) NOT NULL CHECK (vector_auto_select_threshold BETWEEN 0 AND 1),
  vector_min_gap NUMERIC(8,6) NOT NULL CHECK (vector_min_gap BETWEEN 0 AND 1),
  model_confidence_threshold NUMERIC(8,6) NOT NULL CHECK (model_confidence_threshold BETWEEN 0 AND 1),
  embedding_fingerprint VARCHAR(128),
  embedding_dimension INTEGER CHECK (embedding_dimension > 0),
  strict_schema_status VARCHAR(16) NOT NULL DEFAULT 'UNKNOWN'
    CHECK (strict_schema_status IN ('UNKNOWN', 'SUPPORTED', 'UNSUPPORTED')),
  probe_checked_at TIMESTAMP,
  build_status VARCHAR(16) NOT NULL DEFAULT 'NOT_BUILT'
    CHECK (build_status IN ('NOT_BUILT', 'RUNNING', 'READY', 'FAILED', 'SKIPPED')),
  build_total INTEGER NOT NULL DEFAULT 0 CHECK (build_total >= 0),
  build_ready INTEGER NOT NULL DEFAULT 0 CHECK (build_ready >= 0),
  build_failed INTEGER NOT NULL DEFAULT 0 CHECK (build_failed >= 0),
  last_error_code VARCHAR(64),
  revision BIGINT NOT NULL DEFAULT 0 CHECK (revision >= 0),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CHECK (build_ready + build_failed <= build_total)
);

CREATE UNIQUE INDEX IF NOT EXISTS data_agent_route_profile_idx_active
  ON data_agent_route_profile(status)
  WHERE status = 'ACTIVE' AND deleted = false;

CREATE TABLE IF NOT EXISTS data_agent_route_artifact (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  profile_id BIGINT NOT NULL REFERENCES data_agent_route_profile(id) ON DELETE CASCADE,
  tenant_id VARCHAR(64) NOT NULL,
  target_type VARCHAR(16) NOT NULL CHECK (target_type IN ('SKILL', 'COLLABORATOR')),
  target_id BIGINT NOT NULL,
  target_version_id BIGINT,
  target_key VARCHAR(192) NOT NULL,
  skill_kind VARCHAR(32),
  execution_mode VARCHAR(32),
  display_name VARCHAR(256) NOT NULL,
  description TEXT,
  normalized_rules JSONB NOT NULL,
  risk_level VARCHAR(16) NOT NULL
    CHECK (risk_level IN ('READ_ONLY', 'WRITE', 'FLOW', 'DELEGATED', 'UNKNOWN')),
  source_checksum VARCHAR(64) NOT NULL,
  content_checksum VARCHAR(64) NOT NULL,
  embedding_fingerprint VARCHAR(128) NOT NULL,
  embedding_dimension INTEGER NOT NULL CHECK (embedding_dimension > 0),
  vector_document_id VARCHAR(256),
  status VARCHAR(16) NOT NULL CHECK (status IN ('PREPARING', 'READY', 'FAILED')),
  failure_code VARCHAR(64),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CHECK ((target_type = 'SKILL' AND target_version_id IS NOT NULL)
      OR (target_type = 'COLLABORATOR' AND target_version_id IS NULL)),
  CHECK ((status = 'READY' AND vector_document_id IS NOT NULL AND failure_code IS NULL)
      OR status <> 'READY')
);

CREATE UNIQUE INDEX IF NOT EXISTS data_agent_route_artifact_idx_source
  ON data_agent_route_artifact(profile_id, tenant_id, target_key, source_checksum)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS data_agent_route_artifact_idx_ready_lookup
  ON data_agent_route_artifact(profile_id, tenant_id, status, target_key)
  WHERE deleted = false;

CREATE TABLE IF NOT EXISTS data_agent_route_pending (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  owner_agent_id BIGINT NOT NULL,
  session_id BIGINT,
  user_id VARCHAR(64) NOT NULL,
  thread_id VARCHAR(128) NOT NULL,
  runtime_request_id VARCHAR(128) NOT NULL,
  parent_run_id BIGINT,
  parent_step_id BIGINT,
  execution_state VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  result_reference VARCHAR(128),
  legacy_interaction_type VARCHAR(32),
  token_hash VARCHAR(64) NOT NULL,
  interaction_type VARCHAR(32) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  clarification_round INTEGER NOT NULL DEFAULT 0,
  original_query TEXT NOT NULL,
  prompt TEXT NOT NULL,
  public_payload JSONB NOT NULL,
  route_snapshot JSONB NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  consumed_at TIMESTAMP,
  consumed_runtime_request_id VARCHAR(128),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT data_agent_route_pending_status_ck
    CHECK (status IN ('PENDING', 'CONSUMED', 'EXPIRED')),
  CONSTRAINT data_agent_route_pending_execution_state_ck
    CHECK (execution_state IN ('PENDING', 'CLAIMED', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'FORWARDED', 'EXPIRED')),
  CONSTRAINT data_agent_route_pending_interaction_type_ck
    CHECK (interaction_type IN ('BUSINESS_CLARIFICATION', 'ROUTE_CLARIFICATION', 'CONFIRMATION')),
  CONSTRAINT data_agent_route_pending_round_ck
    CHECK ((interaction_type IN ('BUSINESS_CLARIFICATION', 'ROUTE_CLARIFICATION')
              AND clarification_round BETWEEN 1 AND 2)
        OR (interaction_type = 'CONFIRMATION' AND clarification_round BETWEEN 0 AND 2)),
  CONSTRAINT data_agent_route_pending_legacy_interaction_ck
    CHECK (legacy_interaction_type IS NULL
      OR (legacy_interaction_type = 'ROUTE_RECOVERY'
          AND status <> 'PENDING'
          AND execution_state = 'CANCELLED')),
  CONSTRAINT data_agent_route_pending_parent_binding_ck
    CHECK ((parent_run_id IS NULL) = (parent_step_id IS NULL)),
  CONSTRAINT data_agent_route_pending_binding_ck
    CHECK (BTRIM(tenant_id) <> '' AND BTRIM(user_id) <> ''
      AND BTRIM(thread_id) <> '' AND BTRIM(runtime_request_id) <> ''),
  CONSTRAINT data_agent_route_pending_token_hash_ck
    CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT data_agent_route_pending_payload_ck
    CHECK (jsonb_typeof(public_payload) = 'object' AND jsonb_typeof(route_snapshot) = 'object'),
  CONSTRAINT data_agent_route_pending_lifecycle_ck
    CHECK (expires_at > create_time
      AND ((status = 'CONSUMED'
              AND consumed_at IS NOT NULL
              AND NULLIF(BTRIM(consumed_runtime_request_id), '') IS NOT NULL
              AND consumed_at >= create_time
              AND consumed_at < expires_at)
        OR (status IN ('PENDING', 'EXPIRED')
              AND consumed_at IS NULL
              AND consumed_runtime_request_id IS NULL)))
);

CREATE UNIQUE INDEX IF NOT EXISTS data_agent_route_pending_idx_token_hash
  ON data_agent_route_pending(token_hash);

CREATE INDEX IF NOT EXISTS data_agent_route_pending_idx_expires_at
  ON data_agent_route_pending(expires_at)
  WHERE deleted = false AND status = 'PENDING';

CREATE INDEX IF NOT EXISTS data_agent_route_pending_idx_parent_step
  ON data_agent_route_pending(parent_run_id, parent_step_id)
  WHERE deleted = false AND status = 'PENDING'
    AND parent_run_id IS NOT NULL AND parent_step_id IS NOT NULL;

COMMENT ON TABLE data_agent_route_pending IS '服务端持有的单次业务澄清、路由澄清与确认待续状态';
COMMENT ON COLUMN data_agent_route_pending.id IS '主键ID';
COMMENT ON COLUMN data_agent_route_pending.tenant_id IS '租户安全绑定';
COMMENT ON COLUMN data_agent_route_pending.owner_agent_id IS '创建交互的智能体ID';
COMMENT ON COLUMN data_agent_route_pending.session_id IS '可选数字会话ID，UUID线程场景为空';
COMMENT ON COLUMN data_agent_route_pending.user_id IS '用户安全绑定快照';
COMMENT ON COLUMN data_agent_route_pending.thread_id IS '字符串线程或会话安全绑定';
COMMENT ON COLUMN data_agent_route_pending.runtime_request_id IS '创建交互的运行请求ID';
COMMENT ON COLUMN data_agent_route_pending.parent_run_id IS '父编排运行ID';
COMMENT ON COLUMN data_agent_route_pending.parent_step_id IS '父编排步骤ID';
COMMENT ON COLUMN data_agent_route_pending.execution_state IS '待办执行状态：待领取、已领取、成功、失败、取消、已转交或已过期';
COMMENT ON COLUMN data_agent_route_pending.result_reference IS '幂等执行结果引用';
COMMENT ON COLUMN data_agent_route_pending.legacy_interaction_type IS '已退役交互类型的历史标识';
COMMENT ON COLUMN data_agent_route_pending.token_hash IS '不透明交互令牌的SHA-256摘要';
COMMENT ON COLUMN data_agent_route_pending.interaction_type IS '交互类型：业务澄清、路由澄清或确认';
COMMENT ON COLUMN data_agent_route_pending.status IS '状态：待处理、已消费或已过期';
COMMENT ON COLUMN data_agent_route_pending.clarification_round IS '业务澄清与路由澄清合计轮次';
COMMENT ON COLUMN data_agent_route_pending.original_query IS '用户原始问题快照';
COMMENT ON COLUMN data_agent_route_pending.prompt IS '公开给用户的业务澄清或确认问题';
COMMENT ON COLUMN data_agent_route_pending.public_payload IS '可公开交互数据，不包含内部路由标识';
COMMENT ON COLUMN data_agent_route_pending.route_snapshot IS '仅服务端使用的路由与选项快照';
COMMENT ON COLUMN data_agent_route_pending.expires_at IS '交互状态过期时间';
COMMENT ON COLUMN data_agent_route_pending.consumed_at IS 'CAS成功消费时间';
COMMENT ON COLUMN data_agent_route_pending.consumed_runtime_request_id IS '消费交互的新运行请求ID';
COMMENT ON COLUMN data_agent_route_pending.create_by IS '创建人账号';
COMMENT ON COLUMN data_agent_route_pending.create_name IS '创建人名称';
COMMENT ON COLUMN data_agent_route_pending.create_time IS '创建时间';
COMMENT ON COLUMN data_agent_route_pending.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN data_agent_route_pending.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN data_agent_route_pending.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN data_agent_route_pending.deleted IS '逻辑删除标识';

CREATE TABLE IF NOT EXISTS agent_collaborator (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  collaborator_agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  role_name VARCHAR(100),
  capability_description TEXT,
  delegation_mode VARCHAR(32) NOT NULL DEFAULT 'INTERACTIVE'
    CHECK (delegation_mode IN ('AUTO_READ_ONLY', 'PLAN_CONFIRM', 'INTERACTIVE')),
  routing_rules JSONB NOT NULL DEFAULT
    '{"exact":[],"phrases":[],"aliases":[],"positiveExamples":[],"negativeExamples":[],"hardExcludes":[]}'::jsonb,
  priority INTEGER NOT NULL DEFAULT 0,
  enabled BOOLEAN DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS agent_orchestration_policy (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  max_collaborators_per_run INTEGER NOT NULL CHECK (max_collaborators_per_run > 0),
  failure_strategy VARCHAR(50) DEFAULT 'continue' CHECK (failure_strategy IN ('continue', 'fail_fast')),
  expose_trace BOOLEAN DEFAULT true,
  enabled BOOLEAN DEFAULT true,
  clarification_config JSONB DEFAULT '{}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS agent_orchestration_run (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  thread_id VARCHAR(128),
  runtime_request_id VARCHAR(128),
  query TEXT,
  status VARCHAR(50) DEFAULT 'running',
  final_answer TEXT,
  error_message TEXT,
  route_ms BIGINT DEFAULT 0,
  collaborator_ms BIGINT DEFAULT 0,
  summary_ms BIGINT DEFAULT 0,
  total_ms BIGINT DEFAULT 0,
  collaborator_count INTEGER DEFAULT 0,
  started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON COLUMN agent_orchestration_run.route_ms IS '总路由耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_run.collaborator_ms IS '协作者总耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_run.summary_ms IS '汇总耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_run.total_ms IS '编排总耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_run.collaborator_count IS '协作者数量';

CREATE TABLE IF NOT EXISTS agent_orchestration_step (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  run_id BIGINT NOT NULL REFERENCES agent_orchestration_run(id) ON DELETE CASCADE,
  step_no INTEGER NOT NULL,
  route_step_id VARCHAR(64),
  collaborator_agent_id BIGINT REFERENCES data_agent(id) ON DELETE SET NULL,
  task TEXT,
  reason TEXT,
  expected_output TEXT,
  status VARCHAR(50) DEFAULT 'running',
  answer TEXT,
  evidence TEXT,
  confidence VARCHAR(50),
  error_code VARCHAR(100),
  error_message TEXT,
  child_thread_id VARCHAR(128),
  child_runtime_request_id VARCHAR(128),
  duration_ms BIGINT DEFAULT 0,
  react_ms BIGINT DEFAULT 0,
  tool_count INTEGER DEFAULT 0,
  tool_fail_count INTEGER DEFAULT 0,
  started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON COLUMN agent_orchestration_step.child_thread_id IS '子会话ID';
COMMENT ON COLUMN agent_orchestration_step.child_runtime_request_id IS '子运行请求ID';
COMMENT ON COLUMN agent_orchestration_step.route_step_id IS '路由计划步骤标识，用于父子协作者续传';
COMMENT ON COLUMN agent_orchestration_step.duration_ms IS '步骤总耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_step.react_ms IS 'ReAct 执行耗时，单位毫秒';
COMMENT ON COLUMN agent_orchestration_step.tool_count IS '工具调用次数';
COMMENT ON COLUMN agent_orchestration_step.tool_fail_count IS '工具失败次数';

CREATE TABLE IF NOT EXISTS data_chat_session (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  title VARCHAR(255) DEFAULT '新对话',
  status VARCHAR(50) DEFAULT 'active',
  is_pinned BOOLEAN DEFAULT false,
  user_id BIGINT,
  channel_type VARCHAR(32) NOT NULL DEFAULT 'WEB',
  provider VARCHAR(32),
  connector_code VARCHAR(128),
  session_scope VARCHAR(32),
  channel_session_key VARCHAR(512),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_chat_message (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL REFERENCES data_chat_session(id) ON DELETE CASCADE,
  role VARCHAR(20) NOT NULL,
  content TEXT NOT NULL,
  message_type VARCHAR(50) DEFAULT 'text',
  metadata TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_chat_turn (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL REFERENCES data_chat_session(id) ON DELETE CASCADE,
  thread_id VARCHAR(128) NOT NULL,
  runtime_request_id VARCHAR(128) NOT NULL,
  request_source VARCHAR(32) DEFAULT 'WEB',
  provider VARCHAR(32),
  connector_code VARCHAR(128),
  external_conversation_id VARCHAR(256),
  external_user_id VARCHAR(256),
  agent_id BIGINT NOT NULL REFERENCES data_agent(id) ON DELETE CASCADE,
  user_id BIGINT,
  question TEXT,
  answer TEXT,
  status VARCHAR(50) DEFAULT 'running',
  error_message TEXT,
  started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  finished_at TIMESTAMP,
  duration_ms BIGINT DEFAULT 0,
  answer_explain_message_id BIGINT,
  orchestration_run_id BIGINT,
  model_config_id BIGINT,
  model_name VARCHAR(128),
  prompt_tokens BIGINT DEFAULT 0,
  completion_tokens BIGINT DEFAULT 0,
  total_tokens BIGINT DEFAULT 0,
  tool_count INTEGER DEFAULT 0,
  tool_fail_count INTEGER DEFAULT 0,
  has_datasource BOOLEAN DEFAULT false,
  has_sql BOOLEAN DEFAULT false,
  route_target_type VARCHAR(16),
  route_target_id BIGINT,
  route_target_version_id BIGINT,
  route_artifact_id BIGINT REFERENCES data_agent_route_artifact(id),
  route_profile_id BIGINT REFERENCES data_agent_route_profile(id),
  route_decision VARCHAR(32),
  route_reason_code VARCHAR(64),
  route_degrade_mode VARCHAR(32),
  route_selected_count INTEGER NOT NULL DEFAULT 0 CHECK (route_selected_count >= 0),
  route_duration_ms BIGINT,
  knowledge_duration_ms BIGINT,
  flow_duration_ms BIGINT,
  react_duration_ms BIGINT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_data_chat_turn_session_runtime
  ON data_chat_turn(session_id, runtime_request_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_data_chat_turn_agent_time
  ON data_chat_turn(agent_id, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_data_chat_turn_user_time
  ON data_chat_turn(user_id, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_data_chat_turn_status_time
  ON data_chat_turn(status, started_at DESC);

CREATE INDEX IF NOT EXISTS idx_data_chat_turn_channel_source
  ON data_chat_turn(request_source, provider, connector_code, started_at DESC);

CREATE INDEX IF NOT EXISTS data_chat_turn_idx_route_target_time
  ON data_chat_turn(route_target_type, route_target_id, route_target_version_id, started_at DESC);

CREATE INDEX IF NOT EXISTS data_chat_turn_idx_route_continuity
  ON data_chat_turn(agent_id, session_id, user_id, finished_at DESC)
  WHERE status = 'success' AND route_decision = 'SELECT' AND route_selected_count = 1 AND deleted = false;

COMMENT ON TABLE data_chat_turn IS 'DataAgent 单轮对话诊断索引';
COMMENT ON COLUMN data_chat_turn.session_id IS '会话ID';
COMMENT ON COLUMN data_chat_turn.thread_id IS '运行线程ID，当前为会话ID字符串';
COMMENT ON COLUMN data_chat_turn.runtime_request_id IS '会话内单次运行请求ID';
COMMENT ON COLUMN data_chat_turn.request_source IS '请求来源：WEB、IM、WEB_TAKEOVER、API';
COMMENT ON COLUMN data_chat_turn.provider IS '外部渠道平台';
COMMENT ON COLUMN data_chat_turn.connector_code IS '渠道连接器编码';
COMMENT ON COLUMN data_chat_turn.external_conversation_id IS '外部会话ID';
COMMENT ON COLUMN data_chat_turn.external_user_id IS '外部用户ID';
COMMENT ON COLUMN data_chat_turn.agent_id IS 'Agent ID，智能体标识';
COMMENT ON COLUMN data_chat_turn.user_id IS '业务用户ID';
COMMENT ON COLUMN data_chat_turn.question IS '用户问题';
COMMENT ON COLUMN data_chat_turn.answer IS '最终答案';
COMMENT ON COLUMN data_chat_turn.status IS '单轮状态：running、success、failed、cancelled';
COMMENT ON COLUMN data_chat_turn.error_message IS '错误信息';
COMMENT ON COLUMN data_chat_turn.answer_explain_message_id IS '持久化答案解释隐藏消息ID';
COMMENT ON COLUMN data_chat_turn.orchestration_run_id IS '编排运行ID';
COMMENT ON COLUMN data_chat_turn.model_config_id IS '模型配置ID，仅用于诊断展示';
COMMENT ON COLUMN data_chat_turn.model_name IS '模型名称，仅用于诊断展示';
COMMENT ON COLUMN data_chat_turn.prompt_tokens IS '输入 Token 快照，仅用于诊断展示';
COMMENT ON COLUMN data_chat_turn.completion_tokens IS '输出 Token 快照，仅用于诊断展示';
COMMENT ON COLUMN data_chat_turn.total_tokens IS '总 Token 快照，仅用于诊断展示';
COMMENT ON COLUMN data_chat_turn.has_datasource IS '是否存在数据源证据';
COMMENT ON COLUMN data_chat_turn.has_sql IS '是否存在 SQL 证据';

CREATE TABLE IF NOT EXISTS agent_token_usage (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  tenant_code VARCHAR(128),
  user_id VARCHAR(64),
  user_nick_name VARCHAR(128),
  client_id VARCHAR(128),
  team_ids_json TEXT,
  agent_id BIGINT,
  agent_name VARCHAR(255),
  session_id BIGINT,
  thread_id VARCHAR(128),
  runtime_request_id VARCHAR(128),
  root_runtime_request_id VARCHAR(128),
  parent_runtime_request_id VARCHAR(128),
  orchestration_run_id BIGINT,
  orchestration_step_id BIGINT,
  model_config_id BIGINT,
  provider VARCHAR(64),
  model_name VARCHAR(128),
  model_type VARCHAR(64),
  usage_source VARCHAR(64),
  prompt_tokens BIGINT DEFAULT 0,
  completion_tokens BIGINT DEFAULT 0,
  total_tokens BIGINT DEFAULT 0,
  metering_mode VARCHAR(32),
  status VARCHAR(32),
  duration_ms BIGINT,
  error_code VARCHAR(128),
  error_message TEXT,
  request_source VARCHAR(64),
  cache_hit BOOLEAN DEFAULT false,
  raw_usage_json TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_token_usage IS 'DataAgent Token 用量审计事实表';
COMMENT ON COLUMN agent_token_usage.tenant_id IS '租户ID快照';
COMMENT ON COLUMN agent_token_usage.tenant_code IS '租户编码快照';
COMMENT ON COLUMN agent_token_usage.user_id IS '使用用户ID快照';
COMMENT ON COLUMN agent_token_usage.client_id IS '客户端ID快照';
COMMENT ON COLUMN agent_token_usage.team_ids_json IS '团队ID快照JSON';
COMMENT ON COLUMN agent_token_usage.agent_id IS 'Agent ID，智能体标识';
COMMENT ON COLUMN agent_token_usage.session_id IS '会话ID';
COMMENT ON COLUMN agent_token_usage.thread_id IS '运行线程ID';
COMMENT ON COLUMN agent_token_usage.runtime_request_id IS '当前运行请求ID';
COMMENT ON COLUMN agent_token_usage.root_runtime_request_id IS '根运行请求ID';
COMMENT ON COLUMN agent_token_usage.parent_runtime_request_id IS '父运行请求ID';
COMMENT ON COLUMN agent_token_usage.orchestration_run_id IS '编排运行ID';
COMMENT ON COLUMN agent_token_usage.orchestration_step_id IS '编排步骤ID';
COMMENT ON COLUMN agent_token_usage.model_config_id IS '模型配置ID';
COMMENT ON COLUMN agent_token_usage.provider IS '模型服务商';
COMMENT ON COLUMN agent_token_usage.model_name IS '模型名称';
COMMENT ON COLUMN agent_token_usage.model_type IS '模型类型';
COMMENT ON COLUMN agent_token_usage.usage_source IS '用量来源';
COMMENT ON COLUMN agent_token_usage.prompt_tokens IS '输入 Token 数';
COMMENT ON COLUMN agent_token_usage.completion_tokens IS '输出 Token 数';
COMMENT ON COLUMN agent_token_usage.total_tokens IS '总 Token 数';
COMMENT ON COLUMN agent_token_usage.metering_mode IS '计量模式：ACTUAL、ESTIMATED、UNKNOWN';
COMMENT ON COLUMN agent_token_usage.status IS '调用状态';
COMMENT ON COLUMN agent_token_usage.duration_ms IS '调用耗时，单位毫秒';
COMMENT ON COLUMN agent_token_usage.error_code IS '错误码';
COMMENT ON COLUMN agent_token_usage.error_message IS '错误消息';
COMMENT ON COLUMN agent_token_usage.request_source IS '调用来源';
COMMENT ON COLUMN agent_token_usage.cache_hit IS '是否命中缓存';
COMMENT ON COLUMN agent_token_usage.raw_usage_json IS '原始用量JSON';

CREATE TABLE IF NOT EXISTS agent_usage_limit_policy (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  scope_type VARCHAR(32) NOT NULL,
  scope_id VARCHAR(64) NOT NULL DEFAULT '*',
  user_nick_name VARCHAR(128),
  agent_id BIGINT,
  agent_name VARCHAR(255),
  model_config_id BIGINT,
  policy_type VARCHAR(32) NOT NULL,
  window_type VARCHAR(32) NOT NULL DEFAULT 'DAY',
  window_seconds BIGINT,
  limit_value BIGINT NOT NULL,
  warn_threshold_ratio NUMERIC(8, 4),
  action VARCHAR(32) NOT NULL DEFAULT 'BLOCK',
  enabled BOOLEAN DEFAULT true,
  description VARCHAR(512),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_usage_limit_policy IS 'DataAgent 用量限制策略表';
COMMENT ON COLUMN agent_usage_limit_policy.scope_type IS '策略范围：GLOBAL、TENANT、USER';
COMMENT ON COLUMN agent_usage_limit_policy.scope_id IS '范围ID，GLOBAL 使用 *';
COMMENT ON COLUMN agent_usage_limit_policy.agent_id IS '可选 Agent 条件';
COMMENT ON COLUMN agent_usage_limit_policy.model_config_id IS '可选模型配置条件';
COMMENT ON COLUMN agent_usage_limit_policy.policy_type IS '策略类型：TOKEN_QUOTA、TOKEN_RATE、REQUEST_RATE';
COMMENT ON COLUMN agent_usage_limit_policy.window_type IS '窗口类型：DAY、MONTH、ROLLING';
COMMENT ON COLUMN agent_usage_limit_policy.window_seconds IS '滚动窗口秒数';
COMMENT ON COLUMN agent_usage_limit_policy.limit_value IS '限制值';
COMMENT ON COLUMN agent_usage_limit_policy.warn_threshold_ratio IS '告警阈值比例';
COMMENT ON COLUMN agent_usage_limit_policy.action IS '动作：WARN、BLOCK';
COMMENT ON COLUMN agent_usage_limit_policy.enabled IS '是否启用';
COMMENT ON COLUMN agent_usage_limit_policy.description IS '策略说明';

