COMMENT ON COLUMN agent_token_usage.user_nick_name IS '用量展示用户昵称快照';
COMMENT ON COLUMN agent_token_usage.agent_name IS '用量展示 Agent 名称快照';
COMMENT ON COLUMN agent_token_usage_day.user_nick_name IS '日聚合用量展示用户昵称快照';
COMMENT ON COLUMN agent_token_usage_day.agent_name IS '日聚合用量展示 Agent 名称快照';
