CREATE INDEX IF NOT EXISTS idx_agent_token_usage_time
  ON agent_token_usage(create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_user_time
  ON agent_token_usage(user_id, create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_agent_time
  ON agent_token_usage(agent_id, create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_model_time
  ON agent_token_usage(model_config_id, create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_tenant_time
  ON agent_token_usage(tenant_id, create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_runtime
  ON agent_token_usage(runtime_request_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_token_usage_root
  ON agent_token_usage(root_runtime_request_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_agent_usage_limit_policy_scope
  ON agent_usage_limit_policy(scope_type, scope_id, enabled)
  WHERE deleted = false;
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_token_usage_day_dim
  ON agent_token_usage_day(stat_date, tenant_id, user_id, agent_id, model_config_id, provider, model_name, usage_source);

CREATE TABLE IF NOT EXISTS data_agentscope_session_state (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id BIGINT NOT NULL,
  module_name VARCHAR(255) NOT NULL,
  state_class VARCHAR(255) NOT NULL,
  sequence INTEGER NOT NULL DEFAULT 0,
  content TEXT NOT NULL,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_memory_config (
  id BIGINT PRIMARY KEY,
  agent_id BIGINT NOT NULL,
  user_id VARCHAR(128) NOT NULL,
  recall_enabled BOOLEAN NOT NULL DEFAULT false,
  write_enabled BOOLEAN NOT NULL DEFAULT false,
  recall_types VARCHAR(256),
  write_types VARCHAR(256),
  top_k INTEGER NOT NULL DEFAULT 5,
  similarity_threshold NUMERIC(6, 4) NOT NULL DEFAULT 0.7500,
  injection_token_budget INTEGER NOT NULL DEFAULT 1200,
  min_importance NUMERIC(6, 4) NOT NULL DEFAULT 0.5000,
  confirmed_only BOOLEAN NOT NULL DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS data_agent_memory (
  id BIGINT PRIMARY KEY,
  agent_id BIGINT NOT NULL,
  user_id VARCHAR(128) NOT NULL,
  memory_type VARCHAR(32) NOT NULL,
  summary TEXT NOT NULL,
  content TEXT,
  semantic_hash VARCHAR(128) NOT NULL,
  importance NUMERIC(6, 4) NOT NULL DEFAULT 0.5000,
  confidence NUMERIC(6, 4) NOT NULL DEFAULT 0.7000,
  status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
  source_session_id VARCHAR(128),
  source_message_id VARCHAR(128),
  use_count INTEGER NOT NULL DEFAULT 0,
  last_used_time TIMESTAMP,
  expire_time TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS skill_datasource_tables (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_datasource_id BIGINT NOT NULL REFERENCES skill_datasource(id) ON UPDATE CASCADE ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS skill_datasource_columns (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  skill_datasource_id BIGINT NOT NULL REFERENCES skill_datasource(id) ON UPDATE CASCADE ON DELETE CASCADE,
  table_name VARCHAR(255) NOT NULL,
  column_name VARCHAR(255) NOT NULL,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

-- pgvector is disabled for simple vector store mode.
CREATE TABLE IF NOT EXISTS vector_store (
  id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
  content TEXT,
  metadata JSON,
  embedding vector(1024)
);

