-- Resource ownership is enforced in the database as well as in the service layer.
CREATE OR REPLACE FUNCTION dataagent_validate_agent_tenant()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF COALESCE(NEW.deleted, false) THEN
    RETURN NEW;
END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_binding binding
     WHERE binding.agent_id = NEW.id
       AND COALESCE(binding.deleted, false) = false
       AND binding.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Agent tenant cannot differ from an active Skill binding, agentId=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_tenant_validate ON data_agent;
CREATE TRIGGER trg_data_agent_tenant_validate
BEFORE UPDATE OF tenant_id, deleted ON data_agent
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_agent_tenant();

CREATE OR REPLACE FUNCTION dataagent_validate_datasource_tenant()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (
      SELECT 1
        FROM skill_datasource binding
       WHERE binding.datasource_id = OLD.id
         AND COALESCE(binding.deleted, false) = false
    ) OR EXISTS (
      SELECT 1
        FROM data_agent_skill_version version
       WHERE version.status IN ('PUBLISHED', 'RETIRED')
         AND COALESCE(version.deleted, false) = false
         AND version.datasource_config ->> 'datasourceId' = OLD.id::TEXT
    ) THEN
      RAISE EXCEPTION 'Datasource with active or published Skill references cannot be deleted, datasourceId=%', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF COALESCE(NEW.deleted, false) THEN
    IF EXISTS (
      SELECT 1
        FROM skill_datasource binding
       WHERE binding.datasource_id = NEW.id
         AND COALESCE(binding.deleted, false) = false
    ) OR EXISTS (
      SELECT 1
        FROM data_agent_skill_version version
       WHERE version.status IN ('PUBLISHED', 'RETIRED')
         AND COALESCE(version.deleted, false) = false
         AND version.datasource_config ->> 'datasourceId' = NEW.id::TEXT
    ) THEN
      RAISE EXCEPTION 'Datasource with active or published Skill references cannot be deleted, datasourceId=%', NEW.id;
    END IF;
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM skill_datasource binding
      JOIN data_agent_skill skill ON skill.id = binding.skill_id
     WHERE binding.datasource_id = NEW.id
       AND COALESCE(binding.deleted, false) = false
       AND COALESCE(skill.deleted, false) = false
       AND skill.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) OR EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
      JOIN data_agent_skill skill ON skill.id = version.skill_id
     WHERE version.status IN ('PUBLISHED', 'RETIRED')
       AND COALESCE(version.deleted, false) = false
       AND COALESCE(skill.deleted, false) = false
       AND version.datasource_config ->> 'datasourceId' = NEW.id::TEXT
       AND skill.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Datasource tenant cannot differ from its Skill bindings, datasourceId=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_datasource_tenant_validate ON datasource;
CREATE TRIGGER trg_datasource_tenant_validate
BEFORE UPDATE OF tenant_id, deleted ON datasource
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_datasource_tenant();

DROP TRIGGER IF EXISTS trg_datasource_delete_validate ON datasource;
CREATE TRIGGER trg_datasource_delete_validate
BEFORE DELETE ON datasource
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_datasource_tenant();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_datasource_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
  v_skill_scope VARCHAR(32);
  v_skill_kind VARCHAR(32);
  v_datasource_tenant VARCHAR(64);
BEGIN
  SELECT tenant_id, scope, skill_kind
    INTO v_skill_tenant, v_skill_scope, v_skill_kind
    FROM data_agent_skill
   WHERE id = NEW.skill_id AND deleted = false;
  IF NOT FOUND OR v_skill_scope <> 'TENANT' OR v_skill_tenant IS NULL THEN
    RAISE EXCEPTION 'Skill datasource must belong to an active tenant Skill, skillId=%', NEW.skill_id;
  END IF;

  SELECT tenant_id
    INTO v_datasource_tenant
    FROM datasource
   WHERE id = NEW.datasource_id AND deleted = false;
  IF NOT FOUND OR v_datasource_tenant <> v_skill_tenant THEN
    RAISE EXCEPTION 'Datasource tenant does not match Skill tenant, skillId=%, datasourceId=%',
      NEW.skill_id, NEW.datasource_id;
  END IF;

  IF COALESCE(NEW.is_active, false) AND v_skill_kind = 'QUERY' AND EXISTS (
    SELECT 1
      FROM skill_datasource existing
     WHERE existing.skill_id = NEW.skill_id
       AND existing.id <> COALESCE(NEW.id, -1)
       AND COALESCE(existing.is_active, false)
       AND COALESCE(existing.deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'QUERY Skill can have only one active datasource, skillId=%', NEW.skill_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_skill_datasource_ownership ON skill_datasource;
CREATE TRIGGER trg_skill_datasource_ownership
BEFORE INSERT OR UPDATE OF skill_id, datasource_id, is_active, deleted ON skill_datasource
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_datasource_ownership();

CREATE OR REPLACE FUNCTION dataagent_validate_semantic_model_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
  v_skill_scope VARCHAR(32);
  v_datasource_tenant VARCHAR(64);
BEGIN
  SELECT tenant_id, scope
    INTO v_skill_tenant, v_skill_scope
    FROM data_agent_skill
   WHERE id = NEW.skill_id AND deleted = false;
  IF NOT FOUND OR v_skill_scope <> 'TENANT' OR v_skill_tenant IS NULL THEN
    RAISE EXCEPTION 'Semantic model must belong to an active tenant Skill, skillId=%', NEW.skill_id;
  END IF;

  SELECT tenant_id
    INTO v_datasource_tenant
    FROM datasource
   WHERE id = NEW.datasource_id AND deleted = false;
  IF NOT FOUND OR v_datasource_tenant <> v_skill_tenant OR NOT EXISTS (
    SELECT 1
      FROM skill_datasource binding
     WHERE binding.skill_id = NEW.skill_id
       AND binding.datasource_id = NEW.datasource_id
       AND COALESCE(binding.deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Semantic model datasource is not owned by the Skill, skillId=%, datasourceId=%',
      NEW.skill_id, NEW.datasource_id;
  END IF;
  IF NEW.superseded_by_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM semantic_model replacement
     WHERE replacement.id = NEW.superseded_by_id
       AND replacement.skill_id IS NOT DISTINCT FROM NEW.skill_id
       AND replacement.datasource_id IS NOT DISTINCT FROM NEW.datasource_id
       AND replacement.table_name IS NOT DISTINCT FROM NEW.table_name
       AND replacement.column_name IS NOT DISTINCT FROM NEW.column_name
       AND COALESCE(replacement.deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Semantic model supersession must target an active replacement for the same Skill datasource column, modelId=%',
      NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_semantic_model_ownership ON semantic_model;
CREATE TRIGGER trg_semantic_model_ownership
BEFORE INSERT OR UPDATE OF skill_id, datasource_id, superseded_by_id, deleted ON semantic_model
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_semantic_model_ownership();

