BEGIN
  SELECT scope, tenant_id
    INTO v_scope, v_tenant_id
    FROM data_agent_skill
   WHERE id = NEW.skill_id AND deleted = false;
  IF NOT FOUND OR v_scope <> 'TENANT' OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Business knowledge must belong to an active tenant Skill, skillId=%', NEW.skill_id;
  END IF;
  IF NEW.superseded_by_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM business_knowledge replacement
     WHERE replacement.id = NEW.superseded_by_id
       AND replacement.skill_id IS NOT DISTINCT FROM NEW.skill_id
       AND COALESCE(replacement.deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'Business knowledge supersession must target an active replacement for the same Skill, knowledgeId=%',
      NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_business_knowledge_ownership ON business_knowledge;
CREATE TRIGGER trg_business_knowledge_ownership
BEFORE INSERT OR UPDATE OF skill_id, superseded_by_id, deleted ON business_knowledge
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_business_knowledge_ownership();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_knowledge_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_scope VARCHAR(32);
  v_tenant_id VARCHAR(64);
  v_skill_kind VARCHAR(32);
  v_execution_mode VARCHAR(32);
BEGIN
  SELECT scope, tenant_id, skill_kind, execution_mode
    INTO v_scope, v_tenant_id, v_skill_kind, v_execution_mode
    FROM data_agent_skill
   WHERE id = NEW.skill_id AND deleted = false;
  IF NOT FOUND OR v_scope <> 'TENANT' OR v_tenant_id IS NULL
      OR v_skill_kind <> 'QA' OR v_execution_mode <> 'KNOWLEDGE' THEN
    RAISE EXCEPTION 'Skill knowledge must belong to an active tenant QA + KNOWLEDGE Skill, skillId=%', NEW.skill_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_skill_knowledge_ownership ON skill_knowledge;
CREATE TRIGGER trg_skill_knowledge_ownership
BEFORE INSERT OR UPDATE OF skill_id, deleted ON skill_knowledge
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_knowledge_ownership();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_version_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('PUBLISHED', 'RETIRED') THEN
      RAISE EXCEPTION 'Published Skill version cannot be deleted, versionId=%', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.skill_kind IS NULL
      OR NEW.execution_mode IS NULL
      OR NOT (
        (NEW.skill_kind = 'QA' AND NEW.execution_mode = 'KNOWLEDGE')
        OR (NEW.skill_kind = 'QUERY' AND NEW.execution_mode IN ('DETERMINISTIC', 'REACT'))
        OR (NEW.skill_kind IN ('ACTION', 'ORCHESTRATION') AND NEW.execution_mode = 'FLOW')
      ) THEN
    RAISE EXCEPTION 'Skill version kind/execution mode matrix is invalid, skillId=%, versionId=%',
      NEW.skill_id, NEW.id;
  END IF;
  SELECT tenant_id
    INTO v_skill_tenant
    FROM data_agent_skill
   WHERE id = NEW.skill_id
     AND COALESCE(deleted, false) = false;
  IF NOT FOUND OR NEW.tenant_id IS DISTINCT FROM v_skill_tenant THEN
    RAISE EXCEPTION 'Skill version tenant does not match its Skill, skillId=%, versionId=%', NEW.skill_id, NEW.id;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IN ('PUBLISHED', 'RETIRED') THEN
    IF NEW.status IS DISTINCT FROM OLD.status
        AND NOT (OLD.status = 'PUBLISHED' AND NEW.status = 'RETIRED') THEN
      RAISE EXCEPTION 'Published Skill version can only transition from PUBLISHED to RETIRED, versionId=%', OLD.id;
    END IF;
    IF NEW.deleted IS DISTINCT FROM OLD.deleted
        OR NEW.published_at IS DISTINCT FROM OLD.published_at
        OR NEW.published_by IS DISTINCT FROM OLD.published_by
        OR (
        NEW.skill_id IS DISTINCT FROM OLD.skill_id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.skill_kind IS DISTINCT FROM OLD.skill_kind
        OR NEW.execution_mode IS DISTINCT FROM OLD.execution_mode
        OR NEW.version_no IS DISTINCT FROM OLD.version_no
        OR NEW.skill_markdown IS DISTINCT FROM OLD.skill_markdown
        OR NEW.route_rules IS DISTINCT FROM OLD.route_rules
        OR NEW.knowledge_config IS DISTINCT FROM OLD.knowledge_config
        OR NEW.react_config IS DISTINCT FROM OLD.react_config
        OR NEW.flow_definition IS DISTINCT FROM OLD.flow_definition
        OR NEW.variables_schema IS DISTINCT FROM OLD.variables_schema
        OR NEW.flow_runtime_config IS DISTINCT FROM OLD.flow_runtime_config
        OR NEW.flow_policy_config IS DISTINCT FROM OLD.flow_policy_config
        OR NEW.resource_requirement IS DISTINCT FROM OLD.resource_requirement
        OR NEW.input_schema IS DISTINCT FROM OLD.input_schema
        OR NEW.output_schema IS DISTINCT FROM OLD.output_schema
        OR NEW.datasource_config IS DISTINCT FROM OLD.datasource_config
        OR NEW.semantic_config IS DISTINCT FROM OLD.semantic_config
        OR NEW.runtime_config IS DISTINCT FROM OLD.runtime_config
        OR NEW.checksum IS DISTINCT FROM OLD.checksum
      ) THEN
      RAISE EXCEPTION 'Published Skill version is immutable; create a new draft version, versionId=%', OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_skill_version_validate ON data_agent_skill_version;
CREATE TRIGGER trg_data_agent_skill_version_validate
BEFORE INSERT OR UPDATE OF tenant_id, skill_id, skill_kind, execution_mode, version_no, status, skill_markdown, route_rules, knowledge_config,
  react_config, flow_definition, variables_schema, flow_runtime_config, flow_policy_config, resource_requirement,
  input_schema, output_schema, datasource_config, semantic_config, runtime_config, checksum, deleted, published_at, published_by
ON data_agent_skill_version
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_version_ownership();

DROP TRIGGER IF EXISTS trg_data_agent_skill_version_delete_immutable ON data_agent_skill_version;
CREATE TRIGGER trg_data_agent_skill_version_delete_immutable
BEFORE DELETE ON data_agent_skill_version
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_version_ownership();

CREATE OR REPLACE FUNCTION dataagent_reject_published_semantic_model_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (
      SELECT 1
        FROM data_agent_skill_version version
       WHERE version.status IN ('PUBLISHED', 'RETIRED')
         AND COALESCE(version.deleted, false) = false
         AND COALESCE(version.semantic_config -> 'semanticModelIds', '[]'::jsonb)
           @> jsonb_build_array(OLD.id)
    ) THEN
      RAISE EXCEPTION 'Published Skill version references semantic model %; it cannot be deleted', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.superseded_by_id IS DISTINCT FROM OLD.superseded_by_id
      AND NEW.superseded_by_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
        FROM semantic_model replacement
       WHERE replacement.id = NEW.superseded_by_id
         AND replacement.skill_id IS NOT DISTINCT FROM OLD.skill_id
         AND replacement.datasource_id IS NOT DISTINCT FROM OLD.datasource_id
         AND replacement.table_name IS NOT DISTINCT FROM OLD.table_name
         AND replacement.column_name IS NOT DISTINCT FROM OLD.column_name
         AND COALESCE(replacement.deleted, false) = false
    ) THEN
      RAISE EXCEPTION 'Semantic model supersession must target an active replacement for the same Skill datasource column, modelId=%',
        OLD.id;
    END IF;
  END IF;
  IF NEW.superseded_by_id IS DISTINCT FROM OLD.superseded_by_id
      AND (
        NEW.skill_id IS DISTINCT FROM OLD.skill_id
        OR NEW.datasource_id IS DISTINCT FROM OLD.datasource_id
        OR NEW.table_name IS DISTINCT FROM OLD.table_name
        OR NEW.column_name IS DISTINCT FROM OLD.column_name
        OR NEW.business_name IS DISTINCT FROM OLD.business_name
        OR NEW.synonyms IS DISTINCT FROM OLD.synonyms
        OR NEW.business_description IS DISTINCT FROM OLD.business_description
        OR NEW.column_comment IS DISTINCT FROM OLD.column_comment
        OR NEW.data_type IS DISTINCT FROM OLD.data_type
        OR NEW.status IS DISTINCT FROM OLD.status
        OR NEW.deleted IS DISTINCT FROM OLD.deleted
      ) THEN
    RAISE EXCEPTION 'Semantic model supersession cannot change the superseded resource content, modelId=%', OLD.id;
  END IF;
  IF NEW.skill_id IS NOT DISTINCT FROM OLD.skill_id
      AND NEW.datasource_id IS NOT DISTINCT FROM OLD.datasource_id
      AND NEW.table_name IS NOT DISTINCT FROM OLD.table_name
      AND NEW.column_name IS NOT DISTINCT FROM OLD.column_name
      AND NEW.business_name IS NOT DISTINCT FROM OLD.business_name
      AND NEW.synonyms IS NOT DISTINCT FROM OLD.synonyms
      AND NEW.business_description IS NOT DISTINCT FROM OLD.business_description
      AND NEW.column_comment IS NOT DISTINCT FROM OLD.column_comment
      AND NEW.data_type IS NOT DISTINCT FROM OLD.data_type
      AND NEW.status IS NOT DISTINCT FROM OLD.status
      AND NEW.deleted IS NOT DISTINCT FROM OLD.deleted
      AND NEW.superseded_by_id IS NOT DISTINCT FROM OLD.superseded_by_id THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
     WHERE version.status IN ('PUBLISHED', 'RETIRED')
       AND COALESCE(version.deleted, false) = false
       AND COALESCE(version.semantic_config -> 'semanticModelIds', '[]'::jsonb)
         @> jsonb_build_array(OLD.id)
  ) THEN
    IF OLD.superseded_by_id IS NULL
        AND NEW.superseded_by_id IS NOT NULL
        AND NEW.skill_id IS NOT DISTINCT FROM OLD.skill_id
        AND NEW.datasource_id IS NOT DISTINCT FROM OLD.datasource_id
        AND NEW.table_name IS NOT DISTINCT FROM OLD.table_name
        AND NEW.column_name IS NOT DISTINCT FROM OLD.column_name
        AND NEW.business_name IS NOT DISTINCT FROM OLD.business_name
        AND NEW.synonyms IS NOT DISTINCT FROM OLD.synonyms
        AND NEW.business_description IS NOT DISTINCT FROM OLD.business_description
        AND NEW.column_comment IS NOT DISTINCT FROM OLD.column_comment
        AND NEW.data_type IS NOT DISTINCT FROM OLD.data_type
        AND NEW.status IS NOT DISTINCT FROM OLD.status
        AND NEW.deleted IS NOT DISTINCT FROM OLD.deleted THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Published Skill version references semantic model %; copy it before editing', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_semantic_model_published_immutable ON semantic_model;
CREATE TRIGGER trg_semantic_model_published_immutable
BEFORE UPDATE OF skill_id, datasource_id, table_name, column_name, business_name, synonyms,
  business_description, column_comment, data_type, status, deleted, superseded_by_id
ON semantic_model
FOR EACH ROW EXECUTE FUNCTION dataagent_reject_published_semantic_model_mutation();

DROP TRIGGER IF EXISTS trg_semantic_model_published_delete_immutable ON semantic_model;
CREATE TRIGGER trg_semantic_model_published_delete_immutable
BEFORE DELETE ON semantic_model
FOR EACH ROW EXECUTE FUNCTION dataagent_reject_published_semantic_model_mutation();

CREATE OR REPLACE FUNCTION dataagent_reject_published_business_knowledge_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (
      SELECT 1
        FROM data_agent_skill_version version
       WHERE version.status IN ('PUBLISHED', 'RETIRED')
         AND COALESCE(version.deleted, false) = false
         AND COALESCE(version.knowledge_config -> 'businessKnowledgeIds', '[]'::jsonb)
           @> jsonb_build_array(OLD.id)
    ) THEN
      RAISE EXCEPTION 'Published Skill version references business knowledge %; it cannot be deleted', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.superseded_by_id IS DISTINCT FROM OLD.superseded_by_id
      AND NEW.superseded_by_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
          FROM business_knowledge replacement
         WHERE replacement.id = NEW.superseded_by_id
           AND replacement.skill_id IS NOT DISTINCT FROM OLD.skill_id
           AND COALESCE(replacement.deleted, false) = false
      ) THEN
    RAISE EXCEPTION 'Business knowledge supersession must target an active replacement for the same Skill, knowledgeId=%',
      OLD.id;
  END IF;
  IF NEW.superseded_by_id IS DISTINCT FROM OLD.superseded_by_id
      AND (
        NEW.skill_id IS DISTINCT FROM OLD.skill_id
        OR NEW.business_term IS DISTINCT FROM OLD.business_term
        OR NEW.description IS DISTINCT FROM OLD.description
        OR NEW.synonyms IS NOT DISTINCT FROM OLD.synonyms
        OR NEW.is_recall IS NOT DISTINCT FROM OLD.is_recall
        OR NEW.embedding_status IS NOT DISTINCT FROM OLD.embedding_status
        OR NEW.error_msg IS NOT DISTINCT FROM OLD.error_msg
        OR NEW.deleted IS NOT DISTINCT FROM OLD.deleted
      ) THEN
    RAISE EXCEPTION 'Business knowledge supersession cannot change the superseded resource content, knowledgeId=%', OLD.id;
  END IF;
  IF NEW.skill_id IS NOT DISTINCT FROM OLD.skill_id
      AND NEW.business_term IS NOT DISTINCT FROM OLD.business_term
      AND NEW.description IS NOT DISTINCT FROM OLD.description
      AND NEW.synonyms IS NOT DISTINCT FROM OLD.synonyms
      AND NEW.is_recall IS NOT DISTINCT FROM OLD.is_recall
      AND NEW.embedding_status IS NOT DISTINCT FROM OLD.embedding_status
      AND NEW.error_msg IS NOT DISTINCT FROM OLD.error_msg
      AND NEW.deleted IS NOT DISTINCT FROM OLD.deleted
      AND NEW.superseded_by_id IS NOT DISTINCT FROM OLD.superseded_by_id THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
     WHERE version.status IN ('PUBLISHED', 'RETIRED')
       AND COALESCE(version.deleted, false) = false
       AND COALESCE(version.knowledge_config -> 'businessKnowledgeIds', '[]'::jsonb)
         @> jsonb_build_array(OLD.id)
  ) THEN
    IF OLD.superseded_by_id IS NULL
        AND NEW.superseded_by_id IS NOT NULL
        AND NEW.skill_id IS NOT DISTINCT FROM OLD.skill_id
        AND NEW.business_term IS NOT DISTINCT FROM OLD.business_term
        AND NEW.description IS NOT DISTINCT FROM OLD.description
        AND NEW.synonyms IS NOT DISTINCT FROM OLD.synonyms
        AND NEW.is_recall IS NOT DISTINCT FROM OLD.is_recall
        AND NEW.embedding_status IS NOT DISTINCT FROM OLD.embedding_status
        AND NEW.error_msg IS NOT DISTINCT FROM OLD.error_msg
        AND NEW.deleted IS NOT DISTINCT FROM OLD.deleted THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Published Skill version references business knowledge %; copy it before editing', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_business_knowledge_published_immutable ON business_knowledge;
CREATE TRIGGER trg_business_knowledge_published_immutable
BEFORE UPDATE OF skill_id, business_term, description, synonyms, is_recall, embedding_status, error_msg, deleted,
  superseded_by_id
