CREATE OR REPLACE FUNCTION dataagent_reject_published_skill_knowledge_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
     WHERE version.status IN ('PUBLISHED', 'RETIRED')
       AND COALESCE(version.deleted, false) = false
       AND COALESCE(version.knowledge_config -> 'skillKnowledgeIds', '[]'::jsonb)
         @> jsonb_build_array(OLD.id)
  ) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Published Skill version references Skill knowledge %; it cannot be deleted', OLD.id;
  END IF;
  RAISE EXCEPTION 'Published Skill version references Skill knowledge %; create a new resource instead', OLD.id;
END;
$$;

