CREATE TRIGGER trg_skill_knowledge_published_immutable
BEFORE UPDATE OF skill_id, superseded_by_id, title, type, question, content, is_recall,
  embedding_status, error_msg, source_filename, file_path, file_size, file_type, splitter_type, deleted
ON skill_knowledge
FOR EACH ROW EXECUTE FUNCTION dataagent_reject_published_skill_knowledge_mutation();

DROP TRIGGER IF EXISTS trg_skill_knowledge_published_delete_immutable ON skill_knowledge;
CREATE TRIGGER trg_skill_knowledge_published_delete_immutable
BEFORE DELETE ON skill_knowledge
FOR EACH ROW EXECUTE FUNCTION dataagent_reject_published_skill_knowledge_mutation();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_binding()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
  v_skill_scope VARCHAR(32);
  v_version_status VARCHAR(32);
  v_agent_tenant VARCHAR(64);
BEGIN
  IF COALESCE(NEW.deleted, false) THEN
    RETURN NEW;
  END IF;
  SELECT skill.tenant_id, skill.scope, version.status
    INTO v_skill_tenant, v_skill_scope, v_version_status
    FROM data_agent_skill_version version
    JOIN data_agent_skill skill ON skill.id = version.skill_id
   WHERE version.id = NEW.pinned_skill_version_id
     AND version.skill_id = NEW.skill_id
     AND version.deleted = false
     AND skill.deleted = false;
  IF NOT FOUND OR v_skill_scope <> 'TENANT' OR v_skill_tenant <> NEW.tenant_id
      OR v_version_status <> 'PUBLISHED' THEN
    RAISE EXCEPTION 'Agent binding requires a published tenant Skill version, agentId=%, skillId=%, versionId=%',
      NEW.agent_id, NEW.skill_id, NEW.pinned_skill_version_id;
  END IF;
  SELECT tenant_id INTO v_agent_tenant
    FROM data_agent
   WHERE id = NEW.agent_id AND COALESCE(deleted, false) = false;
  IF NOT FOUND OR v_agent_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'Agent tenant does not match Skill binding tenant, agentId=%, tenantId=%',
      NEW.agent_id, NEW.tenant_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_skill_binding_validate ON data_agent_skill_binding;
CREATE TRIGGER trg_data_agent_skill_binding_validate
BEFORE INSERT OR UPDATE OF tenant_id, agent_id, skill_id, pinned_skill_version_id, deleted ON data_agent_skill_binding
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_binding();

CREATE OR REPLACE FUNCTION dataagent_validate_flow_skill_version()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_tenant_id VARCHAR(64);
  v_status VARCHAR(32);
  v_execution_mode VARCHAR(32);
  v_agent_tenant VARCHAR(64);
BEGIN
  IF COALESCE(NEW.deleted, false) THEN
    RETURN NEW;
  END IF;
  SELECT skill.tenant_id, version.status, version.execution_mode
    INTO v_tenant_id, v_status, v_execution_mode
    FROM data_agent_skill_version version
    JOIN data_agent_skill skill ON skill.id = version.skill_id
   WHERE version.id = NEW.skill_version_id
     AND version.skill_id = NEW.skill_id
     AND version.deleted = false
     AND skill.deleted = false;
  IF NOT FOUND OR v_tenant_id <> NEW.tenant_id OR v_status <> 'PUBLISHED'
      OR v_execution_mode <> 'FLOW' THEN
    RAISE EXCEPTION 'FLOW instance requires a published tenant Skill version, skillId=%, versionId=%',
      NEW.skill_id, NEW.skill_version_id;
  END IF;
  SELECT tenant_id INTO v_agent_tenant
    FROM data_agent
   WHERE id = NEW.agent_id AND COALESCE(deleted, false) = false;
  IF NOT FOUND OR v_agent_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'FLOW instance agent tenant does not match Skill tenant, agentId=%, tenantId=%',
      NEW.agent_id, NEW.tenant_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_flow_instance_validate ON data_agent_flow_instance;
CREATE TRIGGER trg_data_agent_flow_instance_validate
BEFORE INSERT OR UPDATE OF tenant_id, agent_id, skill_id, skill_version_id, deleted ON data_agent_flow_instance
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_flow_skill_version();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_shape()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.scope <> 'TENANT' OR NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Skill must belong to a tenant, skillId=%', NEW.id;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
     WHERE version.skill_id = NEW.id
       AND version.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Skill tenant cannot differ from its versions, skillId=%', NEW.id;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_binding binding
     WHERE binding.skill_id = NEW.id
       AND COALESCE(binding.deleted, false) = false
       AND binding.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Skill tenant cannot differ from its active bindings, skillId=%', NEW.id;
  END IF;
  IF NEW.skill_kind = 'QUERY' AND (
    SELECT count(*)
      FROM skill_datasource
     WHERE skill_id = NEW.id
       AND COALESCE(is_active, false)
       AND COALESCE(deleted, false) = false
  ) > 1 THEN
    RAISE EXCEPTION 'QUERY Skill can have only one active datasource, skillId=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_skill_shape ON data_agent_skill;
CREATE TRIGGER trg_data_agent_skill_shape
BEFORE UPDATE OF scope, tenant_id, skill_kind, deleted ON data_agent_skill
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_shape();


