CREATE TABLE IF NOT EXISTS agent_im_setup_session (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  setup_id VARCHAR(64) NOT NULL,
  provider VARCHAR(32) NOT NULL,
  connect_mode VARCHAR(32) NOT NULL,
  setup_source VARCHAR(32),
  setup_status VARCHAR(32) NOT NULL,
  connector_code VARCHAR(128),
  connector_name VARCHAR(128),
  default_agent_id BIGINT,
  direct_enabled BOOLEAN DEFAULT true,
  group_enabled BOOLEAN DEFAULT false,
  requested_config TEXT,
  validation_result TEXT,
  result_connector_code VARCHAR(128),
  expire_time TIMESTAMP(6) NOT NULL,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_im_setup_session IS 'IM 接入安装会话';
COMMENT ON COLUMN agent_im_setup_session.id IS '主键ID';
