COMMENT ON COLUMN agent_im_setup_session.default_agent_id IS '默认绑定智能体ID';
COMMENT ON COLUMN agent_im_setup_session.direct_enabled IS '是否启用单聊';
COMMENT ON COLUMN agent_im_setup_session.group_enabled IS '是否启用群聊';
COMMENT ON COLUMN agent_im_setup_session.requested_config IS '向导请求配置';
COMMENT ON COLUMN agent_im_setup_session.validation_result IS '凭据校验结果';
COMMENT ON COLUMN agent_im_setup_session.result_connector_code IS '生成的连接器编码';
COMMENT ON COLUMN agent_im_setup_session.expire_time IS '过期时间';
COMMENT ON COLUMN agent_im_setup_session.create_by IS '创建人账号';
COMMENT ON COLUMN agent_im_setup_session.create_name IS '创建人名称';
COMMENT ON COLUMN agent_im_setup_session.create_time IS '创建时间';
COMMENT ON COLUMN agent_im_setup_session.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_im_setup_session.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_im_setup_session.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_im_setup_session.deleted IS '逻辑删除标识';

CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_im_connector_code
