  ON agent_im_conversation_binding(provider, connector_code, conversation_type, external_conversation_id)
  WHERE COALESCE(deleted, false) = false;

CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_im_user_identity_external
  ON agent_im_user_identity(provider, COALESCE(connector_code, ''), external_user_id)
  WHERE COALESCE(deleted, false) = false;

