  WHERE COALESCE(deleted, false) = false;

CREATE INDEX IF NOT EXISTS idx_agent_im_conversation_agent
  ON agent_im_conversation_binding(agent_id, status)
  WHERE COALESCE(deleted, false) = false;

CREATE INDEX IF NOT EXISTS idx_agent_im_identity_user
  ON agent_im_user_identity(user_id, bind_status)
  WHERE COALESCE(deleted, false) = false;

CREATE INDEX IF NOT EXISTS idx_agent_channel_session_session
  ON agent_channel_session_mapping(session_id, status)
  WHERE COALESCE(deleted, false) = false;

CREATE INDEX IF NOT EXISTS idx_agent_im_message_runtime
