  WHERE COALESCE(deleted, false) = false;

-- 以下对象按 cortpdb_dev.agent 的实际结构补齐。

-- 平台化语音播报与实时语音助手能力（PostgreSQL）
-- 普通问答主链路不变，语音能力通过独立配置和接口启用。

CREATE TABLE IF NOT EXISTS model_tts_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  model_config_id BIGINT NOT NULL REFERENCES model_config(id) ON DELETE CASCADE,
  speech_path VARCHAR(255),
  speech_stream_path VARCHAR(255),
  tts_protocol VARCHAR(20) DEFAULT 'http',
  streaming_enabled BOOLEAN DEFAULT false,
  default_format VARCHAR(20) DEFAULT 'mp3',
  default_sample_rate INTEGER DEFAULT 24000,
  options JSONB DEFAULT '{}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS tts_voice_sample (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  file_id VARCHAR(128) NOT NULL,
  file_name VARCHAR(255),
  file_path VARCHAR(500),
  content_type VARCHAR(100),
  duration_ms INTEGER,
  sample_rate INTEGER,
  transcript TEXT,
  consent_confirmed BOOLEAN DEFAULT false,
  status VARCHAR(30) DEFAULT 'READY',
  error_message TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS tts_voice_profile (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tts_config_id BIGINT NOT NULL REFERENCES model_tts_config(id) ON DELETE CASCADE,
  profile_name VARCHAR(100) NOT NULL,
  voice_name VARCHAR(100),
  voice_label VARCHAR(100),
  voice_source VARCHAR(30) DEFAULT 'SYSTEM',
  sample_id BIGINT REFERENCES tts_voice_sample(id) ON DELETE SET NULL,
  language_code VARCHAR(20),
  gender VARCHAR(20),
  speech_speed NUMERIC(4,2) DEFAULT 1.00,
  pitch NUMERIC(5,2) DEFAULT 0.00,
  volume_gain NUMERIC(5,2) DEFAULT 0.00,
  speech_format VARCHAR(20),
  sample_rate INTEGER,
  options JSONB DEFAULT '{}'::jsonb,
  is_default BOOLEAN DEFAULT false,
  enabled BOOLEAN DEFAULT true,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS realtime_voice_session (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  session_id VARCHAR(128),
  agent_id BIGINT,
  mode VARCHAR(30) NOT NULL,
  transport VARCHAR(30) NOT NULL,
  status VARCHAR(30) DEFAULT 'CREATED',
  voice_profile_id BIGINT REFERENCES tts_voice_profile(id) ON DELETE SET NULL,
  allow_interrupt BOOLEAN DEFAULT true,
  vad_enabled BOOLEAN DEFAULT true,
  session_options JSONB DEFAULT '{}'::jsonb,
  started_at TIMESTAMP,
  ended_at TIMESTAMP,
  error_message TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false,
  thread_id VARCHAR(128),
  realtime_config_id BIGINT,
  runtime_mode VARCHAR(30) DEFAULT 'PIPELINE',
  chat_model_config_id BIGINT,
  asr_model_config_id BIGINT,
  tts_model_config_id BIGINT,
  realtime_voice_model_config_id BIGINT,
  current_turn_id VARCHAR(128),
  last_sequence BIGINT DEFAULT 0,
  runtime_request_id VARCHAR(128),
  ws_token VARCHAR(128),
  ws_token_expires_at TIMESTAMP(6),
  error_code INTEGER
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_model_tts_config_model_active
  ON model_tts_config(model_config_id)
  WHERE deleted = false;

CREATE UNIQUE INDEX IF NOT EXISTS uk_tts_voice_profile_default_active
  ON tts_voice_profile(tts_config_id)
  WHERE deleted = false AND enabled = true AND is_default = true;

CREATE INDEX IF NOT EXISTS idx_tts_voice_profile_config
  ON tts_voice_profile(tts_config_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_tts_voice_sample_file_id
  ON tts_voice_sample(file_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_realtime_voice_session_session_id
  ON realtime_voice_session(session_id)
  WHERE deleted = false;

COMMENT ON TABLE model_tts_config IS 'TTS 能力配置，关联通用模型配置';
COMMENT ON COLUMN model_tts_config.model_config_id IS '关联 model_config.id，模型类型应为 TEXT_TO_SPEECH';
COMMENT ON COLUMN model_tts_config.speech_path IS '普通语音合成接口路径';
COMMENT ON COLUMN model_tts_config.speech_stream_path IS '流式语音合成接口路径';
COMMENT ON COLUMN model_tts_config.tts_protocol IS 'TTS 协议：http/websocket/local';
COMMENT ON COLUMN model_tts_config.streaming_enabled IS '是否启用流式 TTS';
COMMENT ON COLUMN model_tts_config.default_format IS '默认音频格式';
COMMENT ON COLUMN model_tts_config.default_sample_rate IS '默认采样率';
COMMENT ON COLUMN model_tts_config.options IS '供应商或本地 sidecar 扩展配置';

COMMENT ON TABLE tts_voice_sample IS 'TTS 本地参考音色样本';
COMMENT ON COLUMN tts_voice_sample.file_id IS '样本文件标识';
COMMENT ON COLUMN tts_voice_sample.file_path IS '样本文件存储路径';
COMMENT ON COLUMN tts_voice_sample.transcript IS '参考录音对应转写文本';
COMMENT ON COLUMN tts_voice_sample.consent_confirmed IS '是否确认拥有音色授权';
COMMENT ON COLUMN tts_voice_sample.status IS '样本状态：READY/FAILED';

COMMENT ON TABLE tts_voice_profile IS 'TTS 音色 Profile';
COMMENT ON COLUMN tts_voice_profile.tts_config_id IS '关联 model_tts_config.id';
COMMENT ON COLUMN tts_voice_profile.voice_name IS '供应商音色名称或自定义音色 ID';
COMMENT ON COLUMN tts_voice_profile.voice_source IS '音色来源：SYSTEM/CUSTOM/LOCAL_REFERENCE';
COMMENT ON COLUMN tts_voice_profile.sample_id IS '本地参考音色样本 ID';
COMMENT ON COLUMN tts_voice_profile.speech_speed IS '语速倍率';
COMMENT ON COLUMN tts_voice_profile.pitch IS '音调调整';
COMMENT ON COLUMN tts_voice_profile.volume_gain IS '音量增益';
COMMENT ON COLUMN tts_voice_profile.is_default IS '是否默认音色';

COMMENT ON TABLE realtime_voice_session IS '实时语音助手平台会话';
COMMENT ON COLUMN realtime_voice_session.mode IS '语音助手模式：PUSH_TO_TALK/CONTINUOUS_VOICE';
COMMENT ON COLUMN realtime_voice_session.transport IS '传输通道：HTTP/SSE/WEBSOCKET/WEBRTC';
COMMENT ON COLUMN realtime_voice_session.status IS '会话状态：CREATED/ACTIVE/INTERRUPTED/ENDED/FAILED';
COMMENT ON COLUMN realtime_voice_session.allow_interrupt IS '是否允许打断当前播报和生成';
COMMENT ON COLUMN realtime_voice_session.vad_enabled IS '是否启用服务端 VAD';
COMMENT ON COLUMN realtime_voice_session.session_options IS '实时会话扩展配置';

-- 实时语音对话 PIPELINE + WEBSOCKET 配置补齐（PostgreSQL）
-- 说明：业务参数进入数据库和页面配置，不新增 application.yml 业务配置。

COMMENT ON COLUMN model_config.model_type IS '模型类型：CHAT/EMBEDDING/AUDIO_TRANSCRIPTION/TEXT_TO_SPEECH/REALTIME_VOICE';

CREATE TABLE IF NOT EXISTS model_asr_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  model_config_id BIGINT NOT NULL,
  transcription_path VARCHAR(255),
  transcription_stream_path VARCHAR(500),
  asr_protocol VARCHAR(30) DEFAULT 'http',
  streaming_enabled BOOLEAN DEFAULT false,
  default_audio_format VARCHAR(30) DEFAULT 'webm',
  default_sample_rate INTEGER DEFAULT 16000,
  vad_supported BOOLEAN DEFAULT true,
  hotword_supported BOOLEAN DEFAULT false,
  options JSONB DEFAULT '{}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS model_realtime_voice_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  model_config_id BIGINT NOT NULL,
  websocket_url VARCHAR(500),
  webrtc_url VARCHAR(500),
  input_audio_format VARCHAR(30) DEFAULT 'PCM16',
  output_audio_format VARCHAR(30) DEFAULT 'PCM16',
  input_sample_rate INTEGER DEFAULT 16000,
  output_sample_rate INTEGER DEFAULT 24000,
  turn_detection_type VARCHAR(50) DEFAULT 'server_vad',
  voice_name VARCHAR(100),
  transcript_enabled BOOLEAN DEFAULT true,
  tool_call_enabled BOOLEAN DEFAULT true,
  interrupt_supported BOOLEAN DEFAULT true,
  options JSONB DEFAULT '{}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE TABLE IF NOT EXISTS realtime_voice_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  agent_id BIGINT,
  config_name VARCHAR(100) NOT NULL,
  runtime_mode VARCHAR(30) NOT NULL DEFAULT 'PIPELINE',
  transport VARCHAR(30) NOT NULL DEFAULT 'WEBSOCKET',
  chat_model_config_id BIGINT,
  asr_model_config_id BIGINT,
  tts_model_config_id BIGINT,
  realtime_voice_model_config_id BIGINT,
  voice_profile_id BIGINT,
  input_audio_format VARCHAR(30) DEFAULT 'PCM16',
  input_sample_rate INTEGER DEFAULT 16000,
  output_audio_format VARCHAR(30) DEFAULT 'PCM16',
  output_sample_rate INTEGER DEFAULT 24000,
  vad_enabled BOOLEAN DEFAULT true,
  allow_interrupt BOOLEAN DEFAULT true,
  partial_transcript_enabled BOOLEAN DEFAULT true,
  text_record_enabled BOOLEAN DEFAULT true,
  fallback_enabled BOOLEAN DEFAULT true,
  fallback_strategy VARCHAR(50) DEFAULT 'RECORDING_ASR',
  connect_timeout_ms INTEGER DEFAULT 10000,
  read_timeout_ms INTEGER DEFAULT 60000,
  idle_timeout_ms INTEGER DEFAULT 60000,
  max_turn_duration_ms INTEGER DEFAULT 60000,
  heartbeat_interval_ms INTEGER DEFAULT 15000,
  is_default BOOLEAN DEFAULT false,
  enabled BOOLEAN DEFAULT true,
  options JSONB DEFAULT '{}'::jsonb,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_model_asr_config_model_config_id
  ON model_asr_config(model_config_id)
  WHERE deleted = false;

CREATE UNIQUE INDEX IF NOT EXISTS idx_model_realtime_voice_config_model_config_id
  ON model_realtime_voice_config(model_config_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_realtime_voice_config_agent_id
  ON realtime_voice_config(agent_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_realtime_voice_config_is_default
  ON realtime_voice_config(is_default)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_realtime_voice_session_session_id
  ON realtime_voice_session(session_id)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS idx_realtime_voice_session_ws_token
  ON realtime_voice_session(ws_token)
  WHERE deleted = false;

COMMENT ON TABLE model_asr_config IS 'ASR 能力配置';
COMMENT ON COLUMN model_asr_config.model_config_id IS '关联 model_config.id，模型类型应为 AUDIO_TRANSCRIPTION';
COMMENT ON COLUMN model_asr_config.transcription_path IS '普通语音转写接口路径';
COMMENT ON COLUMN model_asr_config.transcription_stream_path IS '流式语音转写接口或 WebSocket 地址';
COMMENT ON COLUMN model_asr_config.asr_protocol IS 'ASR 协议：http/websocket/local';
COMMENT ON COLUMN model_asr_config.streaming_enabled IS '是否启用真流式 ASR';
COMMENT ON COLUMN model_asr_config.default_audio_format IS '默认音频格式';
COMMENT ON COLUMN model_asr_config.default_sample_rate IS '默认采样率';
COMMENT ON COLUMN model_asr_config.vad_supported IS '是否支持 VAD';
COMMENT ON COLUMN model_asr_config.hotword_supported IS '是否支持热词';
COMMENT ON COLUMN model_asr_config.options IS '供应商扩展配置';

COMMENT ON TABLE model_realtime_voice_config IS '一体化实时语音模型配置';
COMMENT ON COLUMN model_realtime_voice_config.model_config_id IS '关联 model_config.id，模型类型应为 REALTIME_VOICE';
COMMENT ON COLUMN model_realtime_voice_config.websocket_url IS '厂商实时语音 WebSocket 地址';
COMMENT ON COLUMN model_realtime_voice_config.webrtc_url IS '厂商实时语音 WebRTC 地址';
COMMENT ON COLUMN model_realtime_voice_config.input_audio_format IS '输入音频格式';
COMMENT ON COLUMN model_realtime_voice_config.output_audio_format IS '输出音频格式';
COMMENT ON COLUMN model_realtime_voice_config.input_sample_rate IS '输入采样率';
COMMENT ON COLUMN model_realtime_voice_config.output_sample_rate IS '输出采样率';
COMMENT ON COLUMN model_realtime_voice_config.turn_detection_type IS '轮次检测类型';
COMMENT ON COLUMN model_realtime_voice_config.voice_name IS '默认音色名称';
COMMENT ON COLUMN model_realtime_voice_config.transcript_enabled IS '是否返回转写文本';
COMMENT ON COLUMN model_realtime_voice_config.tool_call_enabled IS '是否支持工具调用';
COMMENT ON COLUMN model_realtime_voice_config.interrupt_supported IS '是否支持打断';
COMMENT ON COLUMN model_realtime_voice_config.options IS '供应商扩展配置';

COMMENT ON TABLE realtime_voice_config IS '智能体实时语音配置';
COMMENT ON COLUMN realtime_voice_config.agent_id IS '智能体ID，空表示全局默认配置';
COMMENT ON COLUMN realtime_voice_config.config_name IS '配置名称';
COMMENT ON COLUMN realtime_voice_config.runtime_mode IS '运行模式：PIPELINE/REALTIME';
COMMENT ON COLUMN realtime_voice_config.transport IS '传输方式：第一版默认 WEBSOCKET';
COMMENT ON COLUMN realtime_voice_config.chat_model_config_id IS 'CHAT 模型配置ID';
COMMENT ON COLUMN realtime_voice_config.asr_model_config_id IS 'ASR 模型配置ID';
COMMENT ON COLUMN realtime_voice_config.tts_model_config_id IS 'TTS 模型配置ID';
COMMENT ON COLUMN realtime_voice_config.realtime_voice_model_config_id IS 'REALTIME_VOICE 模型配置ID';
COMMENT ON COLUMN realtime_voice_config.voice_profile_id IS 'TTS 音色 Profile ID';
COMMENT ON COLUMN realtime_voice_config.input_audio_format IS '输入音频格式';
COMMENT ON COLUMN realtime_voice_config.input_sample_rate IS '输入采样率';
COMMENT ON COLUMN realtime_voice_config.output_audio_format IS '输出音频格式';
COMMENT ON COLUMN realtime_voice_config.output_sample_rate IS '输出采样率';
COMMENT ON COLUMN realtime_voice_config.vad_enabled IS '是否启用 VAD';
COMMENT ON COLUMN realtime_voice_config.allow_interrupt IS '是否允许打断';
COMMENT ON COLUMN realtime_voice_config.partial_transcript_enabled IS '是否显示临时字幕';
COMMENT ON COLUMN realtime_voice_config.text_record_enabled IS '是否保存文字记录';
COMMENT ON COLUMN realtime_voice_config.fallback_enabled IS '是否启用降级';
COMMENT ON COLUMN realtime_voice_config.fallback_strategy IS '降级策略';
COMMENT ON COLUMN realtime_voice_config.connect_timeout_ms IS '连接超时毫秒';
COMMENT ON COLUMN realtime_voice_config.read_timeout_ms IS '读取超时毫秒';
COMMENT ON COLUMN realtime_voice_config.idle_timeout_ms IS '空闲超时毫秒';
COMMENT ON COLUMN realtime_voice_config.max_turn_duration_ms IS '最大单轮时长毫秒';
COMMENT ON COLUMN realtime_voice_config.heartbeat_interval_ms IS '心跳间隔毫秒';
