CREATE UNIQUE INDEX IF NOT EXISTS uk_data_agent_eval_policy_code
  ON data_agent_eval_policy(tenant_id, policy_code)
  WHERE deleted = false;
CREATE UNIQUE INDEX IF NOT EXISTS uk_data_agent_eval_policy_default
  ON data_agent_eval_policy(tenant_id, COALESCE(subject_type, ''))
  WHERE deleted = false AND default_flag = true AND status = 'enabled';
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_subject_type
  ON data_agent_eval_subject(subject_type, subject_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_suite_subject_id
  ON data_agent_eval_suite(subject_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_case_suite_id
  ON data_agent_eval_case(suite_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_run_suite_id
  ON data_agent_eval_run(suite_id, create_time DESC)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_result_run_id
  ON data_agent_eval_case_result(run_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_eval_result_runtime_request_id
  ON data_agent_eval_case_result(runtime_request_id)
  WHERE deleted = false;

-- 自优化中心表结构。
CREATE TABLE IF NOT EXISTS data_agent_opt_experiment (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  tenant_code VARCHAR(128),
  experiment_name VARCHAR(128) NOT NULL,
  subject_id BIGINT,
  owner_type VARCHAR(64),
  owner_id VARCHAR(128),
  baseline_run_id BIGINT NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'draft',
  baseline_metrics_json TEXT,
  diagnosis_json TEXT,
  description VARCHAR(512),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

