COMMENT ON COLUMN data_agent_opt_experiment.baseline_run_id IS '基线评估运行ID';
COMMENT ON COLUMN data_agent_opt_experiment.status IS '实验状态';
COMMENT ON COLUMN data_agent_opt_experiment.baseline_metrics_json IS '基线指标JSON';
COMMENT ON COLUMN data_agent_opt_experiment.diagnosis_json IS '诊断结果JSON';
COMMENT ON COLUMN data_agent_opt_experiment.description IS '实验说明';

CREATE TABLE IF NOT EXISTS data_agent_opt_candidate (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  tenant_code VARCHAR(128),
  experiment_id BIGINT NOT NULL,
  candidate_name VARCHAR(128) NOT NULL,
