  target_id VARCHAR(128) NOT NULL,
  patch_schema_version VARCHAR(32),
  target_version VARCHAR(64),
  before_hash VARCHAR(128) NOT NULL,
  after_hash VARCHAR(128) NOT NULL,
  change_reason VARCHAR(512),
  expected_impact VARCHAR(512),
  patch_json TEXT NOT NULL,
  before_snapshot_json TEXT,
  rollback_patch_json TEXT,
  risk_level VARCHAR(32),
  generated_by VARCHAR(64),
  sandbox_run_id BIGINT,
  gate_result_json TEXT,
  status VARCHAR(32) NOT NULL DEFAULT 'draft',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE data_agent_opt_candidate IS 'Agent 自优化候选版本表';
COMMENT ON COLUMN data_agent_opt_candidate.tenant_id IS '租户ID';
COMMENT ON COLUMN data_agent_opt_candidate.tenant_code IS '租户编码';
COMMENT ON COLUMN data_agent_opt_candidate.experiment_id IS '优化实验ID';
COMMENT ON COLUMN data_agent_opt_candidate.candidate_name IS '候选名称';
COMMENT ON COLUMN data_agent_opt_candidate.target_type IS '目标类型';
COMMENT ON COLUMN data_agent_opt_candidate.target_id IS '目标ID';
COMMENT ON COLUMN data_agent_opt_candidate.patch_schema_version IS '补丁结构版本';
COMMENT ON COLUMN data_agent_opt_candidate.target_version IS '目标配置版本';
COMMENT ON COLUMN data_agent_opt_candidate.before_hash IS '变更前哈希';
COMMENT ON COLUMN data_agent_opt_candidate.after_hash IS '变更后哈希';
COMMENT ON COLUMN data_agent_opt_candidate.change_reason IS '变更原因';
COMMENT ON COLUMN data_agent_opt_candidate.expected_impact IS '预期影响';
COMMENT ON COLUMN data_agent_opt_candidate.patch_json IS '候选补丁JSON';
COMMENT ON COLUMN data_agent_opt_candidate.before_snapshot_json IS '变更前快照JSON';
COMMENT ON COLUMN data_agent_opt_candidate.rollback_patch_json IS '回滚补丁JSON';
COMMENT ON COLUMN data_agent_opt_candidate.risk_level IS '风险等级';
COMMENT ON COLUMN data_agent_opt_candidate.generated_by IS '生成来源';
COMMENT ON COLUMN data_agent_opt_candidate.sandbox_run_id IS '候选沙箱运行ID';
COMMENT ON COLUMN data_agent_opt_candidate.gate_result_json IS '门禁结果JSON';
COMMENT ON COLUMN data_agent_opt_candidate.status IS '候选状态';

CREATE TABLE IF NOT EXISTS data_agent_opt_candidate_eval (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  tenant_code VARCHAR(128),
  experiment_id BIGINT NOT NULL,
  candidate_id BIGINT NOT NULL,
  baseline_run_id BIGINT NOT NULL,
  sandbox_run_id BIGINT NOT NULL,
  score_delta NUMERIC(8, 2),
  pass_rate_delta NUMERIC(8, 2),
  duration_delta_pct NUMERIC(8, 2),
  token_delta_pct NUMERIC(8, 2),
  passed BOOLEAN DEFAULT false,
  compare_json TEXT,
  status VARCHAR(32) NOT NULL DEFAULT 'blocked',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

