COMMENT ON COLUMN data_agent_opt_candidate_eval.score_delta IS '分数差值';
COMMENT ON COLUMN data_agent_opt_candidate_eval.pass_rate_delta IS '通过率差值';
COMMENT ON COLUMN data_agent_opt_candidate_eval.duration_delta_pct IS '耗时变化百分比';
COMMENT ON COLUMN data_agent_opt_candidate_eval.token_delta_pct IS 'Token 变化百分比';
COMMENT ON COLUMN data_agent_opt_candidate_eval.passed IS '是否通过门禁';
COMMENT ON COLUMN data_agent_opt_candidate_eval.compare_json IS '对比结果JSON';
COMMENT ON COLUMN data_agent_opt_candidate_eval.status IS '评估状态';

CREATE TABLE IF NOT EXISTS data_agent_opt_release (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  tenant_code VARCHAR(128),
  experiment_id BIGINT NOT NULL,
  candidate_id BIGINT NOT NULL,
  source_release_id BIGINT,
  action_type VARCHAR(32) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'recorded',
  before_hash VARCHAR(128),
  after_hash VARCHAR(128),
  operator_id VARCHAR(64),
  reason VARCHAR(512),
  approval_json TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE data_agent_opt_release IS 'Agent 自优化发布记录表';
COMMENT ON COLUMN data_agent_opt_release.tenant_id IS '租户ID';
COMMENT ON COLUMN data_agent_opt_release.tenant_code IS '租户编码';
COMMENT ON COLUMN data_agent_opt_release.experiment_id IS '优化实验ID';
COMMENT ON COLUMN data_agent_opt_release.candidate_id IS '候选ID';
COMMENT ON COLUMN data_agent_opt_release.source_release_id IS '来源发布记录ID';
COMMENT ON COLUMN data_agent_opt_release.action_type IS '操作类型';
COMMENT ON COLUMN data_agent_opt_release.status IS '发布状态';
COMMENT ON COLUMN data_agent_opt_release.before_hash IS '发布前哈希';
COMMENT ON COLUMN data_agent_opt_release.after_hash IS '发布后哈希';
COMMENT ON COLUMN data_agent_opt_release.operator_id IS '操作人ID';
COMMENT ON COLUMN data_agent_opt_release.reason IS '操作原因';
COMMENT ON COLUMN data_agent_opt_release.approval_json IS '审批记录JSON';

CREATE INDEX IF NOT EXISTS idx_data_agent_opt_experiment_subject_id
  ON data_agent_opt_experiment(subject_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_experiment_owner
  ON data_agent_opt_experiment(owner_type, owner_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_experiment_baseline_run_id
  ON data_agent_opt_experiment(baseline_run_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_candidate_experiment_id
  ON data_agent_opt_candidate(experiment_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_candidate_target_id
  ON data_agent_opt_candidate(target_type, target_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_candidate_eval_candidate_id
  ON data_agent_opt_candidate_eval(candidate_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_release_candidate_id
  ON data_agent_opt_release(candidate_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS idx_data_agent_opt_release_source_release_id
  ON data_agent_opt_release(source_release_id)
  WHERE deleted = false;

CREATE TABLE IF NOT EXISTS dataagent_chat_session_migration_map (
  old_session_id VARCHAR(36),
  new_session_id BIGINT NOT NULL
);

-- =============================================================================
-- Group A: 02-runtime
-- =============================================================================

-- ============================================================================
-- W2 持久运行时：权威运行状态存储（数字员工方案 第七章 / 第十六章 P1）
-- 用途：为 AI Agent 运行时提供 Run/Plan/Step/Attempt/Invocation/Artifact/Event/
--       Outbox/Interruption/Approval/BudgetLedger 共 11 张权威状态表，
--       支撑 CAS + lease + fence + cancellation epoch、幂等创建、事件回放。
-- 影响范围：仅新增表，不修改既有表；既有遥测表 agent_orchestration_run /
--       agent_orchestration_step 保留并继续写入，本文件中的新表为权威状态源。
-- 兼容性：仅适用于 PostgreSQL（JSONB、部分唯一索引）。
-- 重建说明：本批表尚未上线、无存量数据，可整体 DROP 后重建（下方 DROP 段）。
-- 回滚：DROP 本文件创建的 11 张表即可，不影响任何既有表与数据。
--
-- 【2026-08 P0 安全修订，本批未上线故直接改建表语句而非增量迁移】
--   1. agent_runtime_run 幂等唯一键补 tenant_id：原 (workspace_id, client_request_id) 全局唯一，
--      而任务链路的 client_request_id 是可枚举确定值（SCHEDULE:{triggerId}:{计划时刻}），
--      攻击者抢占该键即可让受害租户的定时任务永久无法创建 Run（跨租户 DoS）。
--   2. agent_runtime_approval 新增 workspace_id 列 + PENDING 部分唯一索引，approval_key 加宽：
--      审批凭据粒度细化到（租户 + 工作空间 + 运行 + 能力 + 参数指纹），杜绝跨工作空间复用批复。
--   回滚：本批表整体 DROP 重建即可；若已有环境按旧结构建过，需先 DROP 旧索引再按本文件重建。
--
-- 【2026-08 数字员工运行归属，本批未上线故直接改建表语句而非增量迁移】
--   用途：agent_runtime_run 增加 employee_binding_id（可空）+ (租户,工作空间,员工) 部分索引，
--      让「TA 的运行」从 (workspace_id + agent_id) 的近似过滤升级为按数字员工绑定精确过滤——
--      同一工作空间内同一智能体可绑定多个 Release（即多个数字员工），近似过滤会把它们混在一起。
--   影响范围：仅本表新增一列一索引，不改既有列与既有索引；写入侧只有任务链路
--      （DefaultTaskRunLauncher，取 agent_task_definition.employee_binding_id）会落值。
--   兼容性：列可空，PostgreSQL 加列不重写堆表；既有 INSERT/SELECT 语句不受影响。
--   历史行：CHAT / 直接 API / 编排镜像（LEGACY_ORCHESTRATION）等触发天然无数字员工绑定，该列恒为 NULL，
--      按员工筛选时不出现属预期行为，不需要回填。本批表未上线，无生产存量数据；
--      若某环境已按旧结构建过表且需保留数据，用下方注释的 ALTER + 回填语句（仅任务链路可推导绑定）。
--   回滚：DROP INDEX agent_runtime_run_idx_tenant_workspace_employee;
--      ALTER TABLE agent_runtime_run DROP COLUMN employee_binding_id;（或整表 DROP 重建）
-- ============================================================================

BEGIN;

-- 未上线，可安全 DROP 重建
DROP TABLE IF EXISTS agent_runtime_budget_ledger;
DROP TABLE IF EXISTS agent_runtime_approval;
DROP TABLE IF EXISTS agent_runtime_interruption;
DROP TABLE IF EXISTS agent_runtime_outbox;
DROP TABLE IF EXISTS agent_runtime_event;
DROP TABLE IF EXISTS agent_runtime_artifact;
DROP TABLE IF EXISTS agent_runtime_invocation;
DROP TABLE IF EXISTS agent_runtime_step_attempt;
DROP TABLE IF EXISTS agent_runtime_step;
DROP TABLE IF EXISTS agent_runtime_plan;
DROP TABLE IF EXISTS agent_runtime_run;

-- ----------------------------------------------------------------------------
-- 1. agent_runtime_run：权威运行记录（一次实际执行）
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_run (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  workspace_id BIGINT NOT NULL DEFAULT 0,
  employee_binding_id BIGINT,
  owner_type VARCHAR(32),
  owner_id BIGINT,
  digital_employee_id BIGINT,
  tenant_id_str VARCHAR(64),
  release_id BIGINT,
  agent_id BIGINT,
  client_request_id VARCHAR(128) NOT NULL,
  thread_id VARCHAR(128),
  runtime_request_id VARCHAR(128),
  source_run_id BIGINT,
  trigger_source VARCHAR(32) DEFAULT 'API',
  run_mode VARCHAR(32),
  query TEXT,
  state VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  state_version BIGINT NOT NULL DEFAULT 0,
  lease_owner VARCHAR(128),
  lease_until TIMESTAMP,
  fence_token BIGINT NOT NULL DEFAULT 0,
  cancellation_epoch BIGINT NOT NULL DEFAULT 0,
  deadline_at TIMESTAMP,
  final_answer TEXT,
  error_code VARCHAR(100),
  error_message TEXT,
  started_at TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_run IS '持久运行时权威运行记录';
COMMENT ON COLUMN agent_runtime_run.id IS '主键ID（run_id）';
COMMENT ON COLUMN agent_runtime_run.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_run.workspace_id IS 'AI 工作空间ID，0 表示未绑定工作空间';
COMMENT ON COLUMN agent_runtime_run.employee_binding_id IS '数字员工绑定ID（agent_workspace_employee.id），空表示本次运行不由数字员工发起（CHAT / 直接 API / 编排镜像）；同一工作空间内同一智能体可绑定多个 Release，按员工统计运行必须用本列而非 agent_id';
COMMENT ON COLUMN agent_runtime_run.owner_type IS '运行主体类型：DIGITAL_EMPLOYEE / CALLER / PLATFORM，空按 CALLER 兜底';
COMMENT ON COLUMN agent_runtime_run.owner_id IS '运行主体 ID（DIGITAL_EMPLOYEE 时为数字员工 ID，CALLER 时为用户 ID，可空）';
COMMENT ON COLUMN agent_runtime_run.digital_employee_id IS '所属数字员工 ID，空表示非数字员工发起';
COMMENT ON COLUMN agent_runtime_run.tenant_id_str IS 'tenant_id 双写载体';
COMMENT ON COLUMN agent_runtime_run.release_id IS 'DataAgent 发布版本ID，空表示未绑定 Release';
COMMENT ON COLUMN agent_runtime_run.agent_id IS '运行的 DataAgent ID';
COMMENT ON COLUMN agent_runtime_run.client_request_id IS '调用方请求ID，配合 tenant_id + workspace_id 做幂等创建；任务链路复用任务幂等键，取值可枚举，故唯一键必须带租户';
COMMENT ON COLUMN agent_runtime_run.thread_id IS '会话ID';
COMMENT ON COLUMN agent_runtime_run.runtime_request_id IS '运行时请求ID，用于与内存注册表/遥测链路关联';
COMMENT ON COLUMN agent_runtime_run.source_run_id IS '来源遥测表 agent_orchestration_run.id，双写迁移期关联用';
COMMENT ON COLUMN agent_runtime_run.trigger_source IS '触发来源：API、CHAT、IM、SCHEDULE、EVENT、LEGACY_ORCHESTRATION';
COMMENT ON COLUMN agent_runtime_run.run_mode IS '运行模式：CHAT、DIRECT、AGENT_LOOP、ORCHESTRATION、FLOW';
COMMENT ON COLUMN agent_runtime_run.query IS '用户问题或任务描述';
COMMENT ON COLUMN agent_runtime_run.state IS '运行状态：PENDING、RUNNING、WAITING_APPROVAL、WAITING_INPUT、CANCELLING、SUCCEEDED、FAILED、CANCELLED、TIMED_OUT';
COMMENT ON COLUMN agent_runtime_run.state_version IS '状态版本号，所有状态更新走 CAS（state_version 相等才允许更新并 +1）';
COMMENT ON COLUMN agent_runtime_run.lease_owner IS '当前租约持有者（节点标识）';
COMMENT ON COLUMN agent_runtime_run.lease_until IS '租约到期时间，过期后其他节点可带新 fence_token 接管';
COMMENT ON COLUMN agent_runtime_run.fence_token IS '栅栏令牌，每次租约获取/接管递增；旧 fence 不得覆盖新 fence 写入的状态';
COMMENT ON COLUMN agent_runtime_run.cancellation_epoch IS '取消纪元，取消请求递增；执行方发现纪元大于自身快照时应停止';
COMMENT ON COLUMN agent_runtime_run.deadline_at IS '绝对截止时间，超过后运行必须终止或转后台';
COMMENT ON COLUMN agent_runtime_run.final_answer IS '最终回答（仅展示用途，不作为下游结构化输入）';
COMMENT ON COLUMN agent_runtime_run.error_code IS '错误编码';
COMMENT ON COLUMN agent_runtime_run.error_message IS '错误信息';
COMMENT ON COLUMN agent_runtime_run.started_at IS '开始时间';
COMMENT ON COLUMN agent_runtime_run.finished_at IS '结束时间';
COMMENT ON COLUMN agent_runtime_run.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_run.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_run.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_run.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_run.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_run.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_run.deleted IS '逻辑删除';

-- 幂等创建唯一约束：重复请求不得重复创建 Run。
-- 必须带 tenant_id：client_request_id 由调用方给定（任务链路为 SCHEDULE:{triggerId}:{计划时刻} 这类
-- 可枚举确定值），不含租户的唯一键会让任意租户抢占他人的键，把幂等降级成跨租户拒绝服务。
CREATE UNIQUE INDEX agent_runtime_run_uk_tenant_workspace_client_request
  ON agent_runtime_run(tenant_id, workspace_id, client_request_id)
  WHERE deleted = false;
CREATE UNIQUE INDEX IF NOT EXISTS agent_runtime_run_uk_tenant_owner_client_request
  ON agent_runtime_run(tenant_id, owner_type, owner_id, client_request_id)
  WHERE deleted = false;

CREATE INDEX agent_runtime_run_idx_tenant_id ON agent_runtime_run(tenant_id, create_time) WHERE deleted = false;
CREATE INDEX agent_runtime_run_idx_thread_id ON agent_runtime_run(thread_id) WHERE deleted = false;
CREATE INDEX agent_runtime_run_idx_runtime_request_id ON agent_runtime_run(runtime_request_id) WHERE deleted = false;
CREATE INDEX agent_runtime_run_idx_source_run_id ON agent_runtime_run(source_run_id) WHERE deleted = false;
-- 租约过期接管扫描
CREATE INDEX agent_runtime_run_idx_state_lease_until ON agent_runtime_run(state, lease_until) WHERE deleted = false;
-- 数字员工维度分页：前端「TA 的运行」按 (tenant_id, workspace_id, employee_binding_id) 过滤 + id 倒序取页。
-- 既有 idx_tenant_id(tenant_id, create_time) 只覆盖租户前缀，工作空间与员工谓词仍需回表过滤。
-- 部分索引排除 employee_binding_id IS NULL 的行（CHAT / 直接 API / 编排镜像占多数），
-- 索引体积只随数字员工运行增长；等值谓词蕴含 NOT NULL，规划器可正常命中。
CREATE INDEX agent_runtime_run_idx_tenant_workspace_employee
  ON agent_runtime_run(tenant_id, workspace_id, employee_binding_id, id DESC)
  WHERE deleted = false AND employee_binding_id IS NOT NULL;

-- 【仅供已按旧结构建过表且需保留数据的环境参考，本文件默认走整表 DROP 重建，下列语句未执行】
-- ALTER TABLE agent_runtime_run ADD COLUMN employee_binding_id BIGINT;
-- 只有任务链路可反推绑定（其余触发来源天然无绑定，保持 NULL）：
-- UPDATE agent_runtime_run r
--    SET employee_binding_id = d.employee_binding_id
--   FROM agent_task_run tr
--   JOIN agent_task_definition d ON d.id = tr.definition_id
--  WHERE tr.runtime_run_id = r.id
--    AND r.employee_binding_id IS NULL;

-- ----------------------------------------------------------------------------
-- 2. agent_runtime_plan：服务端编译后的不可变执行计划
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_plan (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  plan_version INTEGER NOT NULL DEFAULT 1,
  plan_hash VARCHAR(128),
  status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
  compiled_plan JSONB NOT NULL DEFAULT '{}'::jsonb,
  dag_edges JSONB NOT NULL DEFAULT '[]'::jsonb,
  step_count INTEGER NOT NULL DEFAULT 0,
  policy_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  absolute_deadline_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_plan IS '持久运行时编译执行计划（CompiledPlan 持久化，发布后不可原地修改）';
COMMENT ON COLUMN agent_runtime_plan.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_plan.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_plan.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_plan.plan_version IS '计划版本，未启动子图重规划时递增，同一 run 内唯一';
COMMENT ON COLUMN agent_runtime_plan.plan_hash IS '规范化计划内容哈希（canonical JSON hash）';
COMMENT ON COLUMN agent_runtime_plan.status IS '计划状态：ACTIVE 生效、SUPERSEDED 已被新版本替代、SHADOW 影子对比计划（灰度期 V1 决策经 V2 编译的对比产物，不参与执行）';
COMMENT ON COLUMN agent_runtime_plan.compiled_plan IS '编译后的规范化计划 JSON（含步骤、端口绑定、风险与审批要求）';
COMMENT ON COLUMN agent_runtime_plan.dag_edges IS 'DAG 依赖边清单，元素为 [fromStepKey, toStepKey]';
COMMENT ON COLUMN agent_runtime_plan.step_count IS '步骤数量';
COMMENT ON COLUMN agent_runtime_plan.policy_snapshot IS '执行策略快照（失败策略、预算、扇出上限等）';
COMMENT ON COLUMN agent_runtime_plan.absolute_deadline_at IS '计划级绝对截止时间';
COMMENT ON COLUMN agent_runtime_plan.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_plan.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_plan.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_plan.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_plan.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_plan.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_plan.deleted IS '逻辑删除';

CREATE UNIQUE INDEX agent_runtime_plan_uk_run_id_plan_version
  ON agent_runtime_plan(run_id, plan_version)
  WHERE deleted = false;

CREATE INDEX agent_runtime_plan_idx_run_id ON agent_runtime_plan(run_id) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 3. agent_runtime_step：运行步骤（权威状态）
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_step (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  plan_id BIGINT,
  step_key VARCHAR(128) NOT NULL,
  step_name VARCHAR(255),
  capability_handle VARCHAR(255),
  depends_on JSONB NOT NULL DEFAULT '[]'::jsonb,
  input_bindings JSONB NOT NULL DEFAULT '[]'::jsonb,
  state VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  state_version BIGINT NOT NULL DEFAULT 0,
  lease_owner VARCHAR(128),
  lease_until TIMESTAMP,
  fence_token BIGINT NOT NULL DEFAULT 0,
  cancellation_epoch BIGINT NOT NULL DEFAULT 0,
  deadline_at TIMESTAMP,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  max_attempts INTEGER NOT NULL DEFAULT 1,
  output_artifact_id BIGINT,
  error_code VARCHAR(100),
  error_message TEXT,
  started_at TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_step IS '持久运行时步骤记录（事件驱动 DAG 调度的权威状态）';
COMMENT ON COLUMN agent_runtime_step.id IS '主键ID（step_id）';
COMMENT ON COLUMN agent_runtime_step.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_step.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_step.plan_id IS '所属计划ID（agent_runtime_plan.id）';
COMMENT ON COLUMN agent_runtime_step.step_key IS '计划内步骤键，同一 run 内唯一';
COMMENT ON COLUMN agent_runtime_step.step_name IS '步骤展示名称';
COMMENT ON COLUMN agent_runtime_step.capability_handle IS '能力句柄（同一能力可被多个 step_key 重复使用）';
COMMENT ON COLUMN agent_runtime_step.depends_on IS '依赖的上游 step_key 清单（JSON 数组）';
COMMENT ON COLUMN agent_runtime_step.input_bindings IS '输入端口绑定清单（JSON 数组，来源为上游 Artifact）';
COMMENT ON COLUMN agent_runtime_step.state IS '步骤状态：PENDING、READY、RUNNING、WAITING、SUCCEEDED、FAILED、CANCELLED、TIMED_OUT、SKIPPED';
COMMENT ON COLUMN agent_runtime_step.state_version IS '状态版本号，所有状态更新走 CAS';
COMMENT ON COLUMN agent_runtime_step.lease_owner IS '当前租约持有者（节点标识）';
COMMENT ON COLUMN agent_runtime_step.lease_until IS '租约到期时间，过期后其他节点可带新 fence_token 接管';
COMMENT ON COLUMN agent_runtime_step.fence_token IS '栅栏令牌，租约获取/接管时递增；旧 fence 不得覆盖新终态';
COMMENT ON COLUMN agent_runtime_step.cancellation_epoch IS '取消纪元快照，用于识别执行期间发生的取消';
COMMENT ON COLUMN agent_runtime_step.deadline_at IS '步骤级截止时间';
COMMENT ON COLUMN agent_runtime_step.attempt_count IS '已产生的执行尝试次数';
COMMENT ON COLUMN agent_runtime_step.max_attempts IS '最大尝试次数';
COMMENT ON COLUMN agent_runtime_step.output_artifact_id IS '产出 Artifact ID（agent_runtime_artifact.id）';
COMMENT ON COLUMN agent_runtime_step.error_code IS '错误编码';
COMMENT ON COLUMN agent_runtime_step.error_message IS '错误信息';
COMMENT ON COLUMN agent_runtime_step.started_at IS '开始时间';
COMMENT ON COLUMN agent_runtime_step.finished_at IS '结束时间';
COMMENT ON COLUMN agent_runtime_step.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_step.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_step.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_step.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_step.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_step.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_step.deleted IS '逻辑删除';

CREATE UNIQUE INDEX agent_runtime_step_uk_run_id_step_key
  ON agent_runtime_step(run_id, step_key)
  WHERE deleted = false;

CREATE INDEX agent_runtime_step_idx_run_id ON agent_runtime_step(run_id) WHERE deleted = false;
CREATE INDEX agent_runtime_step_idx_run_id_state ON agent_runtime_step(run_id, state) WHERE deleted = false;
-- 租约过期接管扫描：守护作业按 (state='RUNNING', lease_until < now) 全表找崩溃节点遗留的步骤，
-- 没有本索引会退化为全表顺序扫描（同类索引在 agent_runtime_run 上已有 idx_state_lease_until）。
CREATE INDEX agent_runtime_step_idx_state_lease_until ON agent_runtime_step(state, lease_until) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 4. agent_runtime_step_attempt：步骤执行尝试
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_step_attempt (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  step_id BIGINT NOT NULL,
  attempt_no INTEGER NOT NULL,
  state VARCHAR(32) NOT NULL DEFAULT 'RUNNING',
  lease_owner VARCHAR(128),
  fence_token BIGINT NOT NULL DEFAULT 0,
  error_code VARCHAR(100),
  error_message TEXT,
  started_at TIMESTAMP,
  finished_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_step_attempt IS '持久运行时步骤执行尝试记录（每次认领执行产生一条）';
COMMENT ON COLUMN agent_runtime_step_attempt.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_step_attempt.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_step_attempt.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_step_attempt.step_id IS '所属步骤ID（agent_runtime_step.id）';
COMMENT ON COLUMN agent_runtime_step_attempt.attempt_no IS '尝试序号，从 1 开始，同一步骤内唯一';
COMMENT ON COLUMN agent_runtime_step_attempt.state IS '尝试状态：RUNNING、SUCCEEDED、FAILED、CANCELLED、TIMED_OUT';
COMMENT ON COLUMN agent_runtime_step_attempt.lease_owner IS '发起该尝试的租约持有者（节点标识）';
COMMENT ON COLUMN agent_runtime_step_attempt.fence_token IS '该尝试使用的栅栏令牌';
COMMENT ON COLUMN agent_runtime_step_attempt.error_code IS '错误编码';
COMMENT ON COLUMN agent_runtime_step_attempt.error_message IS '错误信息';
COMMENT ON COLUMN agent_runtime_step_attempt.started_at IS '开始时间';
COMMENT ON COLUMN agent_runtime_step_attempt.finished_at IS '结束时间';
COMMENT ON COLUMN agent_runtime_step_attempt.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_step_attempt.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_step_attempt.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_step_attempt.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_step_attempt.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_step_attempt.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_step_attempt.deleted IS '逻辑删除';

CREATE UNIQUE INDEX agent_runtime_step_attempt_uk_step_id_attempt_no
  ON agent_runtime_step_attempt(step_id, attempt_no)
  WHERE deleted = false;

CREATE INDEX agent_runtime_step_attempt_idx_run_id ON agent_runtime_step_attempt(run_id) WHERE deleted = false;
CREATE INDEX agent_runtime_step_attempt_idx_step_id ON agent_runtime_step_attempt(step_id) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 5. agent_runtime_invocation：外部副作用调用记录
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_invocation (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  step_id BIGINT,
  attempt_id BIGINT,
  idempotency_key VARCHAR(160) NOT NULL,
  capability_handle VARCHAR(255),
  invocation_type VARCHAR(32),
  state VARCHAR(32) NOT NULL DEFAULT 'DISPATCH_INTENT',
  state_version BIGINT NOT NULL DEFAULT 0,
  request_digest VARCHAR(128),
  response_digest VARCHAR(128),
  side_effect_receipt JSONB NOT NULL DEFAULT '{}'::jsonb,
  error_code VARCHAR(100),
  error_message TEXT,
  sent_at TIMESTAMP,
  completed_at TIMESTAMP,
  reconciled_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_invocation IS '持久运行时外部副作用调用记录（DISPATCH_INTENT → INVOCATION_SENT → SUCCESS/FAILED/OUTCOME_UNKNOWN → RECONCILING）';
COMMENT ON COLUMN agent_runtime_invocation.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_invocation.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_invocation.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_invocation.step_id IS '所属步骤ID（agent_runtime_step.id）';
COMMENT ON COLUMN agent_runtime_invocation.attempt_id IS '所属尝试ID（agent_runtime_step_attempt.id）';
COMMENT ON COLUMN agent_runtime_invocation.idempotency_key IS '幂等键，同一 run 内唯一；同一写操作不得重复下发';
COMMENT ON COLUMN agent_runtime_invocation.capability_handle IS '被调用能力句柄';
COMMENT ON COLUMN agent_runtime_invocation.invocation_type IS '调用类型：TOOL、SKILL、FLOW、AGENT、MCP、HTTP';
COMMENT ON COLUMN agent_runtime_invocation.state IS '调用状态：DISPATCH_INTENT、INVOCATION_SENT、SUCCESS、FAILED、OUTCOME_UNKNOWN、RECONCILING；OUTCOME_UNKNOWN 禁止自动重试';
COMMENT ON COLUMN agent_runtime_invocation.state_version IS '状态版本号，所有状态更新走 CAS';
COMMENT ON COLUMN agent_runtime_invocation.request_digest IS '请求参数摘要（不落原始敏感参数）';
COMMENT ON COLUMN agent_runtime_invocation.response_digest IS '响应内容摘要';
COMMENT ON COLUMN agent_runtime_invocation.side_effect_receipt IS '外部副作用凭证（订单号、调度单号等业务回执）';
COMMENT ON COLUMN agent_runtime_invocation.error_code IS '错误编码';
COMMENT ON COLUMN agent_runtime_invocation.error_message IS '错误信息';
COMMENT ON COLUMN agent_runtime_invocation.sent_at IS '外部请求实际发出时间（INVOCATION_SENT 时刻）';
COMMENT ON COLUMN agent_runtime_invocation.completed_at IS '终态时间';
COMMENT ON COLUMN agent_runtime_invocation.reconciled_at IS '对账完成时间';
COMMENT ON COLUMN agent_runtime_invocation.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_invocation.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_invocation.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_invocation.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_invocation.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_invocation.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_invocation.deleted IS '逻辑删除';

CREATE UNIQUE INDEX agent_runtime_invocation_uk_run_id_idempotency_key
  ON agent_runtime_invocation(run_id, idempotency_key)
  WHERE deleted = false;

CREATE INDEX agent_runtime_invocation_idx_run_id ON agent_runtime_invocation(run_id) WHERE deleted = false;
-- 对账扫描：OUTCOME_UNKNOWN / RECONCILING 的存量调用
CREATE INDEX agent_runtime_invocation_idx_state ON agent_runtime_invocation(state, create_time) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 6. agent_runtime_artifact：步骤间结构化产物
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_artifact (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  step_key VARCHAR(128),
  schema_version VARCHAR(64),
  data JSONB NOT NULL DEFAULT '{}'::jsonb,
  source_invocation_id BIGINT,
  sensitivity VARCHAR(32) DEFAULT 'INTERNAL',
  content_hash VARCHAR(128),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_artifact IS '持久运行时步骤产物（下游只读取 Artifact，不依赖自然语言）';
COMMENT ON COLUMN agent_runtime_artifact.id IS '主键ID（artifact_id）';
COMMENT ON COLUMN agent_runtime_artifact.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_artifact.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_artifact.step_key IS '产出步骤键';
COMMENT ON COLUMN agent_runtime_artifact.schema_version IS '产物数据结构版本';
COMMENT ON COLUMN agent_runtime_artifact.data IS '结构化产物数据（JSON）';
COMMENT ON COLUMN agent_runtime_artifact.source_invocation_id IS '来源调用ID（agent_runtime_invocation.id）';
COMMENT ON COLUMN agent_runtime_artifact.sensitivity IS '敏感级别：PUBLIC、INTERNAL、SENSITIVE';
COMMENT ON COLUMN agent_runtime_artifact.content_hash IS '产物内容哈希，用于缓存与一致性校验';
COMMENT ON COLUMN agent_runtime_artifact.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_artifact.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_artifact.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_artifact.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_artifact.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_artifact.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_artifact.deleted IS '逻辑删除';

CREATE INDEX agent_runtime_artifact_idx_run_id_step_key ON agent_runtime_artifact(run_id, step_key) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 7. agent_runtime_event：运行事件流（持久化序列，支持 afterSeq 回放）
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_event (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  seq BIGINT NOT NULL,
  event_key VARCHAR(160) NOT NULL,
  event_type VARCHAR(64) NOT NULL,
  step_key VARCHAR(128),
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_event IS '持久运行时事件流（run 内单调 seq，SSE 断线按 afterSeq 回放，无遗漏、无乱序、无重复）';
COMMENT ON COLUMN agent_runtime_event.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_event.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_event.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_event.seq IS 'run 内单调递增序号，从 1 开始';
COMMENT ON COLUMN agent_runtime_event.event_key IS '事件幂等键，同一 run 内唯一，重复追加自动忽略';
COMMENT ON COLUMN agent_runtime_event.event_type IS '事件类型：RUN_CREATED、RUN_STARTED、STEP_READY、STEP_STARTED、STEP_SUCCEEDED、STEP_FAILED 等';
COMMENT ON COLUMN agent_runtime_event.step_key IS '关联步骤键，运行级事件为空';
COMMENT ON COLUMN agent_runtime_event.payload IS '事件负载（JSON）';
COMMENT ON COLUMN agent_runtime_event.occurred_at IS '事件发生时间';
COMMENT ON COLUMN agent_runtime_event.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_event.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_event.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_event.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_event.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_event.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_event.deleted IS '逻辑删除';

-- (run_id, seq) 唯一索引同时承担回放查询索引（run_id + seq 范围扫描）
CREATE UNIQUE INDEX agent_runtime_event_uk_run_id_seq
  ON agent_runtime_event(run_id, seq)
  WHERE deleted = false;

CREATE UNIQUE INDEX agent_runtime_event_uk_run_id_event_key
  ON agent_runtime_event(run_id, event_key)
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 8. agent_runtime_outbox：事务性外发消息（Outbox 模式）
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_outbox (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT,
  event_id BIGINT,
  message_type VARCHAR(64) NOT NULL,
  target_channel VARCHAR(64),
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  state VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  retry_count INTEGER NOT NULL DEFAULT 0,
  next_retry_at TIMESTAMP,
  dispatched_at TIMESTAMP,
  last_error TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_outbox IS '持久运行时事务性外发消息表（与状态变更同事务写入，异步派发到 MQ/IM/回调）';
COMMENT ON COLUMN agent_runtime_outbox.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_outbox.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_outbox.run_id IS '所属运行ID（agent_runtime_run.id），系统级消息可为空';
COMMENT ON COLUMN agent_runtime_outbox.event_id IS '来源事件ID（agent_runtime_event.id）';
COMMENT ON COLUMN agent_runtime_outbox.message_type IS '消息类型（业务自定义，如 RUN_FINISHED_NOTIFY）';
COMMENT ON COLUMN agent_runtime_outbox.target_channel IS '目标通道：MQ、IM、WEBHOOK 等';
COMMENT ON COLUMN agent_runtime_outbox.payload IS '消息负载（JSON）';
COMMENT ON COLUMN agent_runtime_outbox.state IS '派发状态：PENDING、DISPATCHED、FAILED、DEAD';
COMMENT ON COLUMN agent_runtime_outbox.retry_count IS '已重试次数';
COMMENT ON COLUMN agent_runtime_outbox.next_retry_at IS '下次重试时间';
COMMENT ON COLUMN agent_runtime_outbox.dispatched_at IS '派发成功时间';
COMMENT ON COLUMN agent_runtime_outbox.last_error IS '最近一次派发失败原因';
COMMENT ON COLUMN agent_runtime_outbox.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_outbox.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_outbox.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_outbox.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_outbox.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_outbox.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_outbox.deleted IS '逻辑删除';

CREATE INDEX agent_runtime_outbox_idx_state_next_retry_at ON agent_runtime_outbox(state, next_retry_at) WHERE deleted = false;
CREATE INDEX agent_runtime_outbox_idx_run_id ON agent_runtime_outbox(run_id) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 9. agent_runtime_interruption：中断/取消请求记录
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_interruption (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT,
  thread_id VARCHAR(128),
  runtime_request_id VARCHAR(128),
  interruption_type VARCHAR(32) NOT NULL DEFAULT 'CANCEL',
  state VARCHAR(32) NOT NULL DEFAULT 'REQUESTED',
  reason VARCHAR(512),
  requested_by VARCHAR(64),
  cancellation_epoch BIGINT NOT NULL DEFAULT 0,
  requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  applied_at TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_interruption IS '持久运行时中断请求记录（取消标记写穿，跨节点可见）';
COMMENT ON COLUMN agent_runtime_interruption.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_interruption.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_interruption.run_id IS '所属运行ID（agent_runtime_run.id），按请求ID取消且未落 run 时可为空';
COMMENT ON COLUMN agent_runtime_interruption.thread_id IS '会话ID';
COMMENT ON COLUMN agent_runtime_interruption.runtime_request_id IS '运行时请求ID（全局唯一 UUID），内存注册表取消写穿的关联键';
COMMENT ON COLUMN agent_runtime_interruption.interruption_type IS '中断类型：CANCEL、TIMEOUT、MANUAL_TAKEOVER';
COMMENT ON COLUMN agent_runtime_interruption.state IS '中断状态：REQUESTED 已请求、APPLIED 已生效';
COMMENT ON COLUMN agent_runtime_interruption.reason IS '中断原因';
COMMENT ON COLUMN agent_runtime_interruption.requested_by IS '发起人ID';
COMMENT ON COLUMN agent_runtime_interruption.cancellation_epoch IS '本次中断对应的取消纪元（递增后的值）';
COMMENT ON COLUMN agent_runtime_interruption.requested_at IS '请求时间';
COMMENT ON COLUMN agent_runtime_interruption.applied_at IS '生效时间';
COMMENT ON COLUMN agent_runtime_interruption.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_interruption.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_interruption.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_interruption.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_interruption.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_interruption.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_interruption.deleted IS '逻辑删除';

CREATE INDEX agent_runtime_interruption_idx_run_id ON agent_runtime_interruption(run_id) WHERE deleted = false;
CREATE INDEX agent_runtime_interruption_idx_runtime_request_id ON agent_runtime_interruption(runtime_request_id) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 10. agent_runtime_approval：运行审批记录
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_approval (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  workspace_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  step_key VARCHAR(128),
  approval_key VARCHAR(320),
  risk_level VARCHAR(32),
  state VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  request_digest VARCHAR(128),
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  requested_by VARCHAR(64),
  approver VARCHAR(64),
  decided_at TIMESTAMP,
  expires_at TIMESTAMP,
  decision_comment VARCHAR(512),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_approval IS '持久运行时审批记录（高风险步骤执行前审批；参数/权限变化或过期后必须重新审批）';
COMMENT ON COLUMN agent_runtime_approval.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_approval.tenant_id IS '租户ID，必填；审批链路对未解析到租户的请求失败关闭（拒绝创建），不落 0，避免出现无人可批且跨来源共用的 0 号池';
COMMENT ON COLUMN agent_runtime_approval.workspace_id IS 'AI 工作空间ID，0 表示平台级（无工作空间）审批；批复只能被同工作空间的调用消费';
COMMENT ON COLUMN agent_runtime_approval.run_id IS '所属运行ID（agent_runtime_run.id），0 表示无关联运行的管理动作';
COMMENT ON COLUMN agent_runtime_approval.step_key IS '关联步骤键';
COMMENT ON COLUMN agent_runtime_approval.approval_key IS '审批幂等键，格式 ws:{workspaceId}|run:{runId|ref:sourceRefId|none}|{capabilityCode}:{paramsHash}；工作空间与运行入键，批复不可跨工作空间/跨运行复用。长度上限按 capability_handle(255) + 作用域前缀 + 指纹估算';
COMMENT ON COLUMN agent_runtime_approval.risk_level IS '风险等级：LOW、MEDIUM、HIGH';
COMMENT ON COLUMN agent_runtime_approval.state IS '审批状态：PENDING、APPROVED、REJECTED、EXPIRED、CANCELLED、CONSUMED（已通过批复被一次性消费后置 CONSUMED，用后失效）';
COMMENT ON COLUMN agent_runtime_approval.request_digest IS '审批时的请求参数摘要，参数变化后旧审批失效';
COMMENT ON COLUMN agent_runtime_approval.payload IS '审批展示负载（脱敏后的操作说明，JSON）';
COMMENT ON COLUMN agent_runtime_approval.requested_by IS '发起人ID';
COMMENT ON COLUMN agent_runtime_approval.approver IS '审批人ID';
COMMENT ON COLUMN agent_runtime_approval.decided_at IS '审批决定时间';
COMMENT ON COLUMN agent_runtime_approval.expires_at IS '审批过期时间';
COMMENT ON COLUMN agent_runtime_approval.decision_comment IS '审批意见';
COMMENT ON COLUMN agent_runtime_approval.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_approval.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_approval.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_approval.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_approval.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_approval.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_approval.deleted IS '逻辑删除';

-- 同一（租户 + 审批幂等键）同时只允许存在一条 PENDING：把「先查 PENDING 再插入」的非原子窗口
-- 交给数据库兜底，并发下只会建成一条，冲突方回查复用既有 PENDING（真幂等）。
CREATE UNIQUE INDEX agent_runtime_approval_uk_tenant_approval_key_pending
  ON agent_runtime_approval(tenant_id, approval_key, state)
  WHERE state = 'PENDING' AND deleted = false;

CREATE INDEX agent_runtime_approval_idx_run_id ON agent_runtime_approval(run_id) WHERE deleted = false;
-- 可消费批复查询：(租户 + 审批键 + 状态) 命中后再按 workspace_id / run_id 谓词二次收敛
CREATE INDEX agent_runtime_approval_idx_tenant_approval_key_state
  ON agent_runtime_approval(tenant_id, approval_key, state) WHERE deleted = false;
CREATE INDEX agent_runtime_approval_idx_state_expires_at ON agent_runtime_approval(state, expires_at) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 11. agent_runtime_budget_ledger：运行预算流水
-- ----------------------------------------------------------------------------
CREATE TABLE agent_runtime_budget_ledger (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id BIGINT NOT NULL DEFAULT 0,
  run_id BIGINT NOT NULL,
  step_key VARCHAR(128),
  budget_type VARCHAR(32) NOT NULL,
  amount NUMERIC(20, 6) NOT NULL DEFAULT 0,
  ref_invocation_id BIGINT,
  remark VARCHAR(255),
  occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_budget_ledger IS '持久运行时预算消耗流水（模型调用、工具调用、Token、耗时、成本按类型记账）';
COMMENT ON COLUMN agent_runtime_budget_ledger.id IS '主键ID';
COMMENT ON COLUMN agent_runtime_budget_ledger.tenant_id IS '租户ID，0 表示未解析到租户';
COMMENT ON COLUMN agent_runtime_budget_ledger.run_id IS '所属运行ID（agent_runtime_run.id）';
COMMENT ON COLUMN agent_runtime_budget_ledger.step_key IS '关联步骤键，运行级消耗为空';
COMMENT ON COLUMN agent_runtime_budget_ledger.budget_type IS '预算类型：MODEL_CALL、TOOL_CALL、PROMPT_TOKENS、COMPLETION_TOKENS、DURATION_MS、COST';
COMMENT ON COLUMN agent_runtime_budget_ledger.amount IS '消耗数量（单位由 budget_type 决定：次数/Token 数/毫秒/金额）';
COMMENT ON COLUMN agent_runtime_budget_ledger.ref_invocation_id IS '来源调用ID（agent_runtime_invocation.id）';
COMMENT ON COLUMN agent_runtime_budget_ledger.remark IS '备注';
COMMENT ON COLUMN agent_runtime_budget_ledger.occurred_at IS '消耗发生时间';
COMMENT ON COLUMN agent_runtime_budget_ledger.create_by IS '创建人ID';
COMMENT ON COLUMN agent_runtime_budget_ledger.create_name IS '创建人名称';
COMMENT ON COLUMN agent_runtime_budget_ledger.create_time IS '创建时间';
COMMENT ON COLUMN agent_runtime_budget_ledger.last_modify_by IS '最后修改人ID';
COMMENT ON COLUMN agent_runtime_budget_ledger.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_runtime_budget_ledger.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_runtime_budget_ledger.deleted IS '逻辑删除';

CREATE INDEX agent_runtime_budget_ledger_idx_run_id_budget_type ON agent_runtime_budget_ledger(run_id, budget_type) WHERE deleted = false;

COMMIT;

-- =============================================================================
-- Group A: 04-task-im
-- =============================================================================

-- ============================================================================
-- W6：任务体系（5 张新表）+ IM 租户化（6 张 agent_im_* 表重建）
-- 数据库：PostgreSQL
--
-- ⚠️ 本脚本按「可 DROP 重建」编写：系统尚未上线、无存量数据兼容顾虑，
--    agent_im_* 六张表为携带租户列的重建版（字段从现有 entity 反推 + 本轮新增列），
--    执行前请确认目标库无需保留 agent_im_* 数据。
-- 关联说明：workspace_id / employee_binding_id / release_id / runtime_run_id
--    指向其他工作流建的表（agent_workspace / agent_employee_binding /
--    agent_employee_release / agent_runtime_run），一律只存 BIGINT ID，
--    不建数据库级外键，关联关系由应用层维护。
-- 索引命名：表名_idx_字段名；唯一索引 uk_表名_语义，逻辑删除表用部分唯一索引
--    （WHERE deleted = false），与模块既有 DDL 风格一致。
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0. DROP（可重建）
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS agent_task_delivery;
DROP TABLE IF EXISTS agent_task_run;
DROP TABLE IF EXISTS agent_task_trigger;
DROP TABLE IF EXISTS agent_task_version;
DROP TABLE IF EXISTS agent_task_definition;
DROP TABLE IF EXISTS agent_im_message;
DROP TABLE IF EXISTS agent_im_conversation_binding;
DROP TABLE IF EXISTS agent_im_user_identity;
DROP TABLE IF EXISTS agent_im_setup_session;
DROP TABLE IF EXISTS agent_im_connector;
DROP TABLE IF EXISTS agent_im_provider_config;

-- ----------------------------------------------------------------------------
-- 1. agent_task_definition 任务定义
-- ----------------------------------------------------------------------------
CREATE TABLE agent_task_definition (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  workspace_id BIGINT NOT NULL,
  employee_binding_id BIGINT NOT NULL,
  release_id BIGINT NOT NULL,
  task_name VARCHAR(128) NOT NULL,
  task_description VARCHAR(1024),
  task_type VARCHAR(64),
  default_autonomy_level VARCHAR(32) NOT NULL DEFAULT 'ASSISTED',
  high_risk_write BOOLEAN NOT NULL DEFAULT false,
  service_principal VARCHAR(128),
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_task_definition IS 'Agent 任务定义（固定绑定 workspace + 数字员工 + 发布版本）';
COMMENT ON COLUMN agent_task_definition.id IS '主键ID';
COMMENT ON COLUMN agent_task_definition.tenant_id IS '所属租户ID';
COMMENT ON COLUMN agent_task_definition.workspace_id IS '所属 AI 工作空间ID（agent_workspace，应用层关联）';
COMMENT ON COLUMN agent_task_definition.employee_binding_id IS '绑定数字员工ID（agent_employee_binding，应用层关联）';
COMMENT ON COLUMN agent_task_definition.release_id IS '绑定发布版本ID（agent_employee_release，应用层关联）';
COMMENT ON COLUMN agent_task_definition.task_name IS '任务名称';
COMMENT ON COLUMN agent_task_definition.task_description IS '任务描述';
COMMENT ON COLUMN agent_task_definition.task_type IS '任务类型（业务分类，如 REPORT/MONITOR/OPERATION）';
COMMENT ON COLUMN agent_task_definition.default_autonomy_level IS '默认自治级别（AUTONOMOUS/ASSISTED）';
COMMENT ON COLUMN agent_task_definition.high_risk_write IS '是否高风险写任务（true 时自治级别强制 ASSISTED，写动作须审批）';
COMMENT ON COLUMN agent_task_definition.service_principal IS '自动任务受限执行主体标识（service principal，禁止使用创建者长期 Token）';
COMMENT ON COLUMN agent_task_definition.status IS '状态（enabled/disabled）';
COMMENT ON COLUMN agent_task_definition.create_by IS '创建人账号';
COMMENT ON COLUMN agent_task_definition.create_name IS '创建人名称';
COMMENT ON COLUMN agent_task_definition.create_time IS '创建时间';
COMMENT ON COLUMN agent_task_definition.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_task_definition.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_task_definition.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_task_definition.deleted IS '逻辑删除标识';

CREATE INDEX agent_task_definition_idx_tenant_id
  ON agent_task_definition (tenant_id, status)
  WHERE deleted = false;

CREATE INDEX agent_task_definition_idx_workspace_id
  ON agent_task_definition (workspace_id, employee_binding_id)
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 2. agent_task_version 任务版本（不可变）
-- ----------------------------------------------------------------------------
CREATE TABLE agent_task_version (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  definition_id BIGINT NOT NULL,
  version_no INTEGER NOT NULL,
  params_snapshot JSONB,
  prompt_snapshot JSONB,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_task_version IS 'Agent 任务定义的不可变版本（创建后不更新，调整生成新版本）';
COMMENT ON COLUMN agent_task_version.id IS '主键ID';
COMMENT ON COLUMN agent_task_version.tenant_id IS '所属租户ID';
COMMENT ON COLUMN agent_task_version.definition_id IS '任务定义ID';
COMMENT ON COLUMN agent_task_version.version_no IS '版本号（同一定义内单调递增）';
COMMENT ON COLUMN agent_task_version.params_snapshot IS '任务参数快照（JSONB）';
COMMENT ON COLUMN agent_task_version.prompt_snapshot IS '提示词快照（JSONB，系统提示词与用户提示词模板）';
COMMENT ON COLUMN agent_task_version.create_by IS '创建人账号';
COMMENT ON COLUMN agent_task_version.create_name IS '创建人名称';
COMMENT ON COLUMN agent_task_version.create_time IS '创建时间';
COMMENT ON COLUMN agent_task_version.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_task_version.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_task_version.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_task_version.deleted IS '逻辑删除标识';

CREATE UNIQUE INDEX uk_agent_task_version_definition_no
  ON agent_task_version (definition_id, version_no)
  WHERE deleted = false;

CREATE INDEX agent_task_version_idx_tenant_id
  ON agent_task_version (tenant_id, definition_id)
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 3. agent_task_trigger 任务触发器
-- ----------------------------------------------------------------------------
CREATE TABLE agent_task_trigger (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  definition_id BIGINT NOT NULL,
  task_version_id BIGINT NOT NULL,
  trigger_type VARCHAR(32) NOT NULL,
  trigger_config JSONB,
  timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Shanghai',
  misfire_policy VARCHAR(32) NOT NULL DEFAULT 'SKIP',
  concurrency_policy VARCHAR(32) NOT NULL DEFAULT 'FORBID',
  next_fire_time TIMESTAMP(6),
  last_fire_time TIMESTAMP(6),
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_task_trigger IS 'Agent 任务触发器（CHAT/SCHEDULE/EVENT/API/IM）';
COMMENT ON COLUMN agent_task_trigger.id IS '主键ID';
COMMENT ON COLUMN agent_task_trigger.tenant_id IS '所属租户ID';
COMMENT ON COLUMN agent_task_trigger.definition_id IS '任务定义ID（冗余便于按任务查询）';
COMMENT ON COLUMN agent_task_trigger.task_version_id IS '任务版本ID';
COMMENT ON COLUMN agent_task_trigger.trigger_type IS '触发类型（CHAT/SCHEDULE/EVENT/API/IM）';
COMMENT ON COLUMN agent_task_trigger.trigger_config IS '触发配置（JSONB：SCHEDULE=cron；EVENT=eventTopic/eventTag；API=签名要求；IM=provider/connectorCode）';
COMMENT ON COLUMN agent_task_trigger.timezone IS '时区（IANA 名称，SCHEDULE 按此时区计算 cron 与 DST）';
COMMENT ON COLUMN agent_task_trigger.misfire_policy IS '错过执行策略（SKIP=错过跳过 / FIRE_ONCE=补偿一次）';
COMMENT ON COLUMN agent_task_trigger.concurrency_policy IS '并发策略（ALLOW=允许并发 / FORBID=存在未结束运行时跳过）';
COMMENT ON COLUMN agent_task_trigger.next_fire_time IS '下一次计划执行时刻（SCHEDULE 调度扫描依据）';
COMMENT ON COLUMN agent_task_trigger.last_fire_time IS '最近一次实际触发时刻';
COMMENT ON COLUMN agent_task_trigger.status IS '状态（enabled/disabled）';
COMMENT ON COLUMN agent_task_trigger.create_by IS '创建人账号';
COMMENT ON COLUMN agent_task_trigger.create_name IS '创建人名称';
COMMENT ON COLUMN agent_task_trigger.create_time IS '创建时间';
COMMENT ON COLUMN agent_task_trigger.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_task_trigger.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_task_trigger.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_task_trigger.deleted IS '逻辑删除标识';

CREATE INDEX agent_task_trigger_idx_definition_id
  ON agent_task_trigger (definition_id)
  WHERE deleted = false;

-- SCHEDULE 调度扫描：type + status + next_fire_time
CREATE INDEX agent_task_trigger_idx_next_fire_time
  ON agent_task_trigger (trigger_type, status, next_fire_time)
  WHERE deleted = false;

-- EVENT 触发按逻辑主题匹配（JSONB 表达式索引）
CREATE INDEX agent_task_trigger_idx_event_topic
  ON agent_task_trigger ((trigger_config ->> 'eventTopic'))
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 4. agent_task_run 任务运行
-- ----------------------------------------------------------------------------
CREATE TABLE agent_task_run (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  definition_id BIGINT NOT NULL,
  task_version_id BIGINT NOT NULL,
  trigger_id BIGINT NOT NULL,
  trigger_type VARCHAR(32) NOT NULL,
  idempotency_key VARCHAR(512) NOT NULL,
  external_event_id VARCHAR(256),
  scheduled_time TIMESTAMP(6),
  run_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  runtime_run_id BIGINT,
  service_principal VARCHAR(128),
  error_message TEXT,
  started_time TIMESTAMP(6),
  finished_time TIMESTAMP(6),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_task_run IS 'Agent 任务运行（触发幂等的落库单位，最终统一创建 RuntimeRun）';
COMMENT ON COLUMN agent_task_run.id IS '主键ID';
COMMENT ON COLUMN agent_task_run.tenant_id IS '所属租户ID';
COMMENT ON COLUMN agent_task_run.definition_id IS '任务定义ID';
COMMENT ON COLUMN agent_task_run.task_version_id IS '任务版本ID';
COMMENT ON COLUMN agent_task_run.trigger_id IS '触发器ID';
COMMENT ON COLUMN agent_task_run.trigger_type IS '触发类型（CHAT/SCHEDULE/EVENT/API/IM）';
COMMENT ON COLUMN agent_task_run.idempotency_key IS '触发幂等键（SCHEDULE=trigger+计划时刻 / EVENT=trigger+eventId / API=trigger+Idempotency-Key / IM=trigger+messageId）';
COMMENT ON COLUMN agent_task_run.external_event_id IS '外部事件ID（RocketMQ eventId / IM messageId / API Idempotency-Key 原值）';
COMMENT ON COLUMN agent_task_run.scheduled_time IS '计划执行时刻（SCHEDULE 为 cron 计划时刻，其他类型为受理时刻）';
COMMENT ON COLUMN agent_task_run.run_status IS '运行状态（PENDING/RUNNING/SUCCESS/FAILED/SKIPPED/CANCELLED）';
COMMENT ON COLUMN agent_task_run.runtime_run_id IS '关联运行时 RunID（agent_runtime_run 由其他工作流建表，应用层关联，可空）';
COMMENT ON COLUMN agent_task_run.service_principal IS '本次运行使用的受限执行主体标识快照';
COMMENT ON COLUMN agent_task_run.error_message IS '错误信息';
COMMENT ON COLUMN agent_task_run.started_time IS '开始执行时刻';
COMMENT ON COLUMN agent_task_run.finished_time IS '结束时刻';
COMMENT ON COLUMN agent_task_run.create_by IS '创建人账号';
COMMENT ON COLUMN agent_task_run.create_name IS '创建人名称';
COMMENT ON COLUMN agent_task_run.create_time IS '创建时间';
COMMENT ON COLUMN agent_task_run.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_task_run.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_task_run.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_task_run.deleted IS '逻辑删除标识';

-- 触发幂等唯一约束：重复触发（重复事件/API 重放/定时重扫/IM 重投）插入冲突后返回已有运行
CREATE UNIQUE INDEX uk_agent_task_run_idempotency
  ON agent_task_run (idempotency_key)
  WHERE deleted = false;

CREATE INDEX agent_task_run_idx_definition_id
  ON agent_task_run (tenant_id, definition_id, run_status)
  WHERE deleted = false;

-- FORBID 并发策略判定：按触发器查未结束运行
CREATE INDEX agent_task_run_idx_trigger_id
  ON agent_task_run (trigger_id, run_status)
  WHERE deleted = false;

CREATE INDEX agent_task_run_idx_runtime_run_id
  ON agent_task_run (runtime_run_id)
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 5. agent_task_delivery 任务结果投递
--    TODO(W6→通知治理): 与 agent_notification_delivery 能力重叠，待通知栈去留结论后收敛。
-- ----------------------------------------------------------------------------
CREATE TABLE agent_task_delivery (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  task_run_id BIGINT NOT NULL,
  channel VARCHAR(32) NOT NULL,
  target VARCHAR(512) NOT NULL,
  delivery_status VARCHAR(32) NOT NULL DEFAULT 'PENDING',
  retry_count INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  last_delivery_time TIMESTAMP(6),
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_task_delivery IS 'Agent 任务结果投递记录（与 agent_notification_delivery 的收敛见表注 TODO）';
COMMENT ON COLUMN agent_task_delivery.id IS '主键ID';
COMMENT ON COLUMN agent_task_delivery.tenant_id IS '所属租户ID';
COMMENT ON COLUMN agent_task_delivery.task_run_id IS '任务运行ID';
COMMENT ON COLUMN agent_task_delivery.channel IS '投递渠道（IM/EMAIL/WEBHOOK 等）';
COMMENT ON COLUMN agent_task_delivery.target IS '投递目标（会话ID/邮箱/回调地址，按渠道解释）';
COMMENT ON COLUMN agent_task_delivery.delivery_status IS '投递状态（PENDING/SUCCESS/FAILED/RETRYING）';
COMMENT ON COLUMN agent_task_delivery.retry_count IS '已重试次数';
COMMENT ON COLUMN agent_task_delivery.last_error IS '最近一次投递错误';
COMMENT ON COLUMN agent_task_delivery.last_delivery_time IS '最近一次投递时刻';
COMMENT ON COLUMN agent_task_delivery.create_by IS '创建人账号';
COMMENT ON COLUMN agent_task_delivery.create_name IS '创建人名称';
COMMENT ON COLUMN agent_task_delivery.create_time IS '创建时间';
COMMENT ON COLUMN agent_task_delivery.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_task_delivery.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_task_delivery.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_task_delivery.deleted IS '逻辑删除标识';

CREATE INDEX agent_task_delivery_idx_task_run_id
  ON agent_task_delivery (task_run_id, delivery_status)
  WHERE deleted = false;

-- ============================================================================
-- 以下为 IM 租户化重建（6 张 agent_im_* 表）
-- 变更点：
--   1. 全部表新增 tenant_id（provider_config 允许 NULL 表示平台级全局配置，其余 NOT NULL）；
--   2. connector 唯一键从 (connector_code) 改为 (tenant_id, provider, connector_code)；
--   3. conversation_binding 新增 workspace_id、employee_binding_id（绑定 Workspace 与数字员工）；
--   4. message 幂等唯一索引保留并显式声明（幂等键格式含租户前缀：tenantId:provider:connectorCode:externalMessageId）。
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 6. agent_im_provider_config IM 平台配置
-- ----------------------------------------------------------------------------
CREATE TABLE agent_im_provider_config (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  provider VARCHAR(32) NOT NULL,
  encrypted_config TEXT,
  status VARCHAR(32) NOT NULL DEFAULT 'enabled',
  display_order INTEGER DEFAULT 0,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_im_provider_config IS 'IM 平台级配置（tenant_id 为 NULL 表示平台级全局配置，运行时按 provider 全局读取）';
COMMENT ON COLUMN agent_im_provider_config.id IS '主键ID';
COMMENT ON COLUMN agent_im_provider_config.tenant_id IS '所属租户ID（NULL 表示平台级全局配置）';
COMMENT ON COLUMN agent_im_provider_config.provider IS 'IM 平台（DINGTALK/WECOM）';
COMMENT ON COLUMN agent_im_provider_config.encrypted_config IS '加密后的平台配置';
COMMENT ON COLUMN agent_im_provider_config.status IS '状态（enabled/disabled）';
COMMENT ON COLUMN agent_im_provider_config.display_order IS '显示顺序';
COMMENT ON COLUMN agent_im_provider_config.create_by IS '创建人账号';
COMMENT ON COLUMN agent_im_provider_config.create_name IS '创建人名称';
COMMENT ON COLUMN agent_im_provider_config.create_time IS '创建时间';
COMMENT ON COLUMN agent_im_provider_config.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_im_provider_config.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_im_provider_config.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_im_provider_config.deleted IS '逻辑删除标识';

-- 平台级配置每个 provider 一行（COALESCE 使 NULL 租户也参与唯一约束）
CREATE UNIQUE INDEX uk_agent_im_provider_config
  ON agent_im_provider_config (COALESCE(tenant_id, ''), provider)
  WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 7. agent_im_connector IM 对话连接器
-- ----------------------------------------------------------------------------
CREATE TABLE agent_im_connector (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
