COMMENT ON COLUMN agent_im_connector.default_agent_id IS '默认绑定智能体ID';
COMMENT ON COLUMN agent_im_connector.direct_enabled IS '是否启用单聊';
COMMENT ON COLUMN agent_im_connector.group_enabled IS '是否启用群聊';
