COMMENT ON COLUMN agent_im_connector.last_modify_by IS '最后修改人账号';
COMMENT ON COLUMN agent_im_connector.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN agent_im_connector.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN agent_im_connector.deleted IS '逻辑删除标识';

