-- =============================================================================
-- Group A: 05-memory-market
-- =============================================================================

-- ============================================================================
-- 05-memory-market.sql — W7：记忆体系扩展 + 能力市场（方案第十二/十三章）
-- ----------------------------------------------------------------------------
-- 用途：
--   1. data_agent_memory        原地扩列（新增租户/工作空间/主体/事实键/来源/敏感治理列）
--   2. data_agent_skill_version 原地扩列（新增平台来源版本/内容哈希/撤销标记列）
--   3. skill_market_listing / skill_market_listing_version / skill_market_review 新建
--   4. 执行后自检：校验 data_agent_skill_version 的引用完整性未被破坏
-- 执行方式：第 1、2 节一律幂等 ALTER，严禁 DROP 重建 —— 两张表都有存量数据，
--   data_agent_skill_version 还有引用方，DROP ... CASCADE 会连带摘掉外键与触发器（原因见第 2 节）。
--   第 3 节三张市场新表无引用方、无存量数据，保留 DROP 重建。
--   本脚本可重复执行，且不会丢失 data_agent_memory 与 data_agent_skill_version 的既有行。
-- 影响范围：business-agent（agent 库）。第 1 节只加十三列与三个索引、第 2 节只加三列与两个索引，不动既有行、
--   不动 data_agent_skill / data_agent_skill_binding / data_agent_flow_instance /
--   data_agent_skill_tool_ref / agent_runtime_hook(_log) 上指向本表的外键与触发器。
-- 回滚方式：
--   - 第 2 节：ALTER TABLE data_agent_skill_version
--       DROP COLUMN IF EXISTS source_listing_version_id, DROP COLUMN IF EXISTS content_hash,
--       DROP COLUMN IF EXISTS revoked;
--     并 DROP 本节新建的两个索引；既有版本行不受影响，无数据损失。
--   - 第 1 节：ALTER TABLE data_agent_memory DROP COLUMN IF EXISTS 逐列回退新增的十三列，
--     并 DROP 本节新建的三个索引与四个 CHECK 约束；既有记忆行不受影响，无数据损失。
--   - 第 3 节：DROP 对应的三张市场表（无存量数据）。
-- PostgreSQL 兼容性：仅使用 PG 通用语法（JSONB、partial index、IDENTITY、
--   ADD COLUMN IF NOT EXISTS、to_regclass），需 PostgreSQL 11+（ADD COLUMN ... NOT NULL
--   DEFAULT 不重写表）；已在 PostgreSQL 14+ 语义下检查；不含方言函数与大小写敏感对象名。
-- 计费边界：首期平台审核 + 使用配额，不建设计费结算，本脚本不含计费表。
-- ============================================================================

-- ============================================================================
-- 1. data_agent_memory 原地扩列（字段 = 现有 entity 反推 + 方案第十二章新增列）
-- ============================================================================
-- 严禁 DROP 重建：本节只是给既有表加列，DROP 会清空全部记忆数据且不可恢复。
-- 表不存在时按完整结构建表；已存在时靠下方 ADD COLUMN IF NOT EXISTS 幂等补列。
CREATE TABLE IF NOT EXISTS data_agent_memory
(
    id                BIGINT PRIMARY KEY,
    tenant_id         VARCHAR(64),
    workspace_id      BIGINT,
    namespace_id      VARCHAR(128),
    agent_id          BIGINT        NOT NULL,
    user_id           VARCHAR(128)  NOT NULL,
    subject_type      VARCHAR(32),
    subject_id        VARCHAR(128),
    fact_key          VARCHAR(255),
    revision          INTEGER       NOT NULL DEFAULT 1,
    memory_type       VARCHAR(32)   NOT NULL,
    summary           TEXT          NOT NULL,
    content           TEXT,
    semantic_hash     VARCHAR(128)  NOT NULL,
    importance        NUMERIC(6, 4) NOT NULL DEFAULT 0.5000,
    confidence        NUMERIC(6, 4) NOT NULL DEFAULT 0.7000,
    status            VARCHAR(32)   NOT NULL DEFAULT 'ACTIVE',
    provenance        JSONB,
    source_run_id     BIGINT,
    sensitivity       VARCHAR(16)   NOT NULL DEFAULT 'LOW',
    consent_status    VARCHAR(16)   NOT NULL DEFAULT 'UNSPECIFIED',
    valid_from        TIMESTAMP(6),
    valid_to          TIMESTAMP(6),
    source_session_id VARCHAR(128),
    source_message_id VARCHAR(128),
    use_count         INTEGER       NOT NULL DEFAULT 0,
    last_used_time    TIMESTAMP(6),
    expire_time       TIMESTAMP(6),
    create_by         VARCHAR(64),
    create_name       VARCHAR(128),
    create_time       TIMESTAMP(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modify_by    VARCHAR(64),
    last_modify_name  VARCHAR(128),
    last_modify_time  TIMESTAMP(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted           BOOLEAN       NOT NULL DEFAULT FALSE,
    CONSTRAINT ck_data_agent_memory_subject_type CHECK (subject_type IS NULL OR subject_type IN
        ('SESSION', 'EMPLOYEE_USER', 'WORKSPACE', 'EPISODIC', 'PROCEDURAL')),
    CONSTRAINT ck_data_agent_memory_sensitivity CHECK (sensitivity IN ('LOW', 'MEDIUM', 'HIGH')),
    CONSTRAINT ck_data_agent_memory_consent_status CHECK (consent_status IN
        ('UNSPECIFIED', 'GRANTED', 'DENIED', 'REVOKED')),
    CONSTRAINT ck_data_agent_memory_status CHECK (status IN ('ACTIVE', 'PENDING_REVIEW', 'DISABLED', 'EXPIRED'))
);

-- 表已存在（基线见 src/main/resources/dataagent/sql/pg/20260616_memory_context.sql）时补齐新增列。
-- 全部为可空或带 DEFAULT，PG 11+ 下 ADD COLUMN ... NOT NULL DEFAULT 只改 catalog、不重写表。
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS tenant_id      VARCHAR(64);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS workspace_id   BIGINT;
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS namespace_id   VARCHAR(128);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS subject_type   VARCHAR(32);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS subject_id     VARCHAR(128);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS fact_key       VARCHAR(255);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS revision       INTEGER      NOT NULL DEFAULT 1;
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS provenance     JSONB;
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS source_run_id  BIGINT;
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS sensitivity    VARCHAR(16)  NOT NULL DEFAULT 'LOW';
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS consent_status VARCHAR(16)  NOT NULL DEFAULT 'UNSPECIFIED';
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS valid_from     TIMESTAMP(6);
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS valid_to       TIMESTAMP(6);

-- CHECK 约束在建表语句里已内联，这里只为「表已存在」的库补齐。
-- 按 conrelid 限定：约束名跨 schema 不唯一，只按名字判断会误判为已存在而静默跳过。
-- 注意：ADD CONSTRAINT 会校验存量行，若既有 status 超出下列取值需先清洗数据。
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ck_data_agent_memory_subject_type'
                    AND conrelid = to_regclass('data_agent_memory')) THEN
    ALTER TABLE data_agent_memory
      ADD CONSTRAINT ck_data_agent_memory_subject_type CHECK (subject_type IS NULL OR subject_type IN
        ('SESSION', 'EMPLOYEE_USER', 'WORKSPACE', 'EPISODIC', 'PROCEDURAL'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ck_data_agent_memory_sensitivity'
                    AND conrelid = to_regclass('data_agent_memory')) THEN
    ALTER TABLE data_agent_memory
      ADD CONSTRAINT ck_data_agent_memory_sensitivity CHECK (sensitivity IN ('LOW', 'MEDIUM', 'HIGH'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ck_data_agent_memory_consent_status'
                    AND conrelid = to_regclass('data_agent_memory')) THEN
    ALTER TABLE data_agent_memory
      ADD CONSTRAINT ck_data_agent_memory_consent_status CHECK (consent_status IN
        ('UNSPECIFIED', 'GRANTED', 'DENIED', 'REVOKED'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ck_data_agent_memory_status'
                    AND conrelid = to_regclass('data_agent_memory')) THEN
    ALTER TABLE data_agent_memory
      ADD CONSTRAINT ck_data_agent_memory_status CHECK (status IN
        ('ACTIVE', 'PENDING_REVIEW', 'DISABLED', 'EXPIRED'));
  END IF;
END;
$$;

-- 既有索引（沿用原索引名，保持监控/巡检脚本兼容）
CREATE INDEX IF NOT EXISTS idx_data_agent_memory_agent_user
    ON data_agent_memory (agent_id, user_id)
    WHERE deleted = FALSE;

CREATE INDEX IF NOT EXISTS idx_data_agent_memory_status_type
    ON data_agent_memory (status, memory_type)
    WHERE deleted = FALSE;

CREATE UNIQUE INDEX IF NOT EXISTS idx_data_agent_memory_semantic_hash
    ON data_agent_memory (agent_id, user_id, semantic_hash)
    WHERE deleted = FALSE;

-- 新增：同主体同事实键按 revision 修订的唯一约束（fact_key 为空的自由记忆不参与）
CREATE UNIQUE INDEX IF NOT EXISTS data_agent_memory_uidx_subject_fact_revision
    ON data_agent_memory (agent_id, subject_type, subject_id, fact_key, revision)
    WHERE deleted = FALSE AND fact_key IS NOT NULL;

-- 新增：租户/工作空间与命名空间的普通索引
CREATE INDEX IF NOT EXISTS data_agent_memory_idx_tenant_workspace
    ON data_agent_memory (tenant_id, workspace_id);

CREATE INDEX IF NOT EXISTS data_agent_memory_idx_namespace_id
    ON data_agent_memory (namespace_id);

COMMENT ON TABLE data_agent_memory IS 'DataAgent长期记忆';
COMMENT ON COLUMN data_agent_memory.id IS '主键ID';
COMMENT ON COLUMN data_agent_memory.tenant_id IS '租户ID（写入时从认证上下文传播，表未纳入租户拦截白名单，显式谓词是唯一防线）';
COMMENT ON COLUMN data_agent_memory.workspace_id IS '工作空间ID（可空，仅 WORKSPACE 范围记忆填写）';
COMMENT ON COLUMN data_agent_memory.namespace_id IS '记忆命名空间';
COMMENT ON COLUMN data_agent_memory.agent_id IS '智能体ID';
COMMENT ON COLUMN data_agent_memory.user_id IS '用户ID（EMPLOYEE_USER 记忆的主体用户，其余范围为写入人）';
COMMENT ON COLUMN data_agent_memory.subject_type IS '记忆主体类型/范围：SESSION/EMPLOYEE_USER/WORKSPACE/EPISODIC/PROCEDURAL，用户侧与 WORKSPACE 查询严格隔离';
COMMENT ON COLUMN data_agent_memory.subject_id IS '记忆主体ID：会话ID/用户ID/工作空间ID，与 subject_type 配套';
COMMENT ON COLUMN data_agent_memory.fact_key IS '事实键：同键新写入按 revision 递增修订，历史版本保留';
COMMENT ON COLUMN data_agent_memory.revision IS '同 fact_key 下的修订版本，从 1 递增';
COMMENT ON COLUMN data_agent_memory.memory_type IS '记忆内容类型：偏好、事实、历史结论、工作方式';
COMMENT ON COLUMN data_agent_memory.summary IS '用于页面展示和注入上下文的短摘要（提炼结论，禁止保存隐藏思维链与原始敏感业务 payload）';
COMMENT ON COLUMN data_agent_memory.content IS '完整记忆内容（同 summary 红线约束）';
COMMENT ON COLUMN data_agent_memory.semantic_hash IS '语义去重哈希';
COMMENT ON COLUMN data_agent_memory.importance IS '重要度 0-1';
COMMENT ON COLUMN data_agent_memory.confidence IS '置信度 0-1';
COMMENT ON COLUMN data_agent_memory.status IS '状态：ACTIVE/PENDING_REVIEW（程序性记忆默认，人工审核后启用）/DISABLED/EXPIRED';
COMMENT ON COLUMN data_agent_memory.provenance IS '来源说明（抽取来源、依据，JSONB）';
COMMENT ON COLUMN data_agent_memory.source_run_id IS '来源运行ID：只有成功的根 Run 才能生成长期记忆候选';
COMMENT ON COLUMN data_agent_memory.sensitivity IS '敏感级别：LOW/MEDIUM/HIGH，HIGH 必须 consent_status=GRANTED 才可写入';
COMMENT ON COLUMN data_agent_memory.consent_status IS '用户同意状态：UNSPECIFIED/GRANTED/DENIED/REVOKED';
COMMENT ON COLUMN data_agent_memory.valid_from IS '生效时间';
COMMENT ON COLUMN data_agent_memory.valid_to IS '失效时间（TTL），过期不再召回';
COMMENT ON COLUMN data_agent_memory.source_session_id IS '来源会话ID';
COMMENT ON COLUMN data_agent_memory.source_message_id IS '来源消息ID';
COMMENT ON COLUMN data_agent_memory.use_count IS '使用次数';
COMMENT ON COLUMN data_agent_memory.last_used_time IS '最近使用时间';
COMMENT ON COLUMN data_agent_memory.expire_time IS '过期时间（存量存储 TTL，与 valid_to 双轨）';
COMMENT ON COLUMN data_agent_memory.create_by IS '创建人';
COMMENT ON COLUMN data_agent_memory.create_name IS '创建人名称';
COMMENT ON COLUMN data_agent_memory.create_time IS '创建时间';
COMMENT ON COLUMN data_agent_memory.last_modify_by IS '最后修改人';
COMMENT ON COLUMN data_agent_memory.last_modify_name IS '最后修改人名称';
COMMENT ON COLUMN data_agent_memory.last_modify_time IS '最后修改时间';
COMMENT ON COLUMN data_agent_memory.deleted IS '逻辑删除标记';

-- ============================================================================
-- 2. data_agent_skill_version 原地扩列（本节只新增市场来源三列）
--
--    【严禁 DROP 重建】本表是业务数据表（承载 skill_markdown / route_rules /
--    flow_definition 等全部版本内容），且被 7 条外键与 2 个触发器依赖：
--      data_agent_skill.fk_data_agent_skill_latest_draft      (latest_draft_version_id, id)
--      data_agent_skill.fk_data_agent_skill_published         (published_version_id, id)
--      data_agent_skill_binding.fk_data_agent_skill_binding_version
--      data_agent_flow_instance.fk_data_agent_flow_instance_skill_version
--      data_agent_skill_tool_ref.skill_version_id
--      agent_runtime_hook.skill_version_id
--      agent_runtime_hook_log.skill_version_id
--      trg_data_agent_skill_version_validate（租户归属 + 已发布版本不可变校验）
--      trg_data_agent_skill_version_delete_immutable（已发布版本不可删）
--
--    本节早期写作 `DROP TABLE ... CASCADE` + `CREATE`，在任何已有技能数据的库上都会：
--      1) 物理删除全部版本行，而引用方（skill / binding / flow_instance / tool_ref）
--         行仍在，留下悬空 *_version_id；
--      2) 被 CASCADE 静默摘掉上面 7 条外键，脚本却只补回 skill 上的 2 条，
--         binding / flow / tool_ref / hook 的外键从此长期缺失；
--      3) 补回时 ALTER TABLE ADD CONSTRAINT 会校验存量行，于是必然报：
--         ERROR: 插入或更新表 "data_agent_skill" 违反外键约束
--                "fk_data_agent_skill_latest_draft"
--    只增加三列没有任何理由重建整表，故改为幂等 ALTER。表结构基线以
--    src/main/resources/dataagent/sql/pg/schema-v2.sql 为准，本节不复制其定义。
-- ============================================================================
DO $$
BEGIN
  IF to_regclass('data_agent_skill_version') IS NULL THEN
    RAISE EXCEPTION '缺少前置表 data_agent_skill_version，请先执行 src/main/resources/dataagent/sql/pg/schema-v2.sql 建立基线结构';
  END IF;
END;
$$;

ALTER TABLE data_agent_skill_version ADD COLUMN IF NOT EXISTS source_listing_version_id BIGINT;
ALTER TABLE data_agent_skill_version ADD COLUMN IF NOT EXISTS content_hash VARCHAR(128);
ALTER TABLE data_agent_skill_version ADD COLUMN IF NOT EXISTS revoked BOOLEAN NOT NULL DEFAULT FALSE;

-- 两条复合外键的被引用唯一键，基线已建，这里只做幂等补齐（缺失则复合外键无法成立）
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_data_agent_skill_version_id_skill') THEN
    ALTER TABLE data_agent_skill_version
      ADD CONSTRAINT uk_data_agent_skill_version_id_skill UNIQUE (id, skill_id);
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS data_agent_skill_version_idx_skill_id
    ON data_agent_skill_version (skill_id);

-- 平台来源版本反查（租户侧本地副本按来源版本定位）
-- 注意：市场撤销的级联不走本列。安装是「直接引用来源 SkillVersion」模式，被安装的行属于发布者租户，
-- 平台撤销上架条目不得回写它；级联按 agent_workspace_skill_installation.listing_id 作用于安装记录。
CREATE INDEX IF NOT EXISTS data_agent_skill_version_idx_source_listing_version
    ON data_agent_skill_version (source_listing_version_id)
    WHERE source_listing_version_id IS NOT NULL;

COMMENT ON TABLE data_agent_skill_version IS 'Skill 不可变版本（发布后内容冻结）';
COMMENT ON COLUMN data_agent_skill_version.source_listing_version_id IS '平台来源版本：租户把市场能力复制成本地副本时记录的 skill_market_listing_version.id；当前安装为直接引用来源版本模式，市场侧不写本列，本地创建版本为空';
COMMENT ON COLUMN data_agent_skill_version.content_hash IS '市场内容哈希：租户本地副本记录的来源市场版本 content_hash；市场安装的内容哈希落在 agent_workspace_skill_installation.content_hash';
COMMENT ON COLUMN data_agent_skill_version.revoked IS '撤销标记：仅表示本行自身不可用；市场条目撤销级联作用于 agent_workspace_skill_installation（按 listing_id 置 REVOKED），不回写发布者的源版本行';

-- ============================================================================
-- 3. 能力市场新表（方案第十三章：平台审核 + 使用配额，不做计费）
-- ============================================================================
DROP TABLE IF EXISTS skill_market_review;
DROP TABLE IF EXISTS skill_market_listing_version;
DROP TABLE IF EXISTS skill_market_listing;

-- 3.1 市场条目
CREATE TABLE skill_market_listing (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_name VARCHAR(128) NOT NULL,
  description TEXT,
  category VARCHAR(128),
  publisher_id VARCHAR(64),
  publisher_name VARCHAR(128),
  publisher_tenant_id VARCHAR(64),
  current_version_id BIGINT,
  io_schema_summary JSONB NOT NULL DEFAULT '{}'::jsonb,
  permission_scope VARCHAR(512),
  data_scope VARCHAR(512),
  risk_level VARCHAR(16) NOT NULL DEFAULT 'LOW',
  dependent_resources JSONB NOT NULL DEFAULT '[]'::jsonb,
  default_usage_quota INTEGER,
  compatible_engine_version VARCHAR(64),
  revoked BOOLEAN NOT NULL DEFAULT FALSE,
  review_status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT ck_skill_market_listing_review_status CHECK (review_status IN
    ('DRAFT', 'REVIEWING', 'APPROVED', 'REJECTED', 'REVOKED')),
  CONSTRAINT ck_skill_market_listing_risk_level CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH'))
);

CREATE INDEX IF NOT EXISTS skill_market_listing_idx_review_status
    ON skill_market_listing (review_status)
    WHERE deleted = FALSE;

CREATE INDEX IF NOT EXISTS skill_market_listing_idx_category
    ON skill_market_listing (category)
    WHERE deleted = FALSE;

CREATE INDEX IF NOT EXISTS skill_market_listing_idx_listing_name
    ON skill_market_listing (listing_name)
    WHERE deleted = FALSE;

-- 发布者可见范围过滤：非平台管理员的分页固定带 (review_status = 'APPROVED' OR publisher_tenant_id = ?) 谓词
CREATE INDEX IF NOT EXISTS skill_market_listing_idx_publisher_tenant_id
    ON skill_market_listing (publisher_tenant_id)
    WHERE deleted = FALSE;

COMMENT ON TABLE skill_market_listing IS '能力市场条目（平台级，平台审核 + 使用配额，不做计费）';
COMMENT ON COLUMN skill_market_listing.id IS '主键ID';
COMMENT ON COLUMN skill_market_listing.listing_name IS '条目名称';
COMMENT ON COLUMN skill_market_listing.description IS '条目说明';
COMMENT ON COLUMN skill_market_listing.category IS '分类';
COMMENT ON COLUMN skill_market_listing.publisher_id IS '发布者用户ID';
COMMENT ON COLUMN skill_market_listing.publisher_name IS '发布者名称';
COMMENT ON COLUMN skill_market_listing.publisher_tenant_id IS '发布者租户ID';
COMMENT ON COLUMN skill_market_listing.current_version_id IS '当前版本引用（skill_market_listing_version.id，审核通过后指向最新通过版本）';
COMMENT ON COLUMN skill_market_listing.io_schema_summary IS '输入输出 Schema 摘要（JSONB）';
COMMENT ON COLUMN skill_market_listing.permission_scope IS '权限范围说明（所需权限码/能力边界）';
COMMENT ON COLUMN skill_market_listing.data_scope IS '数据范围说明（可触达的数据边界）';
COMMENT ON COLUMN skill_market_listing.risk_level IS '风险等级：LOW/MEDIUM/HIGH';
COMMENT ON COLUMN skill_market_listing.dependent_resources IS '依赖资源（数据源/凭据/工具等，JSONB）';
COMMENT ON COLUMN skill_market_listing.default_usage_quota IS '使用配额默认值（次/日），安装时作为租户配额初始值';
COMMENT ON COLUMN skill_market_listing.compatible_engine_version IS '兼容引擎版本';
COMMENT ON COLUMN skill_market_listing.revoked IS '撤销状态';
COMMENT ON COLUMN skill_market_listing.review_status IS '审核状态：DRAFT/REVIEWING/APPROVED/REJECTED/REVOKED';

-- 3.2 市场条目版本（不可变：提交审核时对引用 Skill 版本做快照，落库后不修改）
CREATE TABLE skill_market_listing_version (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id BIGINT NOT NULL,
  version_no INTEGER NOT NULL,
  skill_version_id BIGINT NOT NULL,
  content_hash VARCHAR(128) NOT NULL,
  change_note TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE UNIQUE INDEX IF NOT EXISTS skill_market_listing_version_uidx_listing_version_no
    ON skill_market_listing_version (listing_id, version_no)
    WHERE deleted = FALSE;

CREATE INDEX IF NOT EXISTS skill_market_listing_version_idx_skill_version_id
    ON skill_market_listing_version (skill_version_id);

COMMENT ON TABLE skill_market_listing_version IS '能力市场条目版本（不可变快照，安装追溯与撤销级联依据）';
COMMENT ON COLUMN skill_market_listing_version.id IS '主键ID';
COMMENT ON COLUMN skill_market_listing_version.listing_id IS '市场条目ID';
COMMENT ON COLUMN skill_market_listing_version.version_no IS '条目内版本号，从 1 递增';
COMMENT ON COLUMN skill_market_listing_version.skill_version_id IS '引用的 Skill 版本ID（data_agent_skill_version.id，Long 引用不加外键）';
COMMENT ON COLUMN skill_market_listing_version.content_hash IS '内容哈希（Skill 版本内容摘要，安装侧校验一致性）';
COMMENT ON COLUMN skill_market_listing_version.change_note IS '变更说明';

-- 3.3 市场审核记录
CREATE TABLE skill_market_review (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id BIGINT NOT NULL,
  listing_version_id BIGINT NOT NULL,
  reviewer_id VARCHAR(64),
  reviewer_name VARCHAR(128),
  conclusion VARCHAR(32) NOT NULL,
  opinion TEXT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT ck_skill_market_review_conclusion CHECK (conclusion IN ('APPROVED', 'REJECTED'))
);

CREATE INDEX IF NOT EXISTS skill_market_review_idx_listing_id
    ON skill_market_review (listing_id);

CREATE INDEX IF NOT EXISTS skill_market_review_idx_listing_version_id
    ON skill_market_review (listing_version_id);

COMMENT ON TABLE skill_market_review IS '能力市场平台审核记录';
COMMENT ON COLUMN skill_market_review.id IS '主键ID';
COMMENT ON COLUMN skill_market_review.listing_id IS '市场条目ID（冗余，便于按条目查审核历史）';
COMMENT ON COLUMN skill_market_review.listing_version_id IS '被审核的条目版本ID';
COMMENT ON COLUMN skill_market_review.reviewer_id IS '审核人用户ID';
COMMENT ON COLUMN skill_market_review.reviewer_name IS '审核人名称';
COMMENT ON COLUMN skill_market_review.conclusion IS '审核结论：APPROVED/REJECTED';
COMMENT ON COLUMN skill_market_review.opinion IS '审核意见';

-- ============================================================================
-- 4. 执行后自检：data_agent_skill_version 引用完整性
--    若本库曾执行过本脚本旧版的 `DROP TABLE data_agent_skill_version CASCADE`，
--    这里会检出缺失的外键/触发器。**只报错不自愈** —— 悬空引用必须先人工确认再清理，
--    处理脚本见同目录 09-skill-version-dangling-repair.sql（需维护者批准后执行）。
--    按引用表名而非约束名判定，避免受 PG 自动命名（*_skill_version_id_fkey）影响。
-- ============================================================================
DO $$
DECLARE
  v_missing_fk      TEXT[];
  v_missing_trigger TEXT[];
BEGIN
  SELECT array_agg(expected.relname ORDER BY expected.relname)
    INTO v_missing_fk
    FROM (VALUES
      ('data_agent_skill'),
      ('data_agent_skill_binding'),
      ('data_agent_flow_instance'),
      ('data_agent_skill_tool_ref'),
      ('agent_runtime_hook'),
      ('agent_runtime_hook_log')
    ) AS expected(relname)
   WHERE to_regclass(expected.relname) IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
         FROM pg_constraint constraint_info
        WHERE constraint_info.contype = 'f'
          AND constraint_info.conrelid = to_regclass(expected.relname)
          AND constraint_info.confrelid = to_regclass('data_agent_skill_version')
     );

  SELECT array_agg(expected.tgname ORDER BY expected.tgname)
    INTO v_missing_trigger
    FROM (VALUES
      ('trg_data_agent_skill_version_validate'),
      ('trg_data_agent_skill_version_delete_immutable')
    ) AS expected(tgname)
   WHERE NOT EXISTS (
     SELECT 1
       FROM pg_trigger trigger_info
      WHERE trigger_info.tgrelid = to_regclass('data_agent_skill_version')
        AND trigger_info.tgname = expected.tgname
        AND NOT trigger_info.tgisinternal
   );

  IF v_missing_fk IS NOT NULL OR v_missing_trigger IS NOT NULL THEN
    RAISE EXCEPTION 'data_agent_skill_version 引用完整性缺失，缺外键的引用表=%，缺触发器=%；本库很可能执行过旧版 DROP ... CASCADE 脚本，请先执行 09-skill-version-dangling-repair.sql 清理悬空引用并恢复约束',
      COALESCE(v_missing_fk, '{}'::text[]), COALESCE(v_missing_trigger, '{}'::text[]);
  END IF;
END;
$$;

-- =============================================================================
-- Group A: 20260817_digital_employee
-- =============================================================================

-- ============================================================================
-- 20260817_digital_employee.sql — PR-5 数字员工域四表 DDL
-- ----------------------------------------------------------------------------
-- 用途      ：数字员工身份 / 发布（Release）/ 部署（Deployment）/ 能力绑定（Capability）
--             四张基础表，落地主文档《数字员工平台完整优化方案-最终版》4.2 节
--             （注意：清单 v1.2 中"主文档 4.3"为断链引用，四表 DDL 实际在 4.2 节）。
-- 影响范围  ：仅新增对象（4 表 + 索引 + 注释），不修改任何现有表；
--             PR-1 已在 agent_task_definition / agent_runtime_run / agent_im_conversation_binding
--             预留的 digital_employee_id / employee_release_id 列自此有真实主表可引用（应用层关联，不加外键）。
-- 执行库    ：PostgreSQL（schema agent，与 20260818_drop_workspace.sql 同一约定）；
--             BIGSERIAL / TIMESTAMPTZ / JSONB / 部分索引均为 PG 语法，不兼容 MySQL。
-- 幂等性    ：CREATE TABLE IF NOT EXISTS + CREATE [UNIQUE] INDEX IF NOT EXISTS，可重复执行。
-- 回滚方式  ：见文末「ROLLBACK」段（按依赖逆序 DROP 四表，无数据迁移不可逆操作）。
-- 权限种子  ：真人权限码 ai-agent:digital-employee:query/use/manage 归属 PR-8 菜单 SQL
--             （服务治理\06-ai\数字员工方案-DDL\06-iam-permissions.sql 的修订版），
--             本脚本不重复插入，避免与 PR-8 双写漂移。
-- ============================================================================
SET search_path TO agent, public;

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. digital_employee 数字员工身份表
--    iam_principal_id 指向 IAM sys_service_principal.id（sp_ 前缀），不是 t_user.id；
--    员工不进人员表（主文档 4.1 / 5.5 硬基线）。
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS digital_employee (
    id                  BIGSERIAL PRIMARY KEY,
    tenant_id           VARCHAR(64) NOT NULL,
    employee_code       VARCHAR(64) NOT NULL,
    employee_name       VARCHAR(128) NOT NULL,
    avatar_file_id      VARCHAR(64),
    job_title           VARCHAR(128),
    description         TEXT,
    system_instruction  TEXT,
    greeting            TEXT,
    status              VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    manager_user_id     VARCHAR(64),
    iam_principal_id    VARCHAR(64),
    principal_status    VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    principal_revision  BIGINT NOT NULL DEFAULT 0,
    model_config_id     BIGINT,
    route_profile_id    BIGINT,
    source_agent_id     BIGINT,
    autonomy_level      VARCHAR(32) NOT NULL DEFAULT 'ASSISTED',
    execution_policy    JSONB NOT NULL DEFAULT '{}',
    draft_revision      INTEGER NOT NULL DEFAULT 0,
    state_version       BIGINT NOT NULL DEFAULT 0,
    approver_user_id    VARCHAR(64),
    create_by           VARCHAR(64),
    create_name         VARCHAR(128),
    create_time         TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_modify_by      VARCHAR(64),
    last_modify_name    VARCHAR(128),
    last_modify_time    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted             BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT chk_employee_status CHECK (status IN ('DRAFT','ENABLED','DISABLED','ARCHIVED')),
    CONSTRAINT chk_employee_principal_status CHECK (principal_status IN ('PENDING','READY','FAILED','DISABLED'))
);

COMMENT ON TABLE digital_employee IS '数字员工身份表（PR-5；员工不写 t_user，执行身份为 Service Principal）';
COMMENT ON COLUMN digital_employee.tenant_id IS '租户 ID（String 基线，VARCHAR(64)）';
COMMENT ON COLUMN digital_employee.employee_code IS '员工唯一编码（租户内唯一）';
COMMENT ON COLUMN digital_employee.manager_user_id IS '业务负责人（仅用于通知），不参与授权';
COMMENT ON COLUMN digital_employee.iam_principal_id IS '可空；IAM Service Principal ID（sp_ 前缀，指向 sys_service_principal），不是 t_user.id';
COMMENT ON COLUMN digital_employee.principal_status IS 'Principal 开通状态：PENDING/READY/FAILED/DISABLED；启用员工前必须 READY 且 rollout 开关打开';
COMMENT ON COLUMN digital_employee.principal_revision IS '最近一次从 IAM 观测到的 auth_revision（本地缓存比对基准）';
COMMENT ON COLUMN digital_employee.source_agent_id IS '可选；能力来源 DataAgent（创建向导「复制指定 DataAgent」），Facade 对话经此桥接既有运行时';
COMMENT ON COLUMN digital_employee.execution_policy IS '非授权运营配置（预算提醒等）；谁能用/能调什么以授权中心为准，本列不是事实源';
COMMENT ON COLUMN digital_employee.state_version IS 'CAS 版本号（启用/停用等状态迁移防覆盖）';
COMMENT ON COLUMN digital_employee.approver_user_id IS '审批人（真人 userId；审批人不得与创建人相同，服务层校验）';
COMMENT ON COLUMN digital_employee.job_title IS '岗位（position 标签，仅展示用，不参与授权）';

CREATE UNIQUE INDEX IF NOT EXISTS uk_employee_code_tenant
    ON digital_employee (tenant_id, employee_code) WHERE deleted = false;
CREATE INDEX IF NOT EXISTS digital_employee_idx_tenant_status
    ON digital_employee (tenant_id, status, id DESC) WHERE deleted = false;
CREATE INDEX IF NOT EXISTS digital_employee_idx_tenant_create_by
    ON digital_employee (tenant_id, create_by, status) WHERE deleted = false;
CREATE UNIQUE INDEX IF NOT EXISTS uk_employee_iam_principal
    ON digital_employee (tenant_id, iam_principal_id)
    WHERE deleted = false AND iam_principal_id IS NOT NULL;

-- ----------------------------------------------------------------------------
-- 2. digital_employee_release 数字员工发布表（独立于 data_agent_release，主文档 4.2 设计决策）
--    Seal 时冻结能力清单进 snapshot（运行时唯一能力来源），Seal 后草稿改动不影响本表。
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS digital_employee_release (
    id                  BIGSERIAL PRIMARY KEY,
    tenant_id           VARCHAR(64) NOT NULL,
    employee_id         BIGINT NOT NULL,
    release_no          INTEGER NOT NULL,
    schema_version      VARCHAR(32) NOT NULL,
    snapshot            JSONB NOT NULL,
    spec_hash           VARCHAR(64) NOT NULL,
    base_release_id     BIGINT,
    source_type         VARCHAR(32),
    source_agent_id     BIGINT,
    source_release_id   BIGINT,
    status              VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    sealed_at           TIMESTAMPTZ,
    sealed_by           VARCHAR(64),
    published_at        TIMESTAMPTZ,
    published_by        VARCHAR(64),
    authorization_policy_version_id BIGINT,
    authorization_policy_hash VARCHAR(64),
    create_by           VARCHAR(64),
    create_name         VARCHAR(128),
    create_time         TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_modify_by      VARCHAR(64),
    last_modify_name    VARCHAR(128),
    last_modify_time    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted             BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT chk_release_status CHECK (status IN ('DRAFT','SEALED','PUBLISHED','RETIRED'))
);

COMMENT ON TABLE digital_employee_release IS '数字员工发布表（DRAFT→SEALED→PUBLISHED→RETIRED）';
COMMENT ON COLUMN digital_employee_release.snapshot IS '完整运行规范快照，含 Seal 时冻结的能力清单（authMode/permissionCode/风险/模型参数/预算/技能绑定）；运行时唯一能力来源';
COMMENT ON COLUMN digital_employee_release.spec_hash IS '快照 SHA-256（Seal 时计算，冻结语义的完整性锚点）';
COMMENT ON COLUMN digital_employee_release.authorization_policy_version_id IS '发布门禁记录（预留可空）；运行时策略指针以 agent_authorization_binding 为准（主文档 5.7）';
COMMENT ON COLUMN digital_employee_release.authorization_policy_hash IS '策略 JSON checksum（发布门禁与决策重放对齐，预留可空）';

CREATE UNIQUE INDEX IF NOT EXISTS uk_release_no_tenant_emp
    ON digital_employee_release (tenant_id, employee_id, release_no) WHERE deleted = false;
CREATE INDEX IF NOT EXISTS digital_employee_release_idx_tenant_emp_status
    ON digital_employee_release (tenant_id, employee_id, status) WHERE deleted = false;

-- ----------------------------------------------------------------------------
-- 3. digital_employee_deployment 数字员工部署表（CAS 激活/回滚）
--    每租户每员工每环境至多一行活跃部署；按主文档 4.2 约定不做软删除（审计走
--    deployment_version 递增链路），故本表无 deleted 列、唯一索引不带部分谓词。
--    create_by/create_name/last_modify_* 列对齐框架 MyBatisMetaObjectHandler 自动填充
--    （实体不继承 SuperEntity 而直接继承 Entity，避免 @TableLogic 自动追加 deleted 谓词）。
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS digital_employee_deployment (
    id                      BIGSERIAL PRIMARY KEY,
    tenant_id               VARCHAR(64) NOT NULL,
    employee_id             BIGINT NOT NULL,
    environment             VARCHAR(32) NOT NULL,
    active_release_id       BIGINT,
    previous_release_id     BIGINT,
    deployment_version      INTEGER NOT NULL DEFAULT 0,
    status                  VARCHAR(32) NOT NULL DEFAULT 'INACTIVE',
    deployed_by             VARCHAR(64),
    deployed_at             TIMESTAMPTZ,
    create_by               VARCHAR(64),
    create_name             VARCHAR(128),
    create_time             TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_modify_by          VARCHAR(64),
    last_modify_name        VARCHAR(128),
    last_modify_time        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_deploy_env CHECK (environment IN ('SANDBOX','PRODUCTION')),
    CONSTRAINT chk_deploy_status CHECK (status IN ('INACTIVE','ACTIVE','ROLLING_BACK'))
);

COMMENT ON TABLE digital_employee_deployment IS '数字员工部署表（CAS：deployment_version 条件更新防并发覆盖）';
COMMENT ON COLUMN digital_employee_deployment.active_release_id IS '当前激活的 digital_employee_release.id';
COMMENT ON COLUMN digital_employee_deployment.previous_release_id IS '切换前的激活 Release（回滚参照）';
COMMENT ON COLUMN digital_employee_deployment.deployment_version IS 'CAS 版本号，每次激活/回滚 +1；UPDATE 影响 0 行即版本冲突';

-- 唯一 (tenant_id, employee_id, environment)；任务要求部分索引 WHERE deleted=false，
-- 本表无 deleted 列（见上），故用全量唯一索引等价实现唯一性。
CREATE UNIQUE INDEX IF NOT EXISTS uk_deploy_env_tenant_emp
    ON digital_employee_deployment (tenant_id, employee_id, environment);

-- ----------------------------------------------------------------------------
-- 4. digital_employee_capability 数字员工能力绑定表（草稿态，非运行时事实源）
--    Seal 时冻结进 Release snapshot；运行时不读本表（主文档 4.2 / 坑 18）。
--    skill_version_id 只能绑定已发布 SkillVersion；市场安装（PR-5 重建）幂等写本表。
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS digital_employee_capability (
    id                  BIGSERIAL PRIMARY KEY,
    tenant_id           VARCHAR(64) NOT NULL,
    employee_id         BIGINT NOT NULL,
    skill_version_id    BIGINT NOT NULL,
    enabled             BOOLEAN NOT NULL DEFAULT true,
    create_by           VARCHAR(64),
    create_name         VARCHAR(128),
    create_time         TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_modify_by      VARCHAR(64),
    last_modify_name    VARCHAR(128),
    last_modify_time    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted             BOOLEAN NOT NULL DEFAULT false
);

COMMENT ON TABLE digital_employee_capability IS '数字员工能力绑定表（草稿态；Seal 冻结进 Release snapshot，运行时不读本表；市场安装幂等落点）';

CREATE UNIQUE INDEX IF NOT EXISTS uk_emp_capability
    ON digital_employee_capability (tenant_id, employee_id, skill_version_id) WHERE deleted = false;
CREATE INDEX IF NOT EXISTS digital_employee_capability_idx_tenant_employee
    ON digital_employee_capability (tenant_id, employee_id) WHERE deleted = false;

COMMIT;

