-- ROLLBACK（回滚方式：按依赖逆序 DROP；PR-5 上线前无生产数据，直接 DROP 即可；
--          上线后回滚需先确认 agent_task_definition.employee_release_id 无引用）
-- ----------------------------------------------------------------------------
