-- DROP TABLE IF EXISTS agent.digital_employee_release;
-- DROP TABLE IF EXISTS agent.digital_employee;

-- =============================================================================
-- Group A: 20260820_digital_employee_clean_architecture
-- =============================================================================

-- ============================================================================
-- 20260820_digital_employee_clean_architecture.sql
--
-- 【用途】
--   干净架构产品补强：新建「数字员工」目录（任务中心 / 数字员工管理 / 技能市场），
--   运行记录与 Agent 评估同父平级（禁止挂到评估叶子下），隐藏发布管理，
--   新增 digital_employee_model_config（员工可用+默认模型）。
--
-- 【影响范围】
--   - IAM menu SQL is omitted in the open-source baseline.
--     运行记录、Agent 评估 的标题、可见性、父级；补授已有子菜单角色对目录的绑定。
--   - agent.digital_employee_model_config：新表。
--   - 逻辑删除 ai-agent_releases（发布管理）菜单，不删角色历史绑定（status=false, deleted=true）。
--
-- 【回滚方式】
--   - IAM menu restore is omitted in the open-source baseline.
--   - 模型表：DROP TABLE digital_employee_model_config。
--
-- 【PostgreSQL 兼容性】
--   PostgreSQL 12+；IAM 菜单 visible=TRUE 表示从侧栏隐藏（与既有约定一致）。
--
-- 【幂等】
--   可重复执行。若旧版 2.4 已把运行记录挂到 Agent 评估叶子下，重跑本段会挪回与评估同父。
--
-- 【执行】
--   需维护者明确批准后执行。
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. 员工可用模型表（禁止复用 agent_model_config.agent_id）
-- ----------------------------------------------------------------------------
SET LOCAL search_path TO agent, public;

CREATE TABLE IF NOT EXISTS digital_employee_model_config (
    id                  BIGSERIAL PRIMARY KEY,
    tenant_id           VARCHAR(64) NOT NULL,
    employee_id         BIGINT NOT NULL,
    model_config_id     BIGINT NOT NULL,
    is_default          BOOLEAN NOT NULL DEFAULT false,
    user_selectable     BOOLEAN NOT NULL DEFAULT true,
    enabled             BOOLEAN NOT NULL DEFAULT true,
    create_by           VARCHAR(64),
    create_name         VARCHAR(128),
    create_time         TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_modify_by      VARCHAR(64),
    last_modify_name    VARCHAR(128),
    last_modify_time    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted             BOOLEAN NOT NULL DEFAULT false
);

COMMENT ON TABLE digital_employee_model_config IS '数字员工可用对话模型（与 agent_model_config 同构，禁止把员工主键写入 agent_id）';
COMMENT ON COLUMN digital_employee_model_config.employee_id IS '数字员工 ID（digital_employee.id）';
COMMENT ON COLUMN digital_employee_model_config.model_config_id IS '平台模型配置 ID';
COMMENT ON COLUMN digital_employee_model_config.is_default IS '是否默认模型；同时回写 digital_employee.model_config_id';
COMMENT ON COLUMN digital_employee_model_config.user_selectable IS '对话页是否允许用户选择';
COMMENT ON COLUMN digital_employee_model_config.enabled IS '是否启用';

CREATE INDEX IF NOT EXISTS digital_employee_model_config_idx_employee
    ON digital_employee_model_config (tenant_id, employee_id, id)
    WHERE deleted = false;

CREATE UNIQUE INDEX IF NOT EXISTS uk_emp_model_config
    ON digital_employee_model_config (tenant_id, employee_id, model_config_id)
    WHERE deleted = false;

-- ----------------------------------------------------------------------------

COMMIT;

-- =============================================================================
-- Group A: 20260818_authorization_pap
-- =============================================================================

-- Agent 统一授权中心（PAP）四张策略表 DDL —— PR-3b
-- 用途：落地《数字员工平台完整优化方案》5.7 控制面：
--   1) agent_authorization_policy          策略主档（当前版本指针）
--   2) agent_authorization_policy_version   策略版本（发布后 JSON 不可变：应用层守卫，只允许翻转 published 标志，禁止 UPDATE 已发布版本的 policy_json/policy_hash）
--   3) agent_authorization_binding          owner→策略版本 运行时唯一指针（(owner_type, owner_id, environment) 唯一，bind_revision 乐观锁 CAS 切换）
--   4) agent_authorization_grant            数字员工对象级授权（DISCOVER/USE；DataAgent 首期仍走 legacy visibility 三表，不双写）
-- 影响：仅新增 agent schema 下四张新表，不改任何现网表（data_agent_visibility_policy/grant/application 保持原样）；
--   租户插件白名单默认空，所有 Mapper 查询手写 tenant_id 谓词（见 AgentAuthorization*Mapper）。
-- 回滚：DROP INDEX IF EXISTS ...; DROP TABLE IF EXISTS ...（按 grant→binding→version→policy 顺序，见文件尾回滚段）；
--   回滚前确认 agent_authorization_binding 无运行中引用（数字员工 Release 发布门禁记录引用 policy_version_id）。
-- PostgreSQL：CREATE TABLE/INDEX IF NOT EXISTS 幂等；TIMESTAMPTZ + JSONB + 部分唯一索引（WHERE deleted = false）兼容 PostgreSQL 12+；
--   约束以建表内联 CHECK 表达（PG 不支持 ADD CONSTRAINT IF NOT EXISTS，幂等由 CREATE TABLE IF NOT EXISTS 整体保证）。
-- 注意：本脚本只归档服务治理目录，不放入 src/main/resources/dataagent/sql/pg/（该目录已停止新增迁移脚本，PRD F-2）。

CREATE SCHEMA IF NOT EXISTS agent;

SET search_path TO agent, public;

BEGIN;

-- ---------------------------------------------------------------------
-- 1. agent_authorization_policy：策略主档
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_authorization_policy (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  code VARCHAR(128) NOT NULL,
  name VARCHAR(255) NOT NULL,
  template_code VARCHAR(64) NOT NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
  current_version_id BIGINT,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_agent_authorization_policy_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'RETIRED'))
);

COMMENT ON TABLE agent_authorization_policy IS 'Agent 授权策略主档：策略编码/名称/模板来源与当前发布版本指针（PR-3b 授权中心 PAP）';
COMMENT ON COLUMN agent_authorization_policy.tenant_id IS '所属租户ID（租户插件白名单默认空，查询必须手写 tenant_id 谓词）';
COMMENT ON COLUMN agent_authorization_policy.code IS '策略编码，租户内唯一';
COMMENT ON COLUMN agent_authorization_policy.template_code IS '来源模板：MODEL_ONLY/CALLER_READ_ONLY/CALLER_INTERACTIVE/DIGITAL_WORKER';
COMMENT ON COLUMN agent_authorization_policy.status IS '策略状态：DRAFT-草稿（仅此状态可 modify），PUBLISHED-已发布，RETIRED-已停用';
COMMENT ON COLUMN agent_authorization_policy.current_version_id IS '当前发布版本指针，指向 agent_authorization_policy_version.id；DRAFT 期为空';

CREATE UNIQUE INDEX IF NOT EXISTS agent_authorization_policy_idx_tenant_code
  ON agent_authorization_policy (tenant_id, code)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS agent_authorization_policy_idx_tenant_status
  ON agent_authorization_policy (tenant_id, status)
  WHERE deleted = false;

-- ---------------------------------------------------------------------
-- 2. agent_authorization_policy_version：策略版本（发布后不可变）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_authorization_policy_version (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  policy_id BIGINT NOT NULL,
  version_no INTEGER NOT NULL,
  policy_json JSONB NOT NULL,
  policy_hash VARCHAR(64) NOT NULL,
  published BOOLEAN NOT NULL DEFAULT false,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted BOOLEAN NOT NULL DEFAULT false
);

COMMENT ON TABLE agent_authorization_policy_version IS 'Agent 授权策略版本：policy_json 发布后不可变（应用层禁止 UPDATE 已发布版本的 JSON，发布动作只翻转 published 标志，新内容必须插入新版本行）';
COMMENT ON COLUMN agent_authorization_policy_version.policy_id IS '策略主档ID，引用 agent_authorization_policy.id';
COMMENT ON COLUMN agent_authorization_policy_version.version_no IS '版本号，策略内单调递增从 1 开始';
COMMENT ON COLUMN agent_authorization_policy_version.policy_json IS '策略 JSON（schemaVersion=1，仅 templateCode/subjectMode/iamUnavailableBehavior/allowModelOnly/rules[]，PolicyValidator 严格校验后落库）';
COMMENT ON COLUMN agent_authorization_policy_version.policy_hash IS '规范化 JSON 的 SHA-256（AuthorizationPolicy.computeHash，PR-3a 冻结算法），用于决策重放与发布门禁对齐';
COMMENT ON COLUMN agent_authorization_policy_version.published IS '是否已发布：false=草稿（可 modify），true=已发布（JSON 永不更新）';

CREATE UNIQUE INDEX IF NOT EXISTS agent_authorization_policy_version_idx_policy_version_no
  ON agent_authorization_policy_version (policy_id, version_no)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS agent_authorization_policy_version_idx_tenant_policy
  ON agent_authorization_policy_version (tenant_id, policy_id)
  WHERE deleted = false;

-- ---------------------------------------------------------------------
-- 3. agent_authorization_binding：owner → 策略版本运行时指针（CAS）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_authorization_binding (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  owner_type VARCHAR(32) NOT NULL,
  owner_id BIGINT NOT NULL,
  environment VARCHAR(32) NOT NULL,
  policy_version_id BIGINT NOT NULL,
  bind_revision BIGINT NOT NULL DEFAULT 0,
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_agent_authorization_binding_owner_type CHECK (owner_type IN ('DATA_AGENT', 'DIGITAL_EMPLOYEE')),
  CONSTRAINT ck_agent_authorization_binding_environment CHECK (environment IN ('SANDBOX', 'PRODUCTION'))
);

COMMENT ON TABLE agent_authorization_binding IS 'Agent 授权绑定：运行时策略指针唯一事实源（主文档 5.7）；切换策略版本走 bind_revision CAS 乐观锁，冲突方拿最新值重试';
COMMENT ON COLUMN agent_authorization_binding.owner_type IS '授权对象类型：DATA_AGENT-普通智能体，DIGITAL_EMPLOYEE-数字员工';
COMMENT ON COLUMN agent_authorization_binding.owner_id IS '授权对象ID（data_agent.id 或 digital_employee.id，跨域仅存ID不建外键）';
COMMENT ON COLUMN agent_authorization_binding.environment IS '环境：SANDBOX/PRODUCTION，与 digital_employee_deployment.environment 枚举统一';
COMMENT ON COLUMN agent_authorization_binding.policy_version_id IS '生效策略版本ID，必须指向 published=true 的版本（应用层校验）';
COMMENT ON COLUMN agent_authorization_binding.bind_revision IS '绑定乐观锁版本：每次 CAS 更新 +1，并发切换冲突时后到方失败并读取最新值';

CREATE UNIQUE INDEX IF NOT EXISTS agent_authorization_binding_idx_owner_environment
  ON agent_authorization_binding (owner_type, owner_id, environment)
  WHERE deleted = false;

CREATE INDEX IF NOT EXISTS agent_authorization_binding_idx_tenant_owner
  ON agent_authorization_binding (tenant_id, owner_type, owner_id)
  WHERE deleted = false;

-- ---------------------------------------------------------------------
-- 4. agent_authorization_grant：数字员工对象级授权（DISCOVER/USE）
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS agent_authorization_grant (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  owner_type VARCHAR(32) NOT NULL,
  owner_id BIGINT NOT NULL,
  subject_type VARCHAR(32) NOT NULL,
  subject_id VARCHAR(128) NOT NULL,
  subject_name VARCHAR(255),
  resource_type VARCHAR(64) NOT NULL DEFAULT 'OWNER',
  resource_id VARCHAR(128),
  permission VARCHAR(32) NOT NULL,
  source_type VARCHAR(32) NOT NULL DEFAULT 'MANUAL',
  expire_time TIMESTAMPTZ,
  status VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
  create_by VARCHAR(64),
  create_name VARCHAR(128),
  create_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_modify_by VARCHAR(64),
  last_modify_name VARCHAR(128),
  last_modify_time TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT ck_agent_authorization_grant_owner_type CHECK (owner_type IN ('DATA_AGENT', 'DIGITAL_EMPLOYEE')),
  CONSTRAINT ck_agent_authorization_grant_subject_type CHECK (subject_type IN ('USER', 'TEAM', 'PERMISSION', 'TENANT')),
  CONSTRAINT ck_agent_authorization_grant_permission CHECK (permission IN ('DISCOVER', 'USE')),
  CONSTRAINT ck_agent_authorization_grant_status CHECK (status IN ('ACTIVE', 'REVOKED'))
);

COMMENT ON TABLE agent_authorization_grant IS 'Agent 对象级授权（Grant）：谁能 DISCOVER/USE 哪个 owner；首期数字员工消费本表，普通 DataAgent 仍由 legacy visibility 三表经 LegacyVisibilityPolicyProvider 判定（不双写）';
COMMENT ON COLUMN agent_authorization_grant.subject_type IS '被授权主体类型：USER/TEAM/PERMISSION/TENANT（与 legacy visibility subject_type 枚举一致）';
COMMENT ON COLUMN agent_authorization_grant.subject_id IS '被授权主体ID（用户ID/团队ID/权限码/租户ID）';
COMMENT ON COLUMN agent_authorization_grant.resource_type IS '资源类型：OWNER-授权针对 owner 整体（首期固定），预留细分资源';
COMMENT ON COLUMN agent_authorization_grant.resource_id IS '资源ID，resource_type=OWNER 时等于 owner_id 字符串';
COMMENT ON COLUMN agent_authorization_grant.permission IS '授权动作：DISCOVER-可见，USE-可进入业务场景';
COMMENT ON COLUMN agent_authorization_grant.source_type IS '来源：MANUAL-权限中心手动，MIGRATED-legacy 迁移（未启用），SYSTEM_INIT-系统初始化';
COMMENT ON COLUMN agent_authorization_grant.expire_time IS '过期时间，空=永久';
COMMENT ON COLUMN agent_authorization_grant.status IS '状态：ACTIVE-生效，REVOKED-已回收（删除即回收，逻辑删除标记同步置位）';

CREATE UNIQUE INDEX IF NOT EXISTS agent_authorization_grant_idx_owner_subject_permission
  ON agent_authorization_grant (owner_type, owner_id, subject_type, subject_id, permission)
  WHERE deleted = false AND status = 'ACTIVE';

CREATE INDEX IF NOT EXISTS agent_authorization_grant_idx_tenant_owner
  ON agent_authorization_grant (tenant_id, owner_type, owner_id)
  WHERE deleted = false;

COMMIT;

