-- DROP INDEX IF EXISTS agent_authorization_grant_idx_owner_subject_permission;
-- DROP INDEX IF EXISTS agent_authorization_binding_idx_tenant_owner;
-- DROP INDEX IF EXISTS agent_authorization_binding_idx_owner_environment;
-- DROP INDEX IF EXISTS agent_authorization_policy_version_idx_tenant_policy;
-- DROP INDEX IF EXISTS agent_authorization_policy_version_idx_policy_version_no;
-- DROP INDEX IF EXISTS agent_authorization_policy_idx_tenant_status;
-- DROP INDEX IF EXISTS agent_authorization_policy_idx_tenant_code;
-- DROP TABLE IF EXISTS agent_authorization_grant;
-- DROP TABLE IF EXISTS agent_authorization_binding;
