-- =============================================================================
-- Group A: 20260818_authorization_pep_audit
-- =============================================================================

-- ============================================================================
-- PEP 授权决策审计列增量迁移 —— PR-3c（PEP 内核扩展 + 审计列 + Hook/输出/记忆三线）
-- 日期：2026-08-18
-- 用途：落地《数字员工平台 - 落地执行清单 v1.2》PR-3c 交付物 2/3：
--   1) agent_runtime_event 新增 5 列：decision_id / policy_hash / subject_kind /
--      reason_code / detailed_decision_log(JSONB)。授权决策影子事件（event_type=
--      AUTHORIZATION_DECISION）经 appendAuthorizationDecision 落库：审计四列冗余
--      存储（供 SQL 聚合与 PR-10 差异报告），明细 JSONB 携带 original_decision /
--      shadow_decision / comparison_status / mode / revision_matched / bind_revision。
--   2) agent_runtime_invocation 新增 4 列：decision_id / policy_hash / subject_kind /
--      reason_code。网关检查链放行后经 attachDecision 回填首次判定（decision_id 为空
--      才写入，一次调用只挂首次判定的审计口径）。
-- 影响范围：public schema 两张存量运行时表仅追加可空列（detailed_decision_log 带
--   DEFAULT '{}'::jsonb，PG 加列不重写堆表），既有 INSERT/SELECT 语句不受影响；
--   非授权决策事件的新列恒为 NULL，不改变任何现网读写语义。
--   实体映射：AgentRuntimeEvent / AgentRuntimeInvocation 已同步追加对应字段
--   （detailedDecisionLog 走 JsonbStringTypeHandler）。
-- 回滚：见文件尾回滚段（DROP INDEX + DROP COLUMN，均为 IF EXISTS 幂等）；
--   回滚前确认无 PR-10 观测报表消费 AUTHORIZATION_DECISION 事件。
-- PostgreSQL：ADD COLUMN IF NOT EXISTS / CREATE INDEX IF NOT EXISTS 幂等，兼容 PG 12+；
--   部分索引（WHERE deleted = false [AND 谓词]）与 02-runtime.sql 既有索引风格一致。
-- 注意：本脚本只归档服务治理目录，不放入 src/main/resources/dataagent/sql/pg/
--   （该目录已停止新增迁移脚本，PRD F-2）；02-runtime.sql 的权威建表语句已同步
--   补列（该文件走整表 DROP 重建路径，两条部署路径结构一致）。
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. agent_runtime_event：授权决策审计列
-- ----------------------------------------------------------------------------
ALTER TABLE agent_runtime_event ADD COLUMN IF NOT EXISTS decision_id VARCHAR(64);
ALTER TABLE agent_runtime_event ADD COLUMN IF NOT EXISTS policy_hash VARCHAR(64);
ALTER TABLE agent_runtime_event ADD COLUMN IF NOT EXISTS subject_kind VARCHAR(32);
ALTER TABLE agent_runtime_event ADD COLUMN IF NOT EXISTS reason_code VARCHAR(64);
ALTER TABLE agent_runtime_event ADD COLUMN IF NOT EXISTS detailed_decision_log JSONB NOT NULL DEFAULT '{}'::jsonb;

COMMENT ON COLUMN agent_runtime_event.decision_id IS '授权决策ID（PEP 影子决策贯穿标识，非授权决策事件为空）';
COMMENT ON COLUMN agent_runtime_event.policy_hash IS '参与判定的策略哈希（决策审计列，非授权决策事件为空）';
COMMENT ON COLUMN agent_runtime_event.subject_kind IS '决策主体类别（CALLER/DIGITAL_EMPLOYEE，决策审计列）';
COMMENT ON COLUMN agent_runtime_event.reason_code IS 'PDP 原因码（拒绝原因传播，决策审计列）';
COMMENT ON COLUMN agent_runtime_event.detailed_decision_log IS '决策明细日志 JSON：decisionId/scene/policyHash/originalDecision/shadowDecision/comparisonStatus/mode/revisionMatched/bindRevision（供 PR-10 差异报告消费）';

-- 按决策ID追溯（对账 / 重放定位）
CREATE INDEX IF NOT EXISTS agent_runtime_event_idx_decision_id
  ON agent_runtime_event(decision_id)
  WHERE deleted = false AND decision_id IS NOT NULL;

-- 租户级授权决策聚合（PR-9 灰度门禁 / PR-10 差异报告主查询路径）
CREATE INDEX IF NOT EXISTS agent_runtime_event_idx_tenant_authz
  ON agent_runtime_event(tenant_id, occurred_at)
  WHERE deleted = false AND event_type = 'AUTHORIZATION_DECISION';

-- ----------------------------------------------------------------------------
-- 2. agent_runtime_invocation：授权决策审计列
-- ----------------------------------------------------------------------------
ALTER TABLE agent_runtime_invocation ADD COLUMN IF NOT EXISTS decision_id VARCHAR(64);
ALTER TABLE agent_runtime_invocation ADD COLUMN IF NOT EXISTS policy_hash VARCHAR(64);
ALTER TABLE agent_runtime_invocation ADD COLUMN IF NOT EXISTS subject_kind VARCHAR(32);
ALTER TABLE agent_runtime_invocation ADD COLUMN IF NOT EXISTS reason_code VARCHAR(64);

COMMENT ON COLUMN agent_runtime_invocation.decision_id IS '授权决策ID（PEP 决策审计列，首次判定后不再覆盖）';
COMMENT ON COLUMN agent_runtime_invocation.policy_hash IS '参与判定的策略哈希（PEP 决策审计列）';
COMMENT ON COLUMN agent_runtime_invocation.subject_kind IS '决策主体类别（CALLER/DIGITAL_EMPLOYEE，PEP 决策审计列）';
COMMENT ON COLUMN agent_runtime_invocation.reason_code IS 'PDP 原因码（PEP 决策审计列）';

-- 按决策ID反查调用记录
CREATE INDEX IF NOT EXISTS agent_runtime_invocation_idx_decision_id
  ON agent_runtime_invocation(decision_id)
  WHERE deleted = false AND decision_id IS NOT NULL;

COMMIT;

-- ----------------------------------------------------------------------------
-- 回滚脚本（DBA 确认无 PR-10 观测消费后执行）：
-- DROP INDEX IF EXISTS agent_runtime_invocation_idx_decision_id;
-- DROP INDEX IF EXISTS agent_runtime_event_idx_tenant_authz;
-- DROP INDEX IF EXISTS agent_runtime_event_idx_decision_id;
-- ALTER TABLE agent_runtime_invocation DROP COLUMN IF EXISTS reason_code;
-- ALTER TABLE agent_runtime_invocation DROP COLUMN IF EXISTS subject_kind;
-- ALTER TABLE agent_runtime_invocation DROP COLUMN IF EXISTS policy_hash;
-- ALTER TABLE agent_runtime_invocation DROP COLUMN IF EXISTS decision_id;
-- ALTER TABLE agent_runtime_event DROP COLUMN IF EXISTS detailed_decision_log;
-- ALTER TABLE agent_runtime_event DROP COLUMN IF EXISTS reason_code;
-- ALTER TABLE agent_runtime_event DROP COLUMN IF EXISTS subject_kind;
-- ALTER TABLE agent_runtime_event DROP COLUMN IF EXISTS policy_hash;
-- ALTER TABLE agent_runtime_event DROP COLUMN IF EXISTS decision_id;
-- （列删除不可逆，回滚即丢弃审计数据；仅灰度观测期数据，无业务状态依赖）
-- ----------------------------------------------------------------------------

-- =============================================================================
-- Group A: 20260818_memory_owner_ttl
-- =============================================================================

-- ============================================================================
-- 20260818_memory_owner_ttl.sql
-- PR-7：data_agent_memory 归属键切换 + workspace_id 遗留清理 + TTL 列
--
-- 用途：
--   1. 记忆归属键切换（v1.2 §8.2）：新增 digital_employee_id（数字员工共享记忆
--      归属，与 agent_id 并存）、expires_at（存储 TTL 过期时间，清理任务扫描列）；
--   2. workspace 遗留清理（承接 20260818_drop_workspace.sql「明确不动」第 2 条）：
--      存量 WORKSPACE 记忆按 v1.2 §0.2 口径一次性作废（不迁移），DROP
--      workspace_id 列与 data_agent_memory_idx_tenant_workspace 索引；
--   3. 新增部分索引：数字员工归属维度 + TTL 清理扫描维度。
--
-- 影响范围：
--   - 表：data_agent_memory（仅本表，不涉及其它表）；
--   - 数据：subject_type='WORKSPACE' 或 workspace_id 非空且未删除的存量行被置
--     deleted=true（一次性作废，保留行可回滚，不做物理删除）；其余行不动；
--   - 应用：PR-7 起 AgentMemory 实体不再映射 workspace_id（读路径收口），
--     WORKSPACE scope 新写入要求 subjectId 为数字员工 ID 并冗余落
--     digital_employee_id；MemoryScope 枚举不新增值（WORKSPACE 语义重定义为
--     数字员工共享记忆）。
--
-- 回滚方式：
--   - 结构：ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS workspace_id BIGINT;
--     CREATE INDEX IF NOT EXISTS data_agent_memory_idx_tenant_workspace
--       ON data_agent_memory(tenant_id, workspace_id);
--     （新增列/新索引回滚直接 DROP COLUMN / DROP INDEX，均带 IF EXISTS）；
--   - 数据：执行前先备份（CREATE TABLE data_agent_memory_workspace_bak_20260818 AS
--     SELECT * FROM data_agent_memory WHERE subject_type = 'WORKSPACE'），
--     回滚时按备份把作废行的 deleted 恢复为 false。
--
-- PG 兼容性：
--   - 全部语句为 PostgreSQL 方言（部分索引 WHERE 谓词、TIMESTAMPTZ、now()），
--     不可直接用于 MySQL；
--   - 幂等：ADD COLUMN IF NOT EXISTS / CREATE INDEX IF NOT EXISTS /
--     DROP ... IF EXISTS，作废 UPDATE 以 deleted = false 为幂等谓词，可重复执行。
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. 新列（归属键 + 存储TTL）
-- ----------------------------------------------------------------------------
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS digital_employee_id BIGINT;
ALTER TABLE data_agent_memory ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;

COMMENT ON COLUMN data_agent_memory.digital_employee_id IS '数字员工共享记忆归属 ID（WORKSPACE 共享记忆冗余列，subject_id 同值为数字员工 ID），空表示非数字员工归属；台账按数字员工归集以本列为准';
COMMENT ON COLUMN data_agent_memory.expires_at IS '存储 TTL 过期时间（PR-7 新增，清理任务扫描列）；与既有 valid_to 双轨：valid_to 表业务有效期（敏感记忆有效期约束），expires_at 表存储生命周期';

-- ----------------------------------------------------------------------------
-- 2. 存量处置（先于删列，回填依赖旧列仍存在）：
--    WORKSPACE 存量记忆按 v1.2 §0.2 一次性作废不迁移——workspace 域已拆除，
--    归属主体不可考，保留行（deleted=true）可回滚，不物理删除。
-- ----------------------------------------------------------------------------
UPDATE data_agent_memory
   SET deleted = true,
       last_modify_time = now()
 WHERE deleted = false
   AND (workspace_id IS NOT NULL OR subject_type = 'WORKSPACE');

-- ----------------------------------------------------------------------------
-- 3. 索引替换（新索引就绪后再删旧索引）
-- ----------------------------------------------------------------------------
-- 3.1 workspace 维度索引随列一并退场
DROP INDEX IF EXISTS data_agent_memory_idx_tenant_workspace;

-- 3.2 数字员工归属维度：WORKSPACE 共享记忆按 (tenant_id, digital_employee_id) 检索
CREATE INDEX IF NOT EXISTS data_agent_memory_idx_tenant_digital_employee
  ON data_agent_memory(tenant_id, digital_employee_id)
 WHERE deleted = false AND digital_employee_id IS NOT NULL;

-- 3.3 存储TTL清理扫描维度：清理任务按 (tenant_id, expires_at) 扫描过期记忆
CREATE INDEX IF NOT EXISTS data_agent_memory_idx_expires_at
  ON data_agent_memory(tenant_id, expires_at)
 WHERE deleted = false AND expires_at IS NOT NULL;

-- ----------------------------------------------------------------------------
-- 4. 列清理（作废已完成，应用读路径已随 PR-7 收口，无消费方）
-- ----------------------------------------------------------------------------
ALTER TABLE data_agent_memory DROP COLUMN IF EXISTS workspace_id;

COMMIT;

-- ----------------------------------------------------------------------------
-- 5. 执行后核验（人工执行，不入事务）
-- ----------------------------------------------------------------------------
-- 5.1 残留对象应为 0：
-- SELECT count(*) FROM information_schema.columns
--  WHERE table_name = 'data_agent_memory' AND column_name = 'workspace_id';
-- SELECT count(*) FROM pg_indexes
--  WHERE tablename = 'data_agent_memory' AND indexname LIKE '%workspace%';
-- 5.2 新索引应存在：
-- SELECT indexname FROM pg_indexes
--  WHERE tablename = 'data_agent_memory' AND indexname IN (
--    'data_agent_memory_idx_tenant_digital_employee',
--    'data_agent_memory_idx_expires_at');
-- 5.3 作废核验（删列前执行本条，应为 0）：
-- SELECT count(*) FROM data_agent_memory
--  WHERE deleted = false AND (workspace_id IS NOT NULL OR subject_type = 'WORKSPACE');

-- =============================================================================
-- Group A: 20260818_pr6_task_forbid_concurrency_slot
-- =============================================================================

-- ============================================================================
-- PR-6 任务改造：FORBID 并发槽（方案A：DB 侧部分唯一索引）+ 调度幂等唯一约束
-- 来源：《数字员工平台 - 落地执行清单 v1.2》PR-6 第 2/6/8 条
-- 日期：2026-08-18 | 目标库：PostgreSQL 12+ | 幂等：可重复执行
-- ============================================================================
--
-- 【用途】
--   1) idx_forbid_slot（方案A 核心）：agent_task_run 上的部分唯一索引，作为 FORBID
--      并发策略的原子仲裁——同一 (tenant_id, definition_id) 在 concurrency_policy='FORBID'
--      下同时最多一行 PENDING/RUNNING 活跃记录。100 并发竞插时 1 行成功、99 行唯一索引
--      冲突，应用层捕获后转 SKIPPED 并记录原因码 CONCURRENT_SLOT_LOCKED（验收 11.3 的 3.2：
--      1 RUNNING + 99 SKIPPED）。并发窗口内应用层另有 SELECT ... FOR UPDATE SKIP LOCKED
--      预检（AgentTaskRunMapper.findActiveByDefinitionForUpdateSkipLocked），索引是正确性兜底。
--   2) uk_agent_task_run_schedule：调度幂等显式唯一约束 (trigger_id, scheduled_time)，
--      与既有 idempotency_key（SCHEDULE:{triggerId}:{计划时刻}）语义等价、双保险，
--      保证同一调度时刻只产生一个 WorkItem（验收 11.3 的 3.1）。
--   3) agent_task_definition.active_run_id：并发槽占用镜像列（人可读 + 快速判定）。
--      launch 成功竞得槽后 CAS 占用（WHERE active_run_id IS NULL），终态回写时按
--      runId 定向释放（WHERE active_run_id = {runId}），守护作业对账回收残留。
--      镜像不承担正确性（正确性由 idx_forbid_slot 唯一保证）。
--   4) agent_task_run.concurrency_policy：触发器并发策略快照（ALLOW/FORBID），
--      部分唯一索引谓词需要按策略生效——ALLOW 策略允许多行活跃，不参与槽竞争。
--   5) agent_task_version 冻结列：PR-6 第 2 条 AgentTaskVersion 冻结清单
--      （employeeReleaseId/specHash/executionPrincipalId/authorizationPolicyVersionId/
--      authMode/budget，发布后不可改，参数调整生成新版本）。
--
-- 【清单 DDL 原文与落地差异说明】
--   清单原文（PR-6 第 8 条）：
--     ALTER TABLE agent_task_definition ADD UNIQUE INDEX idx_forbid_slot
--       (definition_id, environment) WHERE status = 'FORBIDDEN' AND active_run_id IS NULL;
--   落地差异：现网 agent_task_definition 为「一定义一行」的单行表（无 environment 列，
--   亦无 status='FORBIDDEN' 的行语义；并发策略 FORBID 存于 agent_task_trigger.
--   concurrency_policy），单行表上的部分唯一索引对并发插入无约束效果；并发竞态实际
--   发生在 agent_task_run 的「插入活跃行」路径上，故方案A 索引落在 agent_task_run，
--   并以 definition.active_run_id 承接清单中 active_run_id 的占用/释放语义。
--
-- 【执行前影响检查】
--   部分唯一索引要求存量数据无重复活跃行，先执行查重；有结果先人工收敛再建索引：
--     SELECT tenant_id, definition_id, count(*)
--     FROM agent_task_run
--     WHERE deleted = false AND concurrency_policy = 'FORBID'
--       AND run_status IN ('PENDING','RUNNING')
--     GROUP BY tenant_id, definition_id HAVING count(*) > 1;
--
-- 【执行方式】
--   CREATE INDEX 不能在事务块内执行：手工 psql 执行时保持 autocommit；
--   如经事务型迁移框架执行，请去掉 CONCURRENTLY（接受短暂锁表）。
--
-- 【回滚】
--   见文末「回滚脚本」段；列删除会丢历史数据，回滚前需 DBA 确认。
--
-- 【PG 兼容】
--   PostgreSQL 12+（部分唯一索引 + CONCURRENTLY）；逻辑删除过滤谓词与表内既有
--   部分索引（WHERE deleted = false）同口径。MySQL 不支持部分索引，本方案不适用。
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0. 前置查重（只读；有结果先人工收敛重复活跃行，否则第 2 步建索引失败）
-- ----------------------------------------------------------------------------
SELECT tenant_id, definition_id, count(*) AS active_rows
FROM agent_task_run
WHERE deleted = false
  AND run_status IN ('PENDING','RUNNING')
GROUP BY tenant_id, definition_id
HAVING count(*) > 1;

-- ----------------------------------------------------------------------------
-- 1. agent_task_run 加并发策略快照列（索引谓词按策略生效）
-- ----------------------------------------------------------------------------
ALTER TABLE agent_task_run ADD COLUMN IF NOT EXISTS concurrency_policy VARCHAR(32) NOT NULL DEFAULT 'FORBID';

COMMENT ON COLUMN agent_task_run.concurrency_policy IS '并发策略快照（ALLOW/FORBID，取自触发器落库时刻值；FORBID 行参与 idx_forbid_slot 并发槽竞争）';

-- 存量行按默认 FORBID 回填（触发器默认策略即 FORBID，与既有 findActiveByTrigger 判定口径一致）
UPDATE agent_task_run SET concurrency_policy = 'FORBID' WHERE concurrency_policy IS NULL;

-- ----------------------------------------------------------------------------
-- 2. FORBID 原子并发槽：部分唯一索引（方案A）
--    同一租户同一任务定义、FORBID 策略下，活跃（PENDING/RUNNING）行唯一
-- ----------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS idx_forbid_slot
  ON agent_task_run (tenant_id, definition_id)
  WHERE concurrency_policy = 'FORBID'
    AND run_status IN ('PENDING','RUNNING')
    AND deleted = false;

-- ----------------------------------------------------------------------------
-- 3. 调度幂等：同一 SCHEDULE 触发器同一计划时刻仅一个 WorkItem
--    （含 SKIPPED 行：错过/并发跳过的计划时刻同样占用唯一性，重扫幂等返回）
-- ----------------------------------------------------------------------------
CREATE UNIQUE INDEX IF NOT EXISTS uk_agent_task_run_schedule
  ON agent_task_run (trigger_id, scheduled_time)
  WHERE trigger_type = 'SCHEDULE'
    AND deleted = false;

-- ----------------------------------------------------------------------------
-- 4. agent_task_definition 并发槽占用镜像列
-- ----------------------------------------------------------------------------
ALTER TABLE agent_task_definition ADD COLUMN IF NOT EXISTS active_run_id BIGINT;

COMMENT ON COLUMN agent_task_definition.active_run_id IS '当前占用 FORBID 并发槽的任务运行ID（agent_task_run.id 镜像；launch CAS 占用、终态定向释放、守护作业对账回收，不承担正确性）';

-- 存量修复：把既有唯一活跃行回填到镜像列（无活跃行的定义保持 NULL）
UPDATE agent_task_definition d
SET active_run_id = r.id
FROM (SELECT DISTINCT ON (tenant_id, definition_id) id, tenant_id, definition_id
      FROM agent_task_run
      WHERE deleted = false AND run_status IN ('PENDING','RUNNING')
      ORDER BY tenant_id, definition_id, id) r
WHERE d.deleted = false
  AND d.tenant_id = r.tenant_id
  AND d.id = r.definition_id
  AND d.active_run_id IS NULL;

-- ----------------------------------------------------------------------------
-- 5. agent_task_version 冻结清单列（PR-6 第 2 条：发布后不可改）
-- ----------------------------------------------------------------------------
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS employee_release_id BIGINT;
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS execution_principal_id VARCHAR(128);
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS authorization_policy_version_id BIGINT;
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS auth_mode VARCHAR(32);
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS budget JSONB;
ALTER TABLE agent_task_version ADD COLUMN IF NOT EXISTS spec_hash VARCHAR(64);

COMMENT ON COLUMN agent_task_version.employee_release_id IS '冻结：版本生成时任务定义绑定的数字员工发布版本ID';
COMMENT ON COLUMN agent_task_version.execution_principal_id IS '冻结：版本生成时的受限执行主体标识（service principal）';
COMMENT ON COLUMN agent_task_version.authorization_policy_version_id IS '冻结：版本生成时绑定的授权策略版本ID（可空）';
COMMENT ON COLUMN agent_task_version.auth_mode IS '冻结：授权模式（MODEL_ONLY/PRINCIPAL 等，取参数快照 authMode 键，可空）';
COMMENT ON COLUMN agent_task_version.budget IS '冻结：Token 预算配置（取参数快照 budget 键，可空）';
COMMENT ON COLUMN agent_task_version.spec_hash IS '冻结：参数+提示词快照指纹（SHA-256 十六进制 64 位）';

-- 存量回填：历史版本按定义当前绑定补齐员工/主体快照
-- skipped: agent_task_definition.employee_release_id does not exist on the 04-task-im baseline


