-- =============================================================================
-- Group A: 20260821_digital_employee_spec_hash_nullable
-- =============================================================================

-- =====================================================================
-- 用途：修复数字员工发布表 spec_hash 字段约束错误
--       解决 DRAFT 状态下 spec_hash 为 null 时违反 NOT NULL 约束的问题
-- 影响范围：digital_employee_release 表的 spec_hash 字段约束
-- 兼容性：仅适用于 PostgreSQL
-- 回滚：执行回滚脚本
-- =====================================================================

BEGIN;

-- 检查当前字段状态
SELECT 
    column_name, 
    is_nullable, 
    data_type 
FROM information_schema.columns 
WHERE table_name = 'digital_employee_release' 
  AND column_name = 'spec_hash';

-- 修改 spec_hash 字段为允许 NULL
ALTER TABLE digital_employee_release 
ALTER COLUMN spec_hash DROP NOT NULL;

-- 验证修改结果
SELECT 
    column_name, 
    is_nullable, 
    data_type 
FROM information_schema.columns 
WHERE table_name = 'digital_employee_release' 
  AND column_name = 'spec_hash';

COMMENT ON COLUMN digital_employee_release.spec_hash IS '快照 SHA-256（Seal 时计算，DRAFT 状态为 NULL）';

COMMIT;

-- 验证查询：检查现有数据中 DRAFT 状态的 spec_hash 是否为 NULL
SELECT 
    id, 
    employee_id, 
    status, 
    spec_hash 
FROM digital_employee_release 
WHERE status = 'DRAFT' 
  AND deleted = false;

-- =============================================================================
-- Group A: fix_spec_hash_not_null_constraint
-- =============================================================================

-- ============================================================================
-- fix_spec_hash_not_null_constraint.sql — PR-5 数字员工发布约束修复
-- ----------------------------------------------------------------------------
-- 用途：修复 digital_employee_release.spec_hash 非空约束冲突导致发布失败
-- 
-- 根因分析：
--   createDraft 方法将 specHash 硬编码为 null，但表结构定义为 NOT NULL
--   导致 INSERT 时违反约束，数据库拒绝插入
-- 
-- 解决方案：移除 spec_hash 的非空约束，允许 DRAFT 状态的空值
--           Seal 时会重新计算并更新 spec_hash
-- 
-- 影响范围：仅修改列约束，无数据迁移风险
-- 兼容性：PostgreSQL
-- 幂等性：ALTER COLUMN ... DROP NOT NULL 可重复执行
-- 
-- 执行前检查：
--   SELECT column_name, is_nullable FROM information_schema.columns
--     WHERE table_name = 'digital_employee_release' AND column_name = 'spec_hash';
-- 
-- 回滚方式：
--   ALTER TABLE digital_employee_release ALTER COLUMN spec_hash SET NOT NULL;
-- ============================================================================

BEGIN;

SET search_path TO agent, public;

-- 解除 spec_hash 的非空约束（DRAFT 状态允许为空，Seal 时填充）
ALTER TABLE digital_employee_release 
ALTER COLUMN spec_hash DROP NOT NULL;

-- 验证是否成功
COMMENT ON COLUMN digital_employee_release.spec_hash IS 
'快照 SHA-256（Seal 时计算，DRAFT 状态可为空；冻结语义的完整性锚点）';

COMMIT;

-- ============================================================================
-- 验证 SQL（手动执行）
-- SELECT column_name, is_nullable 
-- FROM information_schema.columns
-- WHERE table_name = 'digital_employee_release' AND column_name = 'spec_hash';
-- 预期结果：is_nullable = YES
-- ============================================================================

-- =============================================================================
-- Group A: 20260824_drop_chat_owner_agent_fk
-- =============================================================================

-- ============================================================================
-- 20260824_drop_chat_owner_agent_fk.sql
--
-- 【用途】
--   数字员工对话把 digital_employee.id 写入 data_chat_session.agent_id /
--   data_chat_turn.agent_id，与库级外键 REFERENCES data_agent(id) 冲突，
--   导致创建会话时报「数据访问异常」。本脚本仅拆除会话链路上这两条 FK。
--
-- 【语义】
--   agent_id 对普通 Agent 仍是 data_agent.id；对数字员工是 digital_employee.id。
--   靠 data_chat_session.channel_type=EMPLOYEE 区分，不改普通 Agent 写入路径。
--
-- 【影响范围】
--   agent.data_chat_session.agent_id、agent.data_chat_turn.agent_id 的外键约束。
--   不改表结构、不改 data_agent 删除逻辑、不动编排表 FK。
--
-- 【幂等】可重复执行（DROP CONSTRAINT IF EXISTS）。
--
-- 【回滚】
--   必须先确保两表 agent_id 均能在 data_agent.id 找到（即没有数字员工会话/turn），否则 ADD CONSTRAINT 失败：
--     ALTER TABLE data_chat_session
--       ADD CONSTRAINT data_chat_session_agent_id_fkey
--       FOREIGN KEY (agent_id) REFERENCES data_agent(id) ON DELETE CASCADE;
--     ALTER TABLE data_chat_turn
--       ADD CONSTRAINT data_chat_turn_agent_id_fkey
--       FOREIGN KEY (agent_id) REFERENCES data_agent(id) ON DELETE CASCADE;
-- ============================================================================

BEGIN;

SET LOCAL search_path TO agent, public;

ALTER TABLE data_chat_session DROP CONSTRAINT IF EXISTS data_chat_session_agent_id_fkey;
ALTER TABLE data_chat_turn DROP CONSTRAINT IF EXISTS data_chat_turn_agent_id_fkey;

COMMENT ON COLUMN data_chat_session.agent_id IS
    '会话主体 ID：WEB/IM 等为 data_agent.id；channel_type=EMPLOYEE 时为 digital_employee.id（应用层维护，无库级外键）';
COMMENT ON COLUMN data_chat_turn.agent_id IS
    '回合主体 ID：与所属会话 agent_id 同语义（普通 Agent 为 data_agent.id，数字员工为 digital_employee.id）';

COMMIT;

-- =============================================================================
-- Group A: 20260825_employee_run_feedback_digest
-- =============================================================================

-- 数字员工运行反馈 + 每日汇总（与 business-agent/src/main/resources/dataagent/sql/pg 同文）。
-- 回滚：DROP TABLE IF EXISTS agent_runtime_run_feedback; DROP TABLE IF EXISTS digital_employee_digest;

CREATE TABLE IF NOT EXISTS agent_runtime_run_feedback (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id VARCHAR(64) NOT NULL,
	run_id BIGINT NOT NULL,
	user_id VARCHAR(64) NOT NULL,
	rating VARCHAR(8) NOT NULL,
	comment TEXT,
	create_by VARCHAR(64),
	create_name VARCHAR(128),
	create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
	last_modify_by VARCHAR(64),
	last_modify_name VARCHAR(128),
	last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
	deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE agent_runtime_run_feedback IS '数字员工运行人工反馈（UP/DOWN），导入评估用例时作为标签与期望输出';
COMMENT ON COLUMN agent_runtime_run_feedback.rating IS 'UP 正例 / DOWN 负例';
COMMENT ON COLUMN agent_runtime_run_feedback.comment IS '评语；DOWN 导入评估时可作 expectedOutput';

CREATE UNIQUE INDEX IF NOT EXISTS agent_runtime_run_feedback_uk_tenant_run_user
	ON agent_runtime_run_feedback (tenant_id, run_id, user_id)
	WHERE deleted = false;

CREATE INDEX IF NOT EXISTS agent_runtime_run_feedback_idx_run_id
	ON agent_runtime_run_feedback (run_id)
	WHERE deleted = false;

CREATE TABLE IF NOT EXISTS digital_employee_digest (
	id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	tenant_id VARCHAR(64) NOT NULL,
	employee_id BIGINT NOT NULL,
	digest_date DATE NOT NULL,
	manager_user_id VARCHAR(64),
	run_total INTEGER NOT NULL DEFAULT 0,
	run_failed INTEGER NOT NULL DEFAULT 0,
	waiting_approval INTEGER NOT NULL DEFAULT 0,
	feedback_down INTEGER NOT NULL DEFAULT 0,
	summary TEXT,
	create_by VARCHAR(64),
	create_name VARCHAR(128),
	create_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
	last_modify_by VARCHAR(64),
	last_modify_name VARCHAR(128),
	last_modify_time TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
	deleted BOOLEAN DEFAULT false
);

COMMENT ON TABLE digital_employee_digest IS '数字员工每日工作汇总（按租户+员工+日期幂等）';

CREATE UNIQUE INDEX IF NOT EXISTS digital_employee_digest_uk_tenant_employee_date
	ON digital_employee_digest (tenant_id, employee_id, digest_date)
	WHERE deleted = false;

-- =============================================================================
-- Group A: 20260825_task_im_idempotency_tenant
-- =============================================================================

-- ============================================================================
-- 20260825_task_im_idempotency_tenant.sql
-- 目标库：PostgreSQL 12+ | 人工执行（本目录无 Flyway/Liquibase）| 本脚本不要自动执行
-- ============================================================================
--
-- 【用途】
--   将 agent_task_run / agent_im_message 的幂等部分唯一索引从 (idempotency_key)
--   改为 (tenant_id, idempotency_key)，避免跨租户共用同一幂等键时互相抢占或误判重复。
--
-- 【影响范围】
--   仅 DROP INDEX IF EXISTS 再 CREATE UNIQUE INDEX，不改表结构、不加列、不改行数据。
--   应用层幂等冲突仍按「插入撞唯一键 → 回查已有行」处理；唯一键语义从全局变为租户内。
--
-- 【列确认（不补列）】
--   agent_task_run.tenant_id
--     已有：服务治理/06-ai/数字员工方案-DDL/04-task-im.sql 建表即含 tenant_id；
--     实体 AgentTaskRun.tenantId 对应此列。
--   agent_im_message.tenant_id
--     已有（数字员工 DDL / 实体）：04-task-im.sql 建表含 tenant_id，
--     实体 AgentImMessage.tenantId 对应此列。
--     阻塞原因：business-agent/.../sql/pg/schema-v2.sql 与
--     20260708_agent_im_conversation.sql 的 CREATE TABLE agent_im_message 无 tenant_id。
--     若目标库来自该历史脚本且尚未加列，禁止在本脚本里 ADD COLUMN；
--     应跳过下方 uk_agent_im_message_idempotency 两句，先由独立迁移补齐 tenant_id 后再跑。
--
-- 【PostgreSQL 兼容】
--   DROP INDEX IF EXISTS 再 CREATE UNIQUE (tenant_id, idempotency_key) WHERE deleted = false。
--   部分唯一索引为 PG 语法；不使用 CONCURRENTLY，可放在事务中（会短暂锁表）。
--   重复执行：先 DROP 再 CREATE，索引名不变，可重跑。
--
-- 【执行前查重】有结果须先人工收敛，否则 CREATE UNIQUE 失败：
--   SELECT tenant_id, idempotency_key, count(*)
--     FROM agent_task_run
--    WHERE deleted = false
--    GROUP BY tenant_id, idempotency_key
--   HAVING count(*) > 1;
--
--   SELECT tenant_id, idempotency_key, count(*)
--     FROM agent_im_message
--    WHERE deleted = false
--    GROUP BY tenant_id, idempotency_key
--   HAVING count(*) > 1;
--
-- 【回滚】
--   DROP INDEX IF EXISTS uk_agent_task_run_idempotency;
--   CREATE UNIQUE INDEX uk_agent_task_run_idempotency
--     ON agent_task_run (idempotency_key)
--     WHERE deleted = false;
--
--   DROP INDEX IF EXISTS uk_agent_im_message_idempotency;
--   CREATE UNIQUE INDEX uk_agent_im_message_idempotency
--     ON agent_im_message (idempotency_key)
--     WHERE deleted = false;
--   （回滚后跨租户再次共享同一 idempotency_key 会冲突。）
-- ============================================================================

DROP INDEX IF EXISTS uk_agent_task_run_idempotency;
CREATE UNIQUE INDEX uk_agent_task_run_idempotency
	ON agent_task_run (tenant_id, idempotency_key)
	WHERE deleted = false;

DROP INDEX IF EXISTS uk_agent_im_message_idempotency;
CREATE UNIQUE INDEX uk_agent_im_message_idempotency
	ON agent_im_message (tenant_id, idempotency_key)
	WHERE deleted = false;

