-- Group A: 20260901_ai_tenant_isolation
-- =============================================================================

-- 20260901_ai_tenant_isolation: tenant_id columns / runtime tenant_id type only.
-- Skipped PLATFORM/scope unique-key rewrite (column is not on schema-v2 / entity).
-- Skipped production backfill of tenant_id='1'.

DO $$
DECLARE
	t text;
	tables text[] := ARRAY[
		'data_chat_session','data_chat_message','data_chat_turn','data_agentscope_session_state',
		'agent_channel_session_mapping','agent_collaborator','agent_model_config','agent_preset_question',
		'agent_orchestration_policy','agent_orchestration_run','agent_orchestration_step',
		'data_agent_memory_config','data_agent_model_structured_capability',
		'data_agent_visibility_policy','data_agent_visibility_grant','data_agent_visibility_application',
		'skill_knowledge','semantic_model','business_knowledge','skill_datasource',
		'skill_datasource_tables','skill_datasource_columns',
		'datasource_table','datasource_column','datasource_permission_rule','logical_relation',
		'model_config','model_asr_config','model_tts_config','model_realtime_voice_config',
		'realtime_voice_config','realtime_voice_session','tts_voice_profile','tts_voice_sample',
		'agent_execution_resource','agent_mcp_server','agent_mcp_tool','agent_mcp_exposure',
		'agent_usage_limit_policy','data_agent_route_profile',
		'agent_runtime_hook','agent_runtime_hook_log',
		'agent_notification_template','agent_notification_target','agent_notification_delivery',
		'agent_notification_authorization'
	];
BEGIN
	FOREACH t IN ARRAY tables LOOP
		IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = t) THEN
			EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS tenant_id VARCHAR(64)', t);
			EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (tenant_id)', t || '_idx_tenant_id', t);
		END IF;
	END LOOP;
END $$;

DO $$
DECLARE
	t text;
	tables text[] := ARRAY[
		'agent_runtime_run','agent_runtime_plan','agent_runtime_step','agent_runtime_step_attempt',
		'agent_runtime_invocation','agent_runtime_artifact','agent_runtime_event','agent_runtime_outbox',
		'agent_runtime_interruption','agent_runtime_approval','agent_runtime_budget_ledger'
	];
BEGIN
	FOREACH t IN ARRAY tables LOOP
		IF EXISTS (
			SELECT 1 FROM information_schema.columns
			WHERE table_schema = current_schema() AND table_name = t AND column_name = 'tenant_id'
			  AND data_type IN ('bigint','integer')
		) THEN
			EXECUTE format(
				'ALTER TABLE %I ALTER COLUMN tenant_id TYPE VARCHAR(64) USING CASE WHEN tenant_id IS NULL OR tenant_id = 0 THEN ''default'' ELSE tenant_id::text END',
				t);
		END IF;
	END LOOP;
END $$;

ALTER TABLE agent_runtime_run ADD COLUMN IF NOT EXISTS owner_type VARCHAR(32);
ALTER TABLE agent_runtime_run ADD COLUMN IF NOT EXISTS owner_id BIGINT;
ALTER TABLE agent_runtime_run ADD COLUMN IF NOT EXISTS digital_employee_id BIGINT;
ALTER TABLE agent_runtime_run ADD COLUMN IF NOT EXISTS tenant_id_str VARCHAR(64);
UPDATE agent_runtime_run SET owner_type = COALESCE(owner_type, 'CALLER') WHERE owner_type IS NULL;
UPDATE agent_runtime_run SET tenant_id_str = tenant_id WHERE tenant_id_str IS NULL AND tenant_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS agent_runtime_run_uk_tenant_owner_client_request
  ON agent_runtime_run(tenant_id, owner_type, owner_id, client_request_id)
  WHERE deleted = false;
CREATE INDEX IF NOT EXISTS agent_runtime_run_idx_tenant_digital_employee
  ON agent_runtime_run(tenant_id, digital_employee_id, id DESC)
  WHERE deleted = false AND digital_employee_id IS NOT NULL;

DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		WHERE table_schema = current_schema() AND table_name = 'agent_runtime_run' AND column_name = 'tenant_id_str'
	) THEN
		UPDATE agent_runtime_run
		SET tenant_id = tenant_id_str
		WHERE (tenant_id IS NULL OR tenant_id = '' OR tenant_id = '0')
		  AND tenant_id_str IS NOT NULL AND tenant_id_str <> '';
	END IF;
END $$;

