-- =============================================================================

-- 20260901_ai_tenant_isolation_add_missing_columns: tenant_id columns / runtime tenant_id type only.
-- Skipped PLATFORM/scope unique-key rewrite (column is not on schema-v2 / entity).
-- Skipped production backfill of tenant_id='1'.

DO $$
DECLARE
	t text;
	tables text[] := ARRAY[
		'data_chat_session','data_chat_message','data_chat_turn','data_agentscope_session_state',
		'agent_channel_session_mapping','agent_collaborator','agent_model_config','agent_preset_question',
		'agent_orchestration_policy','agent_orchestration_run','agent_orchestration_step',
		'data_agent_memory_config','data_agent_model_structured_capability',
		'data_agent_visibility_policy','data_agent_visibility_grant','data_agent_visibility_application',
		'skill_knowledge','semantic_model','business_knowledge','skill_datasource',
		'skill_datasource_tables','skill_datasource_columns',
		'datasource_table','datasource_column','datasource_permission_rule','logical_relation',
		'model_config','model_asr_config','model_tts_config','model_realtime_voice_config',
		'realtime_voice_config','realtime_voice_session','tts_voice_profile','tts_voice_sample',
		'agent_mcp_server','agent_mcp_tool','agent_mcp_exposure',
		'agent_usage_limit_policy','data_agent_route_profile',
		'agent_runtime_hook','agent_runtime_hook_log',
		'agent_notification_template','agent_notification_target','agent_notification_delivery',
		'agent_notification_authorization'
	];
BEGIN
	FOREACH t IN ARRAY tables LOOP
		IF to_regclass(t) IS NULL THEN
			CONTINUE;
		END IF;
		EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS tenant_id VARCHAR(64)', t);
		EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (tenant_id)', t || '_idx_tenant_id', t);
	END LOOP;
END $$;

-- =============================================================================
-- Group A: 20260903_skill_analysis_config
-- =============================================================================

-- ============================================================================
-- 20260903_skill_analysis_config.sql
-- 目标库：PostgreSQL 12+ | 人工执行 | 本脚本不要自动执行
-- ============================================================================
--
-- 【用途】
--   为 data_agent_skill_version 增加 analysis_config JSONB 列，把分析源图发布进
--   技能版本快照（与 datasource_config 同待遇）。并把该列加入
--   trg_data_agent_skill_version_validate / dataagent_validate_skill_version_ownership
--   的已发布版本不可变清单，防止绕过发布直接改 PUBLISHED 源图。
--   存量 PUBLISHED 版本不回填，默认 '{}'::jsonb；要用分析走新版本发布。
--
-- 【影响范围】
--   data_agent_skill_version.analysis_config 加列（NOT NULL DEFAULT '{}'）。
--   替换版本不可变校验函数与 BEFORE UPDATE OF 列清单。
--   QUERY 技能在草稿/已发布版本存在廉价合法 sources[]（非空 id + type 为
--   TABLE/FILE_TABLE/FILE_DOC）时，允许绑定多个启用 JDBC；无 analysisConfig
--   的 QUERY 仍只能一个启用 JDBC。完整校验（表白名单、关联键、FILE_ONLY）
--   以 Java AnalysisConfigParser 为准，本函数不是 JSON Schema。
--   不 DROP 无关对象。
--
-- 【回滚】
--   执行 20260903_skill_analysis_config_rollback.sql：恢复不可变清单、单 JDBC
--   触发器，并 DROP COLUMN。
--
-- 【PostgreSQL 兼容】
--   ADD COLUMN IF NOT EXISTS、JSONB、CREATE OR REPLACE FUNCTION、DROP/CREATE TRIGGER。
-- ============================================================================

ALTER TABLE data_agent_skill_version
	ADD COLUMN IF NOT EXISTS analysis_config JSONB NOT NULL DEFAULT '{}'::jsonb;

COMMENT ON COLUMN data_agent_skill_version.analysis_config IS '发布版本的分析源图快照（sources/associations/grain/nextFlows）';

CREATE OR REPLACE FUNCTION dataagent_validate_skill_version_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('PUBLISHED', 'RETIRED') THEN
      RAISE EXCEPTION 'Published Skill version cannot be deleted, versionId=%', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.skill_kind IS NULL
      OR NEW.execution_mode IS NULL
      OR NOT (
        (NEW.skill_kind = 'QA' AND NEW.execution_mode = 'KNOWLEDGE')
        OR (NEW.skill_kind = 'QUERY' AND NEW.execution_mode IN ('DETERMINISTIC', 'REACT'))
        OR (NEW.skill_kind IN ('ACTION', 'ORCHESTRATION') AND NEW.execution_mode = 'FLOW')
      ) THEN
    RAISE EXCEPTION 'Skill version kind/execution mode matrix is invalid, skillId=%, versionId=%',
      NEW.skill_id, NEW.id;
  END IF;
  SELECT tenant_id
    INTO v_skill_tenant
    FROM data_agent_skill
   WHERE id = NEW.skill_id
     AND COALESCE(deleted, false) = false;
  IF NOT FOUND OR NEW.tenant_id IS DISTINCT FROM v_skill_tenant THEN
    RAISE EXCEPTION 'Skill version tenant does not match its Skill, skillId=%, versionId=%', NEW.skill_id, NEW.id;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IN ('PUBLISHED', 'RETIRED') THEN
    IF NEW.status IS DISTINCT FROM OLD.status
        AND NOT (OLD.status = 'PUBLISHED' AND NEW.status = 'RETIRED') THEN
      RAISE EXCEPTION 'Published Skill version can only transition from PUBLISHED to RETIRED, versionId=%', OLD.id;
    END IF;
    IF NEW.deleted IS DISTINCT FROM OLD.deleted
        OR NEW.published_at IS DISTINCT FROM OLD.published_at
        OR NEW.published_by IS DISTINCT FROM OLD.published_by
        OR (
        NEW.skill_id IS DISTINCT FROM OLD.skill_id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.skill_kind IS DISTINCT FROM OLD.skill_kind
        OR NEW.execution_mode IS DISTINCT FROM OLD.execution_mode
        OR NEW.version_no IS DISTINCT FROM OLD.version_no
        OR NEW.skill_markdown IS DISTINCT FROM OLD.skill_markdown
        OR NEW.route_rules IS DISTINCT FROM OLD.route_rules
        OR NEW.knowledge_config IS DISTINCT FROM OLD.knowledge_config
        OR NEW.react_config IS DISTINCT FROM OLD.react_config
        OR NEW.flow_definition IS DISTINCT FROM OLD.flow_definition
        OR NEW.variables_schema IS DISTINCT FROM OLD.variables_schema
        OR NEW.flow_runtime_config IS DISTINCT FROM OLD.flow_runtime_config
        OR NEW.flow_policy_config IS DISTINCT FROM OLD.flow_policy_config
        OR NEW.resource_requirement IS DISTINCT FROM OLD.resource_requirement
        OR NEW.input_schema IS DISTINCT FROM OLD.input_schema
        OR NEW.output_schema IS DISTINCT FROM OLD.output_schema
        OR NEW.datasource_config IS DISTINCT FROM OLD.datasource_config
        OR NEW.semantic_config IS DISTINCT FROM OLD.semantic_config
        OR NEW.runtime_config IS DISTINCT FROM OLD.runtime_config
        OR NEW.analysis_config IS DISTINCT FROM OLD.analysis_config
        OR NEW.checksum IS DISTINCT FROM OLD.checksum
      ) THEN
      RAISE EXCEPTION 'Published Skill version is immutable; create a new draft version, versionId=%', OLD.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_skill_version_validate ON data_agent_skill_version;
CREATE TRIGGER trg_data_agent_skill_version_validate
BEFORE INSERT OR UPDATE OF tenant_id, skill_id, skill_kind, execution_mode, version_no, status, skill_markdown, route_rules, knowledge_config,
  react_config, flow_definition, variables_schema, flow_runtime_config, flow_policy_config, resource_requirement,
  input_schema, output_schema, datasource_config, semantic_config, runtime_config, analysis_config, checksum, deleted, published_at, published_by
ON data_agent_skill_version
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_version_ownership();

-- Multi-JDBC gate. Cheap structural check only: at least one source object with a
-- non-blank id and type TABLE|FILE_TABLE|FILE_DOC. Empty/`{}`/`[{}]` stay fail-closed
-- (one JDBC). Associations, whitelist, FILE_ONLY vs JOIN are validated in Java
-- (AnalysisConfigParser); this is not a full JSON schema.
CREATE OR REPLACE FUNCTION dataagent_skill_has_analysis_sources(p_skill_id BIGINT)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1
      FROM data_agent_skill_version v
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(v.analysis_config, '{}'::jsonb) -> 'sources') = 'array'
            THEN v.analysis_config -> 'sources'
          ELSE '[]'::jsonb
        END
      ) AS src
     WHERE v.skill_id = p_skill_id
       AND COALESCE(v.deleted, false) = false
       AND v.status IN ('DRAFT', 'PUBLISHED')
       AND jsonb_typeof(src) = 'object'
       AND COALESCE(btrim(src ->> 'id'), '') <> ''
       AND upper(src ->> 'type') IN ('TABLE', 'FILE_TABLE', 'FILE_DOC')
  );
$$;

CREATE OR REPLACE FUNCTION dataagent_validate_skill_datasource_ownership()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
  v_skill_tenant VARCHAR(64);
  v_skill_scope VARCHAR(32);
  v_skill_kind VARCHAR(32);
  v_datasource_tenant VARCHAR(64);
BEGIN
  SELECT tenant_id, scope, skill_kind
    INTO v_skill_tenant, v_skill_scope, v_skill_kind
    FROM data_agent_skill
   WHERE id = NEW.skill_id AND deleted = false;
  IF NOT FOUND OR v_skill_scope <> 'TENANT' OR v_skill_tenant IS NULL THEN
    RAISE EXCEPTION 'Skill datasource must belong to an active tenant Skill, skillId=%', NEW.skill_id;
  END IF;

  SELECT tenant_id
    INTO v_datasource_tenant
    FROM datasource
   WHERE id = NEW.datasource_id AND deleted = false;
  IF NOT FOUND OR v_datasource_tenant <> v_skill_tenant THEN
    RAISE EXCEPTION 'Datasource tenant does not match Skill tenant, skillId=%, datasourceId=%',
      NEW.skill_id, NEW.datasource_id;
  END IF;

  IF COALESCE(NEW.is_active, false) AND v_skill_kind = 'QUERY'
      AND NOT dataagent_skill_has_analysis_sources(NEW.skill_id) AND EXISTS (
    SELECT 1
      FROM skill_datasource existing
     WHERE existing.skill_id = NEW.skill_id
       AND existing.id <> COALESCE(NEW.id, -1)
       AND COALESCE(existing.is_active, false)
       AND COALESCE(existing.deleted, false) = false
  ) THEN
    RAISE EXCEPTION 'QUERY Skill can have only one active datasource, skillId=%', NEW.skill_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_skill_datasource_ownership ON skill_datasource;
CREATE TRIGGER trg_skill_datasource_ownership
BEFORE INSERT OR UPDATE OF skill_id, datasource_id, is_active, deleted ON skill_datasource
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_datasource_ownership();

CREATE OR REPLACE FUNCTION dataagent_validate_skill_shape()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.scope <> 'TENANT' OR NEW.tenant_id IS NULL THEN
    RAISE EXCEPTION 'Skill must belong to a tenant, skillId=%', NEW.id;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_version version
     WHERE version.skill_id = NEW.id
       AND version.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Skill tenant cannot differ from its versions, skillId=%', NEW.id;
  END IF;
  IF EXISTS (
    SELECT 1
      FROM data_agent_skill_binding binding
     WHERE binding.skill_id = NEW.id
       AND COALESCE(binding.deleted, false) = false
       AND binding.tenant_id IS DISTINCT FROM NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'Skill tenant cannot differ from its active bindings, skillId=%', NEW.id;
  END IF;
  IF NEW.skill_kind = 'QUERY'
      AND NOT dataagent_skill_has_analysis_sources(NEW.id)
      AND (
    SELECT count(*)
      FROM skill_datasource
     WHERE skill_id = NEW.id
       AND COALESCE(is_active, false)
       AND COALESCE(deleted, false) = false
  ) > 1 THEN
    RAISE EXCEPTION 'QUERY Skill can have only one active datasource, skillId=%', NEW.id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_data_agent_skill_shape ON data_agent_skill;
CREATE TRIGGER trg_data_agent_skill_shape
BEFORE UPDATE OF scope, tenant_id, skill_kind, deleted ON data_agent_skill
FOR EACH ROW EXECUTE FUNCTION dataagent_validate_skill_shape();

-- =============================================================================
-- Group A: 20260907_chat_runtime_thread_active
-- =============================================================================

-- ============================================================================
-- 会话层断点 P0：CHAT 一会话一轮部分唯一索引
-- 来源：docs/会话层断点恢复优化方案.md（v7 坑 2/18）
-- 日期：2026-09-07 | 目标库：PostgreSQL 12+ | 幂等：可重复执行
-- ============================================================================
--
-- 【用途】
--   agent_runtime_run 上部分唯一索引 agent_runtime_run_uk_chat_thread_active：
--   同一租户同一 thread_id，run_mode=CHAT 时同时最多一行非终态
--   （PENDING/RUNNING/WAITING_APPROVAL/WAITING_INPUT/CANCELLING）。
--   正确性闸门；应用层预检只减少无效插入。冲突后按 threadId 回查活跃行，报 SESSION_BUSY，
--   不得走幂等键回查（见 RuntimeRunServiceImpl.create）。
--
-- 【执行前影响检查】
--   有重复活跃行时 CREATE UNIQUE INDEX 失败，先人工收敛：
--     SELECT tenant_id, thread_id, count(*) AS active_rows
--     FROM agent_runtime_run
--     WHERE deleted = false
--       AND run_mode = 'CHAT'
--       AND thread_id IS NOT NULL
--       AND state IN ('PENDING','RUNNING','WAITING_APPROVAL','WAITING_INPUT','CANCELLING')
--     GROUP BY tenant_id, thread_id
--     HAVING count(*) > 1;
--
-- 【执行方式】
--   默认无 CONCURRENTLY，可整文件在事务/GUI 管道里执行（会短暂锁表）。
--   生产若要少锁：先单独跑上面的查重 SELECT，再单独（autocommit、一条语句、不要和
--   其它 SQL 一起选中）执行：
--     CREATE UNIQUE INDEX IF NOT EXISTS agent_runtime_run_uk_chat_thread_active
--       ON agent_runtime_run (tenant_id, thread_id)
--       WHERE deleted = false AND run_mode = 'CHAT' AND thread_id IS NOT NULL
--         AND state IN ('PENDING','RUNNING','WAITING_APPROVAL','WAITING_INPUT','CANCELLING');
--   DBeaver/DataGrip/JDBC 把多条 SQL 当 pipeline 时，CONCURRENTLY 会报
--   SQLSTATE 25001（cannot be executed within a pipeline / 不能在事务块中运行）。
--   若 CONCURRENTLY 中途失败，可能留下 indisvalid=false 的半成品，先单独
--   DROP INDEX CONCURRENTLY IF EXISTS agent_runtime_run_uk_chat_thread_active 再重建。
--
-- 【回滚】
--   见 20260907_chat_runtime_thread_active_rollback.sql
--
-- 【PG 兼容】
--   PostgreSQL 12+（部分唯一索引 + CONCURRENTLY）。MySQL 不支持部分索引。
--   tenant_id 列类型与表定义一致（BIGINT）；thread_id 为会话主键字符串。
-- ============================================================================

-- 0. 前置查重（只读；有结果先收敛再建模）
SELECT tenant_id, thread_id, count(*) AS active_rows
FROM agent_runtime_run
WHERE deleted = false
  AND run_mode = 'CHAT'
  AND thread_id IS NOT NULL
  AND state IN ('PENDING','RUNNING','WAITING_APPROVAL','WAITING_INPUT','CANCELLING')
GROUP BY tenant_id, thread_id
HAVING count(*) > 1;

-- 1. 一会话一轮（无 CONCURRENTLY，可与上文 SELECT / 下文 COMMENT 同批执行）
CREATE UNIQUE INDEX IF NOT EXISTS agent_runtime_run_uk_chat_thread_active
  ON agent_runtime_run (tenant_id, thread_id)
  WHERE deleted = false
    AND run_mode = 'CHAT'
    AND thread_id IS NOT NULL
    AND state IN ('PENDING','RUNNING','WAITING_APPROVAL','WAITING_INPUT','CANCELLING');

COMMENT ON INDEX agent_runtime_run_uk_chat_thread_active IS
  'CHAT 同一租户同一会话同时最多一行非终态运行；冲突由应用层回查后报 SESSION_BUSY';

-- =============================================================================
-- Local disk file registry (replaces Suite STS)
-- =============================================================================
CREATE TABLE IF NOT EXISTS agent_file (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id VARCHAR(64),
  original_name VARCHAR(512),
  content_type VARCHAR(255),
  size BIGINT,
  storage_path TEXT NOT NULL,
  create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS agent_file_idx_tenant_id ON agent_file (tenant_id);

COMMENT ON TABLE agent_file IS 'Local uploaded file registry';
COMMENT ON COLUMN agent_file.tenant_id IS 'Tenant id';
COMMENT ON COLUMN agent_file.original_name IS 'Original file name';
COMMENT ON COLUMN agent_file.content_type IS 'MIME type';
COMMENT ON COLUMN agent_file.size IS 'Size in bytes';
COMMENT ON COLUMN agent_file.storage_path IS 'Relative path under storage.directory';
COMMENT ON COLUMN agent_file.create_time IS 'Create time';
